public class Solution {
    public int mirrorReflection(int p, int q) {
        int g = gcd(p, q);
        // Number of extensions in x and y directions
        int m = q / g; // l / p
        int n = p / g; // l / q

        boolean mOdd = (m & 1) == 1;
        boolean nOdd = (n & 1) == 1;

        if (mOdd && !nOdd) {
            return 0; // (p,0)
        } else if (mOdd && nOdd) {
            return 1; // (p,p)
        } else if (!mOdd && nOdd) {
            return 2; // (0,p)
        }
        // This case should not occur with valid inputs
        return -1;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int tmp = a % b;
            a = b;
            b = tmp;
        }
        return a;
    }
}

