import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        // Encode obstacle coordinates into a hash set for O(1) lookup
        Set<Long> obstacleSet = new HashSet<>();
        for (int[] obs : obstacles) {
            long key = ((long) obs[0] << 32) | (obs[1] & 0xffffffffL);
            obstacleSet.add(key);
        }

        // Directions: 0 = north, 1 = east, 2 = south, 3 = west
        int[] dx = {0, 1, 0, -1};
        int[] dy = {1, 0, -1, 0};
        int dir = 0; // start facing north
        int x = 0, y = 0;
        long maxDistSq = 0;

        for (int cmd : commands) {
            if (cmd == -2) { // turn left
                dir = (dir + 3) % 4;
            } else if (cmd == -1) { // turn right
                dir = (dir + 1) % 4;
            } else { // move forward cmd steps (1 <= cmd <= 9)
                for (int step = 0; step < cmd; step++) {
                    int nx = x + dx[dir];
                    int ny = y + dy[dir];
                    long key = ((long) nx << 32) | (ny & 0xffffffffL);
                    if (obstacleSet.contains(key)) {
                        // obstacle encountered, stop this command
                        break;
                    }
                    x = nx;
                    y = ny;
                    long distSq = (long) x * x + (long) y * y;
                    if (distSq > maxDistSq) {
                        maxDistSq = distSq;
                    }
                }
            }
        }

        return (int) maxDistSq;
    }
}

