import java.util.*;

public class Solution {
    public int numMagicSquaresInside(int[][] grid) {
        if (grid == null || grid.length < 3 || grid[0].length < 3) {
            return 0;
        }
        int rows = grid.length;
        int cols = grid[0].length;
        int count = 0;
        for (int i = 0; i <= rows - 3; i++) {
            for (int j = 0; j <= cols - 3; j++) {
                if (isMagic(grid, i, j)) {
                    count++;
                }
            }
        }
        return count;
    }

    private boolean isMagic(int[][] g, int r, int c) {
        // quick check: center must be 5 for a 3x3 magic square using numbers 1..9
        if (g[r + 1][c + 1] != 5) {
            return false;
        }

        boolean[] seen = new boolean[10]; // indices 1..9
        int[] rows = new int[3];
        int[] cols = new int[3];
        int diag1 = 0, diag2 = 0;

        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                int val = g[r + i][c + j];
                // must be in 1..9 and distinct
                if (val < 1 || val > 9 || seen[val]) {
                    return false;
                }
                seen[val] = true;

                rows[i] += val;
                cols[j] += val;
                if (i == j) {
                    diag1 += val;
                }
                if (i + j == 2) {
                    diag2 += val;
                }
            }
        }

        // all rows, columns, and diagonals must sum to 15
        for (int i = 0; i < 3; i++) {
            if (rows[i] != 15 || cols[i] != 15) {
                return false;
            }
        }
        return diag1 == 15 && diag2 == 15;
    }
}

