import java.util.*;

public class Solution {
    private int[] parent;
    private int[] size;

    private int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    private void union(int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return;
        if (size[ra] < size[rb]) {
            int tmp = ra;
            ra = rb;
            rb = tmp;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
    }

    public int largestIsland(int[][] grid) {
        int n = grid.length;
        int total = n * n;
        parent = new int[total];
        size = new int[total];
        for (int i = 0; i < total; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        // Union all adjacent 1s
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int id = i * n + j;
                    for (int[] d : dirs) {
                        int ni = i + d[0];
                        int nj = j + d[1];
                        if (ni >= 0 && ni < n && nj >= 0 && nj < n && grid[ni][nj] == 1) {
                            int nid = ni * n + nj;
                            union(id, nid);
                        }
                    }
                }
            }
        }

        // Current maximum island size
        int max = 0;
        for (int i = 0; i < total; i++) {
            if (grid[i / n][i % n] == 1) {
                int root = find(i);
                max = Math.max(max, size[root]);
            }
        }

        // If the whole grid is already 1s
        if (max == total) return total;

        // Try flipping each 0 to 1
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    Set<Integer> seen = new HashSet<>();
                    int sum = 1; // the flipped cell
                    for (int[] d : dirs) {
                        int ni = i + d[0];
                        int nj = j + d[1];
                        if (ni >= 0 && ni < n && nj >= 0 && nj < n && grid[ni][nj] == 1) {
                            int nid = ni * n + nj;
                            int root = find(nid);
                            if (seen.add(root)) {
                                sum += size[root];
                            }
                        }
                    }
                    max = Math.max(max, sum);
                }
            }
        }

        return max;
    }
}

