                if (Character.isDigit(c)) {
                    digits.append(c);
                }
            }
            int n = digits.length();
            String local = digits.substring(n - 4);
            if (n == 10) {
                return "***-***-" + local;
            } else {
                StringBuilder sb = new StringBuilder();
                sb.append('+');
                for (int i = 0; i < n - 10; i++) {
                    sb.append('*');
                }
                sb.append("-***-***-").append(local);
                return sb.toString();
            }
        }
    }
}

