public class Solution {
    public int maxDistToClosest(int[] seats) {
        int maxDist = 0;
        int lastOccupied = -1;
        int n = seats.length;

        for (int i = 0; i < n; i++) {
            if (seats[i] == 1) {
                if (lastOccupied == -1) {
                    // Leading empty seats
                    maxDist = i;
                } else {
                    // Seats between two occupied seats
                    int dist = (i - lastOccupied) / 2;
                    if (dist > maxDist) {
                        maxDist = dist;
                    }
                }
                lastOccupied = i;
            }
        }

        // Trailing empty seats
        if (seats[n - 1] == 0) {
            int trailingDist = n - 1 - lastOccupied;
            if (trailingDist > maxDist) {
                maxDist = trailingDist;
            }
        }

        return maxDist;
    }
}

