import java.util.*;

public class Solution {
    private static final int[] A_DECREASE = {4, 3, 2, 1};
    private static final int[] B_DECREASE = {0, 1, 2, 3};
    private static final double EPS = 1e-12;
    private double[][] memo;
    private int maxSize;

    public double soupServings(int n) {
        // For large n the probability approaches 1.
        if (n >= 4800) {
            return 1.0;
        }
        int m = (n + 24) / 25; // scale down to units of 25 ml
        maxSize = m + 1; // we need indices up to m (including 0)
        memo = new double[maxSize + 1][maxSize + 1];
        for (double[] row : memo) {
            Arrays.fill(row, -1.0);
        }
        return dfs(m, m);
    }

    private double dfs(int a, int b) {
        if (a <= 0 && b <= 0) {
            return 0.5;
        }
        if (a <= 0) {
            return 1.0;
        }
        if (b <= 0) {
            return 0.0;
        }
        if (a < maxSize && b < maxSize && memo[a][b] >= 0) {
            return memo[a][b];
        }
        double prob = 0.0;
        for (int i = 0; i < 4; i++) {
            prob += dfs(a - A_DECREASE[i], b - B_DECREASE[i]);
        }
        prob *= 0.25;
        if (a < maxSize && b < maxSize) {
            memo[a][b] = prob;
        }
        return prob;
    }
}

