public class Solution {
    public double new21Game(int n, int k, int w) {
        // Edge cases
        if (k == 0) {
            // Alice stops immediately with 0 points
            return 1.0;
        }
        if (n >= k + w - 1) {
            // Even the maximum possible final score is <= n
            return 1.0;
        }
        if (n < k) {
            // Alice must reach at least k points, which is > n
            return 0.0;
        }

        double[] dp = new double[n + 1];
        dp[0] = 1.0;
        double windowSum = 1.0; // sum of the last w probabilities that can lead to current score
        double result = 0.0;

        for (int i = 1; i <= n; i++) {
            dp[i] = windowSum / w;

            if (i >= k) {
                // i is a possible final score
                result += dp[i];
            } else {
                // i is still a transient state; it can contribute to future scores
                windowSum += dp[i];
            }

            // Remove the probability that is now out of the sliding window
            if (i - w >= 0) {
                windowSum -= dp[i - w];
            }
        }

        return result;
    }
}

