import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Solution {
    public List<String> findAndReplacePattern(String[] words, String pattern) {
        List<String> result = new ArrayList<>();
        for (String word : words) {
            if (matches(word, pattern)) {
                result.add(word);
            }
        }
        return result;
    }

    private boolean matches(String word, String pattern) {
        if (word.length() != pattern.length()) {
            return false;
        }
        int[] mapPatternToWord = new int[26];
        int[] mapWordToPattern = new int[26];
        Arrays.fill(mapPatternToWord, -1);
        Arrays.fill(mapWordToPattern, -1);
        for (int i = 0; i < word.length(); i++) {
            int pIdx = pattern.charAt(i) - 'a';
            int wIdx = word.charAt(i) - 'a';
            if (mapPatternToWord[pIdx] == -1 && mapWordToPattern[wIdx] == -1) {
                mapPatternToWord[pIdx] = wIdx;
                mapWordToPattern[wIdx] = pIdx;
            } else if (mapPatternToWord[pIdx] != wIdx || mapWordToPattern[wIdx] != pIdx) {
                return false;
            }
        }
        return true;
    }
}

