import java.util.TreeMap;

public class Solution {
    public boolean isNStraightHand(int[] hand, int groupSize) {
        if (groupSize == 1) {
            return true;
        }
        if (hand == null || hand.length == 0 || hand.length % groupSize != 0) {
            return false;
        }

        // Count frequencies using a sorted map
        TreeMap<Integer, Integer> freq = new TreeMap<>();
        for (int card : hand) {
            freq.put(card, freq.getOrDefault(card, 0) + 1);
        }

        // Process cards from smallest to largest
        while (!freq.isEmpty()) {
            int start = freq.firstKey(); // smallest remaining card
            for (int i = 0; i < groupSize; i++) {
                int cur = start + i;
                Integer count = freq.get(cur);
                if (count == null) {
                    return false; // missing required card
                }
                if (count == 1) {
                    freq.remove(cur);
                } else {
                    freq.put(cur, count - 1);
                }
            }
        }
        return true;
    }
}

