import java.util.*;

public class Solution {
    private static class UnionFind {
        private final int[] parent;
        private final int[] size;

        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) return;
            if (size[rootA] < size[rootB]) {
                int tmp = rootA;
                rootA = rootB;
                rootB = tmp;
            }
            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }

        int getSize(int x) {
            int root = find(x);
            return size[root];
        }
    }

    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int total = m * n;
        int top = total; // virtual top node index

        UnionFind uf = new UnionFind(total + 1);

        // copy grid and apply hits (mark bricks to be removed)
        int[][] copy = new int[m][n];
        for (int i = 0; i < m; i++) {
            System.arraycopy(grid[i], 0, copy[i], 0, n);
        }
        for (int[] hit : hits) {
            int r = hit[0];
            int c = hit[1];
            if (copy[r][c] == 1) {
                copy[r][c] = 0; // remove brick
            }
        }

        // initial union of remaining bricks
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (copy[i][j] == 1) {
                    int idx = i * n + j;
                    // connect to top if in first row
                    if (i == 0) {
                        uf.union(idx, top);
                    }
                    // union with up and left neighbors (to avoid double work)
                    if (i > 0 && copy[i - 1][j] == 1) {
                        uf.union(idx, (i - 1) * n + j);
                    }
                    if (j > 0 && copy[i][j - 1] == 1) {
                        uf.union(idx, i * n + (j - 1));
                    }
                }
            }
        }

        int[] result = new int[hits.length];
        int[] dirs = {-1, 0, 1, 0, -1};

        for (int k = hits.length - 1; k >= 0; k--) {
            int r = hits[k][0];
            int c = hits[k][1];
            if (grid[r][c] == 0) {
                // there was no brick originally
                result[k] = 0;
                continue;
            }

            int before = uf.getSize(top);

            int idx = r * n + c;
            // restore the brick
            copy[r][c] = 1;

            // if it's in the top row, connect to virtual top
            if (r == 0) {
                uf.union(idx, top);
            }

            // union with all four neighbors if they have bricks
            for (int d = 0; d < 4; d++) {
                int nr = r + dirs[d];
                int nc = c + dirs[d + 1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && copy[nr][nc] == 1) {
                    uf.union(idx, nr * n + nc);
                }
            }

            int after = uf.getSize(top);
            // bricks that became stable due to this addition (excluding the brick itself)
            int fallen = Math.max(0, after - before - 1);
            result[k] = fallen;
        }

        return result;
    }
}

