import java.util.Map;
import java.util.HashMap;
import java.util.Arrays;

public class Solution {
    public String findReplaceString(String s, int[] indices, String[] sources, String[] targets) {
        // Map each index to its source and target
        Map<Integer, Integer> indexToPos = new HashMap<>();
        for (int i = 0; i < indices.length; i++) {
            indexToPos.put(indices[i], i);
        }

        // Sort indices to process from left to right
        int[] sortedIndices = indices.clone();
        Arrays.sort(sortedIndices);

        StringBuilder result = new StringBuilder();
        int cur = 0; // current position in original string

        for (int idx : sortedIndices) {
            int pos = indexToPos.get(idx);
            String src = sources[pos];
            String tgt = targets[pos];

            // If the source matches the substring at idx, perform replacement
            if (s.startsWith(src, idx)) {
                // Append unchanged part
                result.append(s, cur, idx);
                // Append target
                result.append(tgt);
                // Move current pointer past the replaced source
                cur = idx + src.length();
            }
            // If it doesn't match, do nothing; the original characters will be handled later
        }

        // Append any remaining part of the original string
        result.append(s.substring(cur));

        return result.toString();
    }
}

