public class Solution {
    public int surfaceArea(int[][] grid) {
        int n = grid.length;
        int area = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int v = grid[i][j];
                if (v > 0) {
                    // top and bottom
                    area += 2;
                    // four sides
                    area += 4 * v;
                    // subtract shared faces with north neighbor
                    if (i > 0) {
                        area -= 2 * Math.min(v, grid[i - 1][j]);
                    }
                    // subtract shared faces with west neighbor
                    if (j > 0) {
                        area -= 2 * Math.min(v, grid[i][j - 1]);
                    }
                }
            }
        }
        return area;
    }
}

