public class Solution {
    public int[][] spiralMatrixIII(int rows, int cols, int y, int x) {
        int total = rows * cols;
        int[][] result = new int[total][2];
        int idx = 0;

        // Directions: east, south, west, north
        int[][] dirs = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        int dirIdx = 0;
        int steps = 1;
        int r = y;
        int c = x;

        // Record the starting position if it's inside the grid
        if (r >= 0 && r < rows && c >= 0 && c < cols) {
            result[idx][0] = r;
            result[idx][1] = c;
            idx++;
        }

        while (idx < total) {
            // Each step length is used for two directions
            for (int repeat = 0; repeat < 2; repeat++) {
                int dr = dirs[dirIdx][0];
                int dc = dirs[dirIdx][1];
                for (int s = 0; s < steps; s++) {
                    r += dr;
                    c += dc;
                    if (r >= 0 && r < rows && c >= 0 && c < cols) {
                        result[idx][0] = r;
                        result[idx][1] = c;
                        idx++;
                        if (idx == total) {
                            break;
                        }
                    }
                }
                dirIdx = (dirIdx + 1) % 4;
                if (idx == total) {
                    break;
                }
            }
            steps++;
        }

        return result;
    }
}

