public class Solution {
    public String pushDominoes(String dominoes) {
        // Add sentinel characters to simplify edge handling
        StringBuilder extended = new StringBuilder();
        extended.append('L');
        extended.append(dominoes);
        extended.append('R');
        char[] symbols = extended.toString().toCharArray();

        StringBuilder result = new StringBuilder();
        int i = 0;
        while (i < symbols.length - 1) {
            int j = i + 1;
            while (j < symbols.length && symbols[j] == '.') {
                j++;
            }
            char left = symbols[i];
            char right = symbols[j];
            int gap = j - i - 1; // number of '.' between i and j

            if (left == right) {
                // Same direction: all become that direction
                result.append(left);
                for (int k = 0; k < gap; k++) {
                    result.append(left);
                }
            } else if (left == 'L' && right == 'R') {
                // Forces away from each other: remain upright
                result.append('L');
                for (int k = 0; k < gap; k++) {
                    result.append('.');
                }
            } else { // left == 'R' && right == 'L'
                // Forces towards each other
                result.append('R');
                for (int k = 0; k < gap; k++) {
                    if (k < gap / 2) {
                        result.append('R');
                    } else if (k == gap / 2 && (gap % 2 == 1)) {
                        result.append('.');
                    } else {
                        result.append('L');
                    }
                }
            }
            i = j;
        }

        // Remove the sentinel characters at the beginning and end
        return result.substring(1, result.length() - 1);
    }
}

