public class Solution {
    public int subarrayBitwiseORs(int[] arr) {
        Set<Integer> resultSet = new HashSet<>();
        Set<Integer> prev = new HashSet<>();
        for (int num : arr) {
            Set<Integer> cur = new HashSet<>();
            cur.add(num);
            for (int val : prev) {
