public class Solution {
    public int projectionArea(int[][] grid) {
        int n = grid.length;
        int top = 0;
        int front = 0; // yz plane: max of each column
        int side = 0;  // zx plane: max of each row

        // top view: count cells with value > 0
        for (int i = 0; i < n; i++) {
            int rowMax = 0;
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > 0) {
                    top++;
                }
                rowMax = Math.max(rowMax, grid[i][j]);
            }
            side += rowMax; // max in this row for side view
        }

        // front view: max of each column
        for (int j = 0; j < n; j++) {
            int colMax = 0;
            for (int i = 0; i < n; i++) {
                colMax = Math.max(colMax, grid[i][j]);
            }
            front += colMax;
        }

        return top + front + side;
    }
}

