import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int maxProfitAssignment(int[] difficulty, int[] profit, int[] worker) {
        int n = difficulty.length;
        // Pair difficulty with profit
        int[][] jobs = new int[n][2];
        for (int i = 0; i < n; i++) {
            jobs[i][0] = difficulty[i];
            jobs[i][1] = profit[i];
        }
        // Sort jobs by difficulty ascending
        Arrays.sort(jobs, Comparator.comparingInt(a -> a[0]));

        // Build prefix max profit array
        int[] diffSorted = new int[n];
        int[] maxProfitUpTo = new int[n];
        int maxSoFar = 0;
        for (int i = 0; i < n; i++) {
            diffSorted[i] = jobs[i][0];
            maxSoFar = Math.max(maxSoFar, jobs[i][1]);
            maxProfitUpTo[i] = maxSoFar;
        }

        // Sort workers to possibly improve cache locality (optional)
        Arrays.sort(worker);

        int total = 0;
        for (int ability : worker) {
            // Find rightmost index where diffSorted[idx] <= ability
            int idx = upperBound(diffSorted, ability) - 1;
            if (idx >= 0) {
                total += maxProfitUpTo[idx];
            }
        }
        return total;
    }

    // Returns first index > target (i.e., upper bound)
    private int upperBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] <= target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

