public class Solution {
    public int maxIncreaseKeepingSkyline(int[][] grid) {
        int n = grid.length;
        int[] rowMax = new int[n];
        int[] colMax = new int[n];

        // Compute maximum height for each row and column
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] > rowMax[r]) {
                    rowMax[r] = grid[r][c];
                }
                if (grid[r][c] > colMax[c]) {
                    colMax[c] = grid[r][c];
                }
            }
        }

        int totalIncrease = 0;
        // Calculate possible increase for each building
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                int allowedHeight = Math.min(rowMax[r], colMax[c]);
                totalIncrease += allowedHeight - grid[r][c];
            }
        }

        return totalIncrease;
    }
}

