public class Solution {
    public TreeNode increasingBST(final TreeNode root) {
        TreeNode dummy = new TreeNode(0);
        TreeNode[] prev = new TreeNode[]{dummy};
        inorder(root, prev);
        return dummy.right;
    }

    private void inorder(TreeNode node, TreeNode[] prev) {
        if (node == null) {
            return;
        }
        inorder(node.left, prev);
        // detach left child
        node.left = null;
        // attach to the right of previous node
        prev[0].right = node;
        // move prev pointer
        prev[0] = node;
        inorder(node.right, prev);
    }
}

