import java.util.*;

public class Solution {
    public boolean reorderedPowerOf2(int n) {
        if (n == 0) {
            return false;
        }
        int[] targetCount = digitCount(n);
        // generate powers of two up to 10 digits (since int max has 10 digits)
        for (int i = 0; i < 31; i++) { // 2^30 is the largest power of two fitting in int positive range
            int power = 1 << i;
            if (Arrays.equals(targetCount, digitCount(power))) {
                return true;
            }
        }
        // also consider 2^30 = 1073741824 (10 digits) which fits in int, already covered.
        // For completeness, check 2^31 as long (2147483648) which exceeds int range but may match digit multiset of n if n is larger than int max (not possible here).
        long powerLong = 1L << 31;
        if (powerLong <= Integer.MAX_VALUE) {
            // unreachable branch
        } else {
            if (Arrays.equals(targetCount, digitCount((int) powerLong))) {
                return true;
            }
        }
        return false;
    }

    private int[] digitCount(int num) {
        int[] cnt = new int[10];
        while (num > 0) {
            cnt[num % 10]++;
            num /= 10;
        }
        return cnt;
    }
}

