public class Solution {
    public int expressiveWords(String s, String[] words) {
        int stretchyCount = 0;
        for (String word : words) {
            if (isStretchy(s, word)) {
                stretchyCount++;
            }
        }
        return stretchyCount;
    }

    private boolean isStretchy(String s, String word) {
        int i = 0, j = 0;
        int n = s.length(), m = word.length();

        while (i < n && j < m) {
            char cs = s.charAt(i);
            char cw = word.charAt(j);
            if (cs != cw) {
                return false;
            }

            int countS = 0;
            while (i < n && s.charAt(i) == cs) {
                i++;
                countS++;
            }

            int countW = 0;
            while (j < m && word.charAt(j) == cw) {
                j++;
                countW++;
            }

            if (countS < 3) {
                if (countS != countW) {
                    return false;
                }
            } else {
                if (countW > countS) {
                    return false;
                }
                // countW can be any value from 1 to countS when countS >= 3
                if (countW == 0) {
                    return false;
                }
            }
        }

        // Both strings must be fully consumed
        return i == n && j == m;
    }
}

