public class Solution {
    public int primePalindrome(int n) {
        if (n <= 2) return 2;
        if (n <= 3) return 3;
        if (n <= 5) return 5;
        if (n <= 7) return 7;
        if (n <= 11) return 11;

        for (int i = 1; ; i++) {
            int p = createPalindrome(i, true); // odd length palindrome
            if (p > 200_000_000) break;
            if (p >= n && isPrime(p)) {
                return p;
            }
        }
        return -1; // should never reach here with given constraints
    }

    private int createPalindrome(int input, boolean oddLength) {
        int n = input;
        int pal = input;
        if (oddLength) {
            n /= 10;
        }
        while (n > 0) {
            pal = pal * 10 + (n % 10);
            n /= 10;
        }
        return pal;
    }

    private boolean isPrime(int num) {
        if (num < 2) return false;
        if (num % 2 == 0) return num == 2;
        int limit = (int) Math.sqrt(num);
        for (int i = 3; i <= limit; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

