import java.util.HashSet;
import java.util.PriorityQueue;
import java.util.Set;

public class Solution {
    private static class Node {
        String str;
        int steps;
        int est; // heuristic

        Node(String str, int steps, int est) {
            this.str = str;
            this.steps = steps;
            this.est = est;
        }

        int totalCost() {
            return steps + est;
        }
    }

    public int kSimilarity(String a, String b) {
        if (a.equals(b)) {
            return 0;
        }

        PriorityQueue<Node> pq = new PriorityQueue<>((n1, n2) -> {
            int c1 = n1.totalCost();
            int c2 = n2.totalCost();
            if (c1 != c2) return Integer.compare(c1, c2);
            return Integer.compare(n1.steps, n2.steps);
        });

        Set<String> visited = new HashSet<>();
        int initHeuristic = heuristic(a, b);
        pq.offer(new Node(a, 0, initHeuristic));
        visited.add(a);

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            String curStr = cur.str;
            int curSteps = cur.steps;

            if (curStr.equals(b)) {
                return curSteps;
            }

            // find first mismatched position
            int i = 0;
            while (i < curStr.length() && curStr.charAt(i) == b.charAt(i)) {
                i++;
            }
            if (i == curStr.length()) {
                continue; // should not happen because we would have returned earlier
            }

            char targetChar = b.charAt(i);
            for (int j = i + 1; j < curStr.length(); j++) {
                if (curStr.charAt(j) == targetChar && curStr.charAt(j) != b.charAt(j)) {
                    String next = swap(curStr, i, j);
                    if (!visited.contains(next)) {
                        visited.add(next);
                        int h = heuristic(next, b);
                        pq.offer(new Node(next, curSteps + 1, h));
                    }
                }
            }
        }

        return -1; // should never reach here because a and b are anagrams
    }

    private int heuristic(String s, String target) {
        int mismatches = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != target.charAt(i)) {
                mismatches++;
            }
        }
        // each swap can fix at most two mismatches
        return (mismatches + 1) / 2;
    }

    private String swap(String s, int i, int j) {
        char[] arr = s.toCharArray();
        char tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
        return new String(arr);
    }
}

