import java.util.*;

public class Solution {
    private static class UnionFind {
        private final int[] parent;
        private final int[] rank;
        private int count;

        UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            count = n;
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) return;
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
            count--;
        }

        int getCount() {
            return count;
        }
    }

    private boolean areSimilar(String a, String b) {
        int diff = 0;
        int first = -1, second = -1;
        for (int i = 0; i < a.length(); i++) {
            if (a.charAt(i) != b.charAt(i)) {
                diff++;
                if (first == -1) {
                    first = i;
                } else if (second == -1) {
                    second = i;
                } else {
                    // more than 2 differences
                    return false;
                }
            }
        }
        if (diff == 0) return true;               // identical
        if (diff != 2) return false;              // must be exactly 2 differences
        // check if swapping makes them equal
        return a.charAt(first) == b.charAt(second) && a.charAt(second) == b.charAt(first);
    }

    public int numSimilarGroups(String[] strs) {
        int n = strs.length;
        if (n == 0) return 0;
        UnionFind uf = new UnionFind(n);
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (uf.find(i) != uf.find(j) && areSimilar(strs[i], strs[j])) {
                    uf.union(i, j);
                }
            }
        }
        return uf.getCount();
    }
}

