        while (left < right) {
            int mid = left + (right - left) / 2;
            long hoursNeeded = 0;
            for (int p : piles) {
                hoursNeeded += (p + mid - 1) / mid; // ceil division
                if (hoursNeeded > h) {
                    break; // no need to continue if already exceeds h
                }
            }
            if (hoursNeeded <= h) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }
}

