import java.util.*;

public class Solution {
    public int uniqueLetterString(String s) {
        int n = s.length();
        // Map each character to list of its occurrence indices
        Map<Character, List<Integer>> idxMap = new HashMap<>();
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            idxMap.computeIfAbsent(c, k -> new ArrayList<>()).add(i);
        }

        long total = 0L;
        for (List<Integer> positions : idxMap.values()) {
            int size = positions.size();
            for (int i = 0; i < size; i++) {
                int cur = positions.get(i);
                int prev = (i == 0) ? -1 : positions.get(i - 1);
                int next = (i == size - 1) ? n : positions.get(i + 1);
                long contribution = (long) (cur - prev) * (next - cur);
                total += contribution;
            }
        }
        return (int) total;
    }
}

