public class Solution {
    public int matrixScore(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int score = 0;

        // Ensure the first column is all 1s by conceptually flipping rows where it's 0
        for (int j = 0; j < n; j++) {
            int ones = 0;
            for (int i = 0; i < m; i++) {
                // If the first element of the row was flipped, invert the current cell
                int val = grid[i][j];
                if (grid[i][0] == 0) {
                    val ^= 1;
                }
                if (val == 1) {
                    ones++;
                }
            }
            // For the first column we must keep all 1s, for others choose the better side
            int maxOnes = (j == 0) ? ones : Math.max(ones, m - ones);
            score += maxOnes << (n - 1 - j);
        }

        return score;
    }
}

