import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int[] sumOfDistancesInTree(int n, int[][] edges) {
        if (n == 0) return new int[0];
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int a = e[0];
            int b = e[1];
            graph[a].add(b);
            graph[b].add(a);
        }

        int[] subtreeSize = new int[n];
        int[] ans = new int[n];
        // First DFS to compute subtree sizes and answer for root (node 0)
        dfs1(0, -1, graph, subtreeSize, ans);
        // Second DFS to compute answers for all other nodes
        dfs2(0, -1, graph, subtreeSize, ans, n);
        return ans;
    }

    private void dfs1(int node, int parent, List<Integer>[] graph, int[] subtreeSize, int[] ans) {
        subtreeSize[node] = 1; // count itself
        for (int nei : graph[node]) {
            if (nei == parent) continue;
            dfs1(nei, node, graph, subtreeSize, ans);
            subtreeSize[node] += subtreeSize[nei];
            ans[0] += subtreeSize[nei]; // distance contribution from child subtree
        }
    }

    private void dfs2(int node, int parent, List<Integer>[] graph, int[] subtreeSize, int[] ans, int n) {
        for (int nei : graph[node]) {
            if (nei == parent) continue;
            // Move root from node to nei
            ans[nei] = ans[node] - subtreeSize[nei] + (n - subtreeSize[nei]);
            dfs2(nei, node, graph, subtreeSize, ans, n);
        }
    }
}

