import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class Solution {
    private static final int MOD = 1_000_000_007;
    private int[] xs;
    private int[] count;
    private long[] coverLen;

    private static class Event implements Comparable<Event> {
        int y;
        int x1;
        int x2;
        int type; // +1 for entering, -1 for leaving

        Event(int y, int x1, int x2, int type) {
            this.y = y;
            this.x1 = x1;
            this.x2 = x2;
            this.type = type;
        }

        @Override
        public int compareTo(Event o) {
            return Integer.compare(this.y, o.y);
        }
    }

    public int rectangleArea(int[][] rectangles) {
        List<Integer> xList = new ArrayList<>();
        List<Event> events = new ArrayList<>();

        for (int[] rect : rectangles) {
            int x1 = rect[0], y1 = rect[1], x2 = rect[2], y2 = rect[3];
            xList.add(x1);
            xList.add(x2);
            events.add(new Event(y1, x1, x2, 1));
            events.add(new Event(y2, x1, x2, -1));
        }

        // coordinate compression
        Collections.sort(xList);
        int m = 0;
        int[] temp = new int[xList.size()];
        for (int v : xList) {
            if (m == 0 || v != temp[m - 1]) {
                temp[m++] = v;
            }
        }
        xs = Arrays.copyOf(temp, m);

        // build segment tree
        int size = xs.length * 4;
        count = new int[size];
        coverLen = new long[size];

        Collections.sort(events);

        long area = 0;
        int prevY = events.get(0).y;
        long curCover = 0;

        for (Event e : events) {
            int curY = e.y;
            long deltaY = curY - prevY;
            if (deltaY != 0) {
                area = (area + (curCover % MOD) * (deltaY % MOD)) % MOD;
                prevY = curY;
            }
            int l = Arrays.binarySearch(xs, e.x1);
            int r = Arrays.binarySearch(xs, e.x2);
            update(1, 0, xs.length - 1, l, r, e.type);
            curCover = coverLen[1];
        }

        return (int) (area % MOD);
    }

    private void update(int node, int l, int r, int ql, int qr, int val) {
        if (qr <= l || r <= ql) {
            return;
        }
        if (ql <= l && r <= qr) {
            count[node] += val;
            pushUp(node, l, r);
            return;
        }
        int mid = (l + r) >>> 1;
        update(node << 1, l, mid, ql, qr, val);
        update(node << 1 | 1, mid, r, ql, qr, val);
        pushUp(node, l, r);
    }

    private void pushUp(int node, int l, int r) {
        if (count[node] > 0) {
            coverLen[node] = (long) xs[r] - xs[l];
        } else if (l + 1 == r) {
            coverLen[node] = 0;
        } else {
            coverLen[node] = coverLen[node << 1] + coverLen[node << 1 | 1];
        }
    }
}

