import com_github_leetcode.TreeNode;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

public class Solution {
    public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        // Map each node to its parent
        Map<TreeNode, TreeNode> parentMap = new HashMap<>();
        buildParentMap(root, null, parentMap);

        // BFS from target
        Deque<TreeNode> queue = new ArrayDeque<>();
        Set<TreeNode> visited = new HashSet<>();

        queue.offer(target);
        visited.add(target);
        int distance = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            if (distance == k) {
                List<Integer> result = new ArrayList<>();
                for (TreeNode node : queue) {
                    result.add(node.val);
                }
                return result;
            }
            for (int i = 0; i < size; i++) {
                TreeNode cur = queue.poll();
                // left child
                if (cur.left != null && visited.add(cur.left)) {
                    queue.offer(cur.left);
                }
                // right child
                if (cur.right != null && visited.add(cur.right)) {
                    queue.offer(cur.right);
                }
                // parent
                TreeNode parent = parentMap.get(cur);
                if (parent != null && visited.add(parent)) {
                    queue.offer(parent);
                }
            }
            distance++;
        }

        // If k is larger than the height of the tree, return empty list
        return new ArrayList<>();
    }

    private void buildParentMap(TreeNode node, TreeNode parent, Map<TreeNode, TreeNode> map) {
        if (node == null) {
            return;
        }
        map.put(node, parent);
        buildParentMap(node.left, node, map);
        buildParentMap(node.right, node, map);
    }
}

