import java.util.*;

public class Solution {
    public boolean buddyStrings(String s, String goal) {
        if (s == null || goal == null) return false;
        int n = s.length();
        if (n != goal.length()) return false;
        if (n < 2) return false;

        if (s.equals(goal)) {
            // Need at least one duplicate character to make a swap that keeps the string unchanged
            int[] count = new int[26];
            for (int i = 0; i < n; i++) {
                int idx = s.charAt(i) - 'a';
                count[idx]++;
                if (count[idx] > 1) {
                    return true;
                }
            }
            return false;
        }

        List<Integer> diff = new ArrayList<>(2);
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) != goal.charAt(i)) {
                diff.add(i);
                if (diff.size() > 2) {
                    return false;
                }
            }
        }

        if (diff.size() != 2) {
            return false;
        }

        int i = diff.get(0);
        int j = diff.get(1);
        return s.charAt(i) == goal.charAt(j) && s.charAt(j) == goal.charAt(i);
    }
}

