public class Solution {
    public String shiftingLetters(String s, int[][] shifts) {
        int n = s.length();
        int[] diff = new int[n + 1]; // extra space for easier handling

        for (int[] shift : shifts) {
            int start = shift[0];
            int end = shift[1];
            int direction = shift[2];
            int delta = direction == 1 ? 1 : -1;

            diff[start] += delta;
            if (end + 1 < n) {
                diff[end + 1] -= delta;
            }
        }

        StringBuilder sb = new StringBuilder(n);
        int cur = 0;
        for (int i = 0; i < n; i++) {
            cur += diff[i];
            int shift = ((cur % 26) + 26) % 26; // ensure non‑negative
            char c = s.charAt(i);
            char shifted = (char) ((c - 'a' + shift) % 26 + 'a');
            sb.append(shifted);
        }
        return sb.toString();
    }
}

