public class Solution {
    private static final int MOD = 1_000_000_007;

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    public int distinctSequences(int n) {
        long[][] dpPrev = new long[7][7]; // dpPrev[last][secondLast]
        dpPrev[0][0] = 1; // empty sequence

        for (int pos = 0; pos < n; pos++) {
            long[][] dpNext = new long[7][7];
            for (int last = 0; last <= 6; last++) {
                for (int second = 0; second <= 6; second++) {
                    long cur = dpPrev[last][second];
                    if (cur == 0) continue;
                    for (int x = 1; x <= 6; x++) {
                        // adjacency gcd condition
                        if (last != 0 && gcd(last, x) != 1) continue;
                        // distance 1 (adjacent) cannot be equal
                        if (last != 0 && x == last) continue;
                        // distance 2 cannot be equal
                        if (second != 0 && x == second) continue;
                        dpNext[x][last] = (dpNext[x][last] + cur) % MOD;
                    }
                }
            }
            dpPrev = dpNext;
        }

        long ans = 0;
        for (int last = 0; last <= 6; last++) {
            for (int second = 0; second <= 6; second++) {
                ans = (ans + dpPrev[last][second]) % MOD;
            }
        }
        return (int) ans;
    }
}

