public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numberOfWays(int startPos, int endPos, int k) {
        long diff = (long) endPos - (long) startPos;
        long sum = (long) k + diff;
        if ((sum & 1L) == 1L) {
            return 0;
        }
        long r = sum / 2;
        if (r < 0 || r > k) {
            return 0;
        }
        int right = (int) r;
        // pre‑compute factorials up to k
        long[] fact = new long[k + 1];
        long[] invFact = new long[k + 1];
        fact[0] = 1;
        for (int i = 1; i <= k; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[k] = modPow(fact[k], MOD - 2);
        for (int i = k - 1; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        }
        long result = fact[k];
        result = result * invFact[right] % MOD;
        result = result * invFact[k - right] % MOD;
        return (int) result;
    }

    private long modPow(long base, long exp) {
        long res = 1;
        long b = base % MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = res * b % MOD;
            }
            b = b * b % MOD;
            exp >>= 1;
        }
        return res;
    }
}

