public class Solution {
    public long countExcellentPairs(int[] nums, int k) {
        Set<Integer> unique = new HashSet<>();
        for (int num : nums) {
            unique.add(num);
        }

        int[] popCountFreq = new int[32]; // popcount can be at most 31 for positive ints
        for (int val : unique) {
            int bits = Integer.bitCount(val);
            popCountFreq[bits]++;
        }

        long result = 0L;
        for (int i = 0; i < 32; i++) {
            if (popCountFreq[i] == 0) continue;
            for (int j = 0; j < 32; j++) {
                if (popCountFreq[j] == 0) continue;
                if (i + j >= k) {
                    result += (long) popCountFreq[i] * popCountFreq[j];
                }
            }
        }
        return result;
    }
}

