public class Solution {
    public long taskSchedulerII(int[] tasks, int space) {
        Map<Integer, Long> lastDay = new HashMap<>();
        long day = 0L; // current day index
        for (int task : tasks) {
            if (lastDay.containsKey(task)) {
                long earliest = lastDay.get(task) + (long) space + 1L;
                if (day < earliest) {
                    day = earliest; // wait until cooldown satisfied
                }
            }
            // perform the task on 'day'
            lastDay.put(task, day);
            day++; // move to the next day after completing this task
        }
        return day;
    }
}

