public class Solution {
    public int minPathCost(int[][] grid, int[][] moveCost) {
        int m = grid.length;
        int n = grid[0].length;
        int[] prev = new int[n];
        // Initialize with the first row values
        for (int j = 0; j < n; j++) {
            prev[j] = grid[0][j];
        }

        // DP over rows
        for (int i = 1; i < m; i++) {
            int[] cur = new int[n];
            // Set to a large value
            for (int j = 0; j < n; j++) {
                cur[j] = Integer.MAX_VALUE;
            }
            for (int j = 0; j < n; j++) { // current column
                for (int k = 0; k < n; k++) { // previous column
                    int cost = prev[k] + moveCost[grid[i - 1][k]][j] + grid[i][j];
                    if (cost < cur[j]) {
                        cur[j] = cost;
                    }
                }
            }
            prev = cur;
        }

        // Find minimum in the last row
        int answer = Integer.MAX_VALUE;
        for (int val : prev) {
            if (val < answer) {
                answer = val;
            }
        }
        return answer;
    }
}

