        for (int num : nums) {
            int digitSum = digitSum(num);
            if (bestByDigitSum.containsKey(digitSum)) {
                int candidate = num + bestByDigitSum.get(digitSum);
                if (candidate > maxPairSum) {
                    maxPairSum = candidate;
                }
                // keep the larger number for future pairs
                if (num > bestByDigitSum.get(digitSum)) {
                    bestByDigitSum.put(digitSum, num);
                }
            } else {
                bestByDigitSum.put(digitSum, num);
            }
        }
        return maxPairSum;
    }

    private int digitSum(int n) {
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum;
    }
}

