import java.util.*;
import com_github_leetcode.TreeNode;

public class Solution {
    public int amountOfTime(TreeNode root, int start) {
        if (root == null) return 0;

        // Build undirected graph from the binary tree
        Map<Integer, List<Integer>> graph = new HashMap<>();
        buildGraph(root, graph);

        // BFS from the start node to find the farthest distance
        Queue<Integer> queue = new ArrayDeque<>();
        Set<Integer> visited = new HashSet<>();

        queue.offer(start);
        visited.add(start);
        int minutes = -1; // start at -1 because the first level is minute 0

        while (!queue.isEmpty()) {
            int size = queue.size();
            minutes++;
            for (int i = 0; i < size; i++) {
                int node = queue.poll();
                for (int neighbor : graph.getOrDefault(node, Collections.emptyList())) {
                    if (!visited.contains(neighbor)) {
                        visited.add(neighbor);
                        queue.offer(neighbor);
                    }
                }
            }
        }
        return minutes;
    }

    private void buildGraph(TreeNode node, Map<Integer, List<Integer>> graph) {
        if (node == null) return;

        graph.computeIfAbsent(node.val, k -> new ArrayList<>());

        if (node.left != null) {
            graph.computeIfAbsent(node.left.val, k -> new ArrayList<>());
            graph.get(node.val).add(node.left.val);
            graph.get(node.left.val).add(node.val);
            buildGraph(node.left, graph);
        }

        if (node.right != null) {
            graph.computeIfAbsent(node.right.val, k -> new ArrayList<>());
            graph.get(node.val).add(node.right.val);
            graph.get(node.right.val).add(node.val);
            buildGraph(node.right, graph);
        }
    }
}

