import java.util.*;

public class Solution {
    private static class UnionFind {
        private final int[] parent;
        private final int[] size;

        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) return;
            // union by size
            if (size[rootA] < size[rootB]) {
                int tmp = rootA;
                rootA = rootB;
                rootB = tmp;
            }
            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }

        int componentSize(int x) {
            return size[find(x)];
        }

        Map<Integer, Integer> componentSizes() {
            Map<Integer, Integer> map = new HashMap<>();
            for (int i = 0; i < parent.length; i++) {
                int root = find(i);
                map.put(root, size[root]);
            }
            return map;
        }
    }

    public long countPairs(int n, int[][] edges) {
        UnionFind uf = new UnionFind(n);
        for (int[] edge : edges) {
            uf.union(edge[0], edge[1]);
        }

        // Gather sizes of each distinct component
        Map<Integer, Integer> compMap = uf.componentSizes();

        long totalPairs = (long) n * (n - 1) / 2;
        long intraComponentPairs = 0L;
        for (int sz : compMap.values()) {
            intraComponentPairs += (long) sz * (sz - 1) / 2;
        }

        return totalPairs - intraComponentPairs;
    }
}

