import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int maximumRobots(int[] chargeTimes, int[] runningCosts, long budget) {
        int n = chargeTimes.length;
        Deque<Integer> maxDeque = new ArrayDeque<>(); // stores indices with decreasing chargeTimes
        long sumRunning = 0L;
        int left = 0;
        int best = 0;

        for (int right = 0; right < n; right++) {
            // add right element to deque (maintain decreasing order)
            while (!maxDeque.isEmpty() && chargeTimes[maxDeque.peekLast()] <= chargeTimes[right]) {
                maxDeque.pollLast();
            }
            maxDeque.offerLast(right);

            // add running cost
            sumRunning += runningCosts[right];

            // shrink window while condition violated
            while (left <= right) {
                long maxCharge = chargeTimes[maxDeque.peekFirst()];
                long k = right - left + 1;
                long totalCost = maxCharge + k * sumRunning;
                if (totalCost <= budget) {
                    break;
                }
                // remove left element
                if (maxDeque.peekFirst() == left) {
                    maxDeque.pollFirst();
                }
                sumRunning -= runningCosts[left];
                left++;
            }

            // update answer
            best = Math.max(best, right - left + 1);
        }

        return best;
    }
}

