import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class Solution {
    public boolean matchReplacement(String s, String sub, char[][] mappings) {
        if (sub.length() > s.length()) {
            return false;
        }

        // Build replacement map: for each character in sub, the set of characters it can become
        Map<Character, Set<Character>> replaceMap = new HashMap<>();

        // Add identity replacements (character can stay the same)
        for (int i = 0; i < sub.length(); i++) {
            char c = sub.charAt(i);
            replaceMap.computeIfAbsent(c, k -> new HashSet<>()).add(c);
        }

        // Add given mappings
        for (char[] pair : mappings) {
            if (pair == null || pair.length < 2) continue;
            char oldChar = pair[0];
            char newChar = pair[1];
            replaceMap.computeIfAbsent(oldChar, k -> new HashSet<>()).add(newChar);
        }

        int n = s.length();
        int m = sub.length();

        // Try every possible starting position in s
        for (int start = 0; start <= n - m; start++) {
            boolean ok = true;
            for (int j = 0; j < m; j++) {
                char subChar = sub.charAt(j);
                char sChar = s.charAt(start + j);
                Set<Character> allowed = replaceMap.get(subChar);
                if (allowed == null || !allowed.contains(sChar)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return true;
            }
        }

        return false;
    }
}

