public class Solution {
    private static final int MOD = 1_000_000_007;

    public int peopleAwareOfSecret(int n, int delay, int forget) {
        long[] dp = new long[n + 1];
        dp[1] = 1; // day 1 the secret is known by one person

        long share = 0; // number of people who can share today

        for (int day = 2; day <= n; day++) {
            // people who start sharing today (discovered delay days ago)
            if (day - delay >= 1) {
                share = (share + dp[day - delay]) % MOD;
            }
            // people who forget today (discovered forget days ago) stop sharing
            if (day - forget >= 1) {
                share = (share - dp[day - forget] + MOD) % MOD;
            }
            dp[day] = share;
        }

        long ans = 0;
        int start = Math.max(1, n - forget + 1);
        for (int i = start; i <= n; i++) {
            ans = (ans + dp[i]) % MOD;
        }
        return (int) ans;
    }
}

