public class Solution {
    public long minimumReplacement(int[] nums) {
        long operations = 0L;
        long allowed = Long.MAX_VALUE; // maximum value allowed for the current element to keep array non‑decreasing

        for (int i = nums.length - 1; i >= 0; i--) {
            long current = nums[i];
            if (current <= allowed) {
                allowed = current;
            } else {
                // need to split current into pieces so that each piece <= allowed
                long pieces = (current + allowed - 1) / allowed; // ceil division
                operations += pieces - 1; // each split adds (pieces‑1) operations
                allowed = current / pieces; // new maximum piece after optimal split
            }
        }

        return operations;
    }
}

