public class Solution {
    public int maximumsSplicedArray(int[] nums1, int[] nums2) {
        int n = nums1.length;
        long sum1 = 0;
        long sum2 = 0;
        int[] diff = new int[n];
        for (int i = 0; i < n; i++) {
            sum1 += nums1[i];
            sum2 += nums2[i];
            diff[i] = nums1[i] - nums2[i];
        }

        // Kadane for maximum subarray sum of diff
        long maxEndingHere = diff[0];
        long maxSoFar = diff[0];
        // Kadane for minimum subarray sum of diff
        long minEndingHere = diff[0];
        long minSoFar = diff[0];

        for (int i = 1; i < n; i++) {
            maxEndingHere = Math.max(diff[i], maxEndingHere + diff[i]);
            maxSoFar = Math.max(maxSoFar, maxEndingHere);

            minEndingHere = Math.min(diff[i], minEndingHere + diff[i]);
            minSoFar = Math.min(minSoFar, minEndingHere);
        }

        long candidate1 = sum1;                     // no swap, keep nums1 sum
        long candidate2 = sum2;                     // no swap, keep nums2 sum
        long candidate3 = sum1 - minSoFar;          // improve nums1 by swapping where diff is minimal
        long candidate4 = sum2 + maxSoFar;          // improve nums2 by swapping where diff is maximal

        long result = Math.max(Math.max(candidate1, candidate2),
                               Math.max(candidate3, candidate4));

        return (int) result;
    }
}

