import com_github_leetcode.ListNode;

public class Solution {
    public int[][] spiralMatrix(int m, int n, ListNode head) {
        int[][] matrix = new int[m][n];
        // Fill with -1 initially
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                matrix[i][j] = -1;
            }
        }

        int top = 0, bottom = m - 1;
        int left = 0, right = n - 1;
        ListNode cur = head;

        while (cur != null && top <= bottom && left <= right) {
            // left to right
            for (int col = left; col <= right && cur != null; col++) {
                matrix[top][col] = cur.val;
                cur = cur.next;
            }
            top++;

            // top to bottom
            for (int row = top; row <= bottom && cur != null; row++) {
                matrix[row][right] = cur.val;
                cur = cur.next;
            }
            right--;

            // right to left
            if (top <= bottom) {
                for (int col = right; col >= left && cur != null; col--) {
                    matrix[bottom][col] = cur.val;
                    cur = cur.next;
                }
                bottom--;
            }

            // bottom to top
            if (left <= right) {
                for (int row = bottom; row >= top && cur != null; row--) {
                    matrix[row][left] = cur.val;
                    cur = cur.next;
                }
                left++;
            }
        }

        return matrix;
    }
}

