import java.util.*;

public class Solution {
    private int best;

    public int distributeCookies(int[] c, int k) {
        // Sort bags in descending order to improve pruning
        Integer[] bags = new Integer[c.length];
        for (int i = 0; i < c.length; i++) {
            bags[i] = c[i];
        }
        Arrays.sort(bags, Collections.reverseOrder());

        int[] sums = new int[k];
        best = Integer.MAX_VALUE;
        dfs(bags, 0, sums);
        return best;
    }

    private void dfs(Integer[] bags, int index, int[] sums) {
        if (index == bags.length) {
            int curMax = 0;
            for (int s : sums) {
                curMax = Math.max(curMax, s);
            }
            best = Math.min(best, curMax);
            return;
        }

        int bag = bags[index];
        // Try to assign current bag to each child
        for (int i = 0; i < sums.length; i++) {
            // Prune symmetric states: if this child has same sum as previous child, skip
            boolean skip = false;
            for (int j = 0; j < i; j++) {
                if (sums[j] == sums[i]) {
                    skip = true;
                    break;
                }
            }
            if (skip) continue;

            sums[i] += bag;
            // Prune if current max already exceeds best
            int currentMax = Math.max(best, sums[i]); // we only need to know if it exceeds best
            if (currentMax < best) {
                dfs(bags, index + 1, sums);
            } else if (index == bags.length - 1) {
                // last bag, still need to evaluate
                dfs(bags, index + 1, sums);
            }
            sums[i] -= bag;

            // If this child had no cookies before adding this bag, break to avoid equivalent permutations
            if (sums[i] == 0) {
                break;
            }
        }
    }
}

