public class Solution {
    public int garbageCollection(String[] garbage, int[] travel) {
        int n = garbage.length;
        // Prefix sum of travel times
        int[] prefix = new int[n];
        for (int i = 0; i < n - 1; i++) {
            prefix[i + 1] = prefix[i] + travel[i];
        }

        int totalTime = 0;
        int lastM = -1, lastP = -1, lastG = -1;

        for (int i = 0; i < n; i++) {
            String house = garbage[i];
            for (int j = 0; j < house.length(); j++) {
                char c = house.charAt(j);
                totalTime++; // picking up one unit takes 1 minute
                if (c == 'M') {
                    lastM = i;
                } else if (c == 'P') {
                    lastP = i;
                } else if (c == 'G') {
                    lastG = i;
                }
            }
        }

        if (lastM != -1) {
            totalTime += prefix[lastM];
        }
        if (lastP != -1) {
            totalTime += prefix[lastP];
        }
        if (lastG != -1) {
            totalTime += prefix[lastG];
        }

        return totalTime;
    }
}

