import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int validSubarraySize(int[] nums, int threshold) {
        int n = nums.length;
        int[] left = new int[n];
        int[] right = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();

        // previous less element
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) {
                stack.pop();
            }
            left[i] = stack.isEmpty() ? -1 : stack.peek();
            stack.push(i);
        }

        stack.clear();

        // next less element
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) {
                stack.pop();
            }
            right[i] = stack.isEmpty() ? n : stack.peek();
            stack.push(i);
        }

        for (int i = 0; i < n; i++) {
            int maxLen = right[i] - left[i] - 1;
            if (nums[i] <= 0) {
                continue; // cannot satisfy the condition for positive threshold
            }
            int needed = threshold / nums[i] + 1; // smallest k such that nums[i] > threshold/k
            if (needed <= maxLen) {
                return needed;
            }
        }
        return -1;
    }
}

