    public long kSum(int[] nums, int k) {
        int n = nums.length;
        // sort descending
        Integer[] arr = new Integer[n];
        for (int i = 0; i < n; i++) arr[i] = nums[i];
        Arrays.sort(arr, (a, b) -> Integer.compare(b, a));

        long[] sorted = new long[n];
        for (int i = 0; i < n; i++) sorted[i] = arr[i];

        // initial sum = sum of all positive numbers
        long initSum = 0;
        for (long v : sorted) {
            if (v > 0) initSum += v;
        }

        PriorityQueue<Node> pq = new PriorityQueue<>(
                (a, b) -> Long.compare(b.sum, a.sum) // max-heap by sum
        );
        HashSet<Node> visited = new HashSet<>();

        Node start = new Node(initSum, 0);
        pq.offer(start);
        visited.add(start);

        long answer = 0;
        for (int count = 0; count < k; count++) {
            Node cur = pq.poll();
            answer = cur.sum;
            int i = cur.idx;
            if (i >= n) continue;

            // option 1: exclude current element
            long sumExclude = cur.sum - sorted[i];
            Node nodeExclude = new Node(sumExclude, i + 1);
            if (visited.add(nodeExclude)) {
                pq.offer(nodeExclude);
            }

            // option 2: replace current element with next (if exists)
            if (i + 1 < n) {
                long sumReplace = cur.sum - sorted[i] + sorted[i + 1];
                Node nodeReplace = new Node(sumReplace, i + 1);
                if (visited.add(nodeReplace)) {
                    pq.offer(nodeReplace);
                }
            }
        }
        return answer;
    }
}

