public class Solution {
    public int countSpecialNumbers(int n) {
        // Convert n to digit array
        String s = Integer.toString(n);
        int len = s.length();
        int[] digits = new int[len];
        for (int i = 0; i < len; i++) {
            digits[i] = s.charAt(i) - '0';
        }

        // dp[pos][mask][tight][lead] = -1 means uncomputed
        // pos up to len (max 10), mask up to 1<<10 = 1024, tight 0/1, lead 0/1
        int[][][][] dp = new int[len + 1][1 << 10][2][2];
        for (int i = 0; i <= len; i++) {
            for (int m = 0; m < (1 << 10); m++) {
                for (int t = 0; t < 2; t++) {
                    for (int l = 0; l < 2; l++) {
                        dp[i][m][t][l] = -1;
                    }
                }
            }
        }

        return dfs(0, 0, 1, 1, digits, dp);
    }

    private int dfs(int pos, int mask, int tight, int lead, int[] digits, int[][][][] dp) {
        if (pos == digits.length) {
            // If all positions are leading zeros, the number is 0 which we don't count
            return lead == 1 ? 0 : 1;
        }
        if (dp[pos][mask][tight][lead] != -1) {
            return dp[pos][mask][tight][lead];
        }

        int limit = tight == 1 ? digits[pos] : 9;
        int total = 0;
        for (int d = 0; d <= limit; d++) {
            int newLead = (lead == 1 && d == 0) ? 1 : 0;
            int newMask = mask;
            if (newLead == 0) { // we placed a non‑leading digit
                if ((mask & (1 << d)) != 0) {
                    continue; // digit already used
                }
                newMask = mask | (1 << d);
            }
            int newTight = (tight == 1 && d == limit) ? 1 : 0;
            total += dfs(pos + 1, newMask, newTight, newLead, digits, dp);
        }

        dp[pos][mask][tight][lead] = total;
        return total;
    }
}

