import java.util.HashSet;
import java.util.Set;

public class Solution {
    public long distinctNames(String[] ideas) {
        // Store suffixes (the part after the first character) for each starting letter
        @SuppressWarnings("unchecked")
        Set<String>[] groups = new Set[26];
        for (int i = 0; i < 26; i++) {
            groups[i] = new HashSet<>();
        }

        for (String idea : ideas) {
            char first = idea.charAt(0);
            String suffix = idea.substring(1);
            groups[first - 'a'].add(suffix);
        }

        long result = 0L;

        // Compare each pair of different starting letters
        for (int i = 0; i < 26; i++) {
            for (int j = i + 1; j < 26; j++) {
                Set<String> setI = groups[i];
                Set<String> setJ = groups[j];

                if (setI.isEmpty() || setJ.isEmpty()) {
                    continue;
                }

                // Count common suffixes
                int common = 0;
                // Iterate over the smaller set for efficiency
                if (setI.size() < setJ.size()) {
                    for (String s : setI) {
                        if (setJ.contains(s)) {
                            common++;
                        }
                    }
                } else {
                    for (String s : setJ) {
                        if (setI.contains(s)) {
                            common++;
                        }
                    }
                }

                long uniqueI = setI.size() - common;
                long uniqueJ = setJ.size() - common;

                // Each ordered pair (i->j and j->i) yields a valid company name
                result += uniqueI * uniqueJ * 2;
            }
        }

        return result;
    }
}

