public class Solution {
    public long countSubarrays(int[] nums, long k) {
        if (k <= 1) {
            return 0L; // smallest possible score is at least 1 (positive nums)
        }
        int n = nums.length;
        long ans = 0L;
        long sum = 0L;
        int right = 0;

        for (int left = 0; left < n; left++) {
            while (right < n) {
                long newSum = sum + nums[right];
                int len = right - left + 1;
                long limit = (k - 1) / len; // maximum allowed sum for this length
                if (newSum <= limit) {
                    sum = newSum;
                    right++;
                } else {
                    break;
                }
            }
            ans += (right - left);
            if (right > left) {
                sum -= nums[left];
            } else {
                // window is empty, move right to keep it ahead of left
                right = left + 1;
            }
        }
        return ans;
    }
}

