import java.util.*;

public class Solution {
    private static class EdgeInfo {
        int child;      // child node of the edge (parent -> child)
        int xor;        // XOR of the subtree rooted at child
        EdgeInfo(int child, int xor) {
            this.child = child;
            this.xor = xor;
        }
    }

    private int[] parent;
    private int[] tin;
    private int[] tout;
    private int timer;
    private int[] subtreeXor;
    private List<Integer>[] graph;
    private List<EdgeInfo> edgeList;
    private int totalXor;

    private void dfs(int node, int par) {
        parent[node] = par;
        tin[node] = timer++;
        int curXor = nums[node];
        for (int nb : graph[node]) {
            if (nb == par) continue;
            dfs(nb, node);
            curXor ^= subtreeXor[nb];
        }
        subtreeXor[node] = curXor;
        tout[node] = timer++;
        if (par != -1) {
            edgeList.add(new EdgeInfo(node, subtreeXor[node]));
        }
    }

    private boolean isAncestor(int u, int v) {
        // returns true if u is ancestor of v (including u == v)
        return tin[u] <= tin[v] && tout[v] <= tout[u];
    }

    private int[] nums; // store reference for dfs

    public int minimumScore(int[] nums, int[][] edges) {
        this.nums = nums;
        int n = nums.length;
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        parent = new int[n];
        tin = new int[n];
        tout = new int[n];
        subtreeXor = new int[n];
        edgeList = new ArrayList<>();
        timer = 0;
        totalXor = 0;
        for (int v : nums) totalXor ^= v;

        dfs(0, -1);

        int m = edgeList.size(); // n-1
        int answer = Integer.MAX_VALUE;

        for (int i = 0; i < m; i++) {
            EdgeInfo e1 = edgeList.get(i);
            int a = e1.child;
            int xorA = e1.xor;
            for (int j = i + 1; j < m; j++) {
                EdgeInfo e2 = edgeList.get(j);
                int b = e2.child;
                int xorB = e2.xor;

                int comp1, comp2, comp3;

                if (isAncestor(a, b)) {
                    // a is ancestor of b
                    comp1 = xorB;                     // inner subtree
                    comp2 = xorA ^ xorB;              // middle part
                    comp3 = totalXor ^ xorA;          // outer rest
                } else if (isAncestor(b, a)) {
                    // b is ancestor of a
                    comp1 = xorA;
                    comp2 = xorB ^ xorA;
                    comp3 = totalXor ^ xorB;
                } else {
                    // disjoint subtrees
                    comp1 = xorA;
                    comp2 = xorB;
                    comp3 = totalXor ^ xorA ^ xorB;
                }

                int max = Math.max(comp1, Math.max(comp2, comp3));
                int min = Math.min(comp1, Math.min(comp2, comp3));
                int score = max - min;
                if (score < answer) answer = score;
            }
        }

        return answer;
    }
}

