import java.util.Arrays;

public class Solution {
    public int minOperations(int[] nums, int[] numsDivide) {
        if (nums == null || numsDivide == null || nums.length == 0 || numsDivide.length == 0) {
            return -1;
        }

        // Compute GCD of all elements in numsDivide
        int g = numsDivide[0];
        for (int i = 1; i < numsDivide.length; i++) {
            g = gcd(g, numsDivide[i]);
        }

        // Sort nums to consider deletions from smallest to largest
        Arrays.sort(nums);

        // Find the first element that divides the GCD
        for (int i = 0; i < nums.length; i++) {
            if (g % nums[i] == 0) {
                return i; // number of deletions needed
            }
        }

        // No suitable element found
        return -1;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int tmp = a % b;
            a = b;
            b = tmp;
        }
        return a;
    }
}

