import java.util.Arrays;

public class Solution {
    private static class UF {
        private final int[] parent;
        private final long[] sum;

        public UF(int n) {
            parent = new int[n];
            sum = new long[n];
            Arrays.fill(parent, -1); // -1 indicates not yet inserted
        }

        public void insert(int x, long value) {
            parent[x] = x;
            sum[x] = value;
        }

        public int find(int x) {
            if (parent[x] == x) {
                return x;
            }
            parent[x] = find(parent[x]);
            return parent[x];
        }

        public void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) {
                return;
            }
            // attach rb to ra
            parent[rb] = ra;
            sum[ra] += sum[rb];
        }

        public long getSum(int root) {
            return sum[root];
        }
    }

    public long[] maximumSegmentSum(int[] nums, int[] removeQueries) {
        int n = nums.length;
        long[] answer = new long[n];
        UF uf = new UF(n);
        boolean[] active = new boolean[n];
        long curMax = 0L;

        for (int i = n - 1; i >= 0; i--) {
            answer[i] = curMax;
            int idx = removeQueries[i];
            active[idx] = true;
            uf.insert(idx, nums[idx]);

            if (idx > 0 && active[idx - 1]) {
                uf.union(idx, idx - 1);
            }
            if (idx + 1 < n && active[idx + 1]) {
                uf.union(idx, idx + 1);
            }

            long segmentSum = uf.getSum(uf.find(idx));
            if (segmentSum > curMax) {
                curMax = segmentSum;
            }
        }
        return answer;
    }
}

