public class Solution {
    public String largestPalindromic(String num) {
        int[] cnt = new int[10];
        for (char c : num.toCharArray()) {
            cnt[c - '0']++;
        }

        StringBuilder left = new StringBuilder();
        // build the left half using the largest possible digits
        for (int d = 9; d >= 0; d--) {
            int pairs = cnt[d] / 2;
            for (int i = 0; i < pairs; i++) {
                left.append((char) ('0' + d));
            }
            cnt[d] -= pairs * 2;
        }

        // if left consists only of zeros, discard it to avoid leading zeros
        if (left.length() > 0 && left.charAt(0) == '0') {
            left.setLength(0);
        }

        // choose the middle digit (largest remaining digit)
        char middle = 0;
        for (int d = 9; d >= 0; d--) {
            if (cnt[d] > 0) {
                middle = (char) ('0' + d);
                break;
            }
        }

        // if nothing was added, the answer is "0"
        if (left.length() == 0 && middle == 0) {
            return "0";
        }

        StringBuilder result = new StringBuilder();
        result.append(left);
        if (middle != 0) {
            result.append(middle);
        }
        result.append(left.reverse());

        return result.toString();
    }
}

