import java.util.ArrayList;
import java.util.List;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int idealArrays(int n, int maxValue) {
        // pre‑compute divisors for every number up to maxValue
        List<Integer>[] divisors = new ArrayList[maxValue + 1];
        for (int i = 1; i <= maxValue; i++) {
            divisors[i] = new ArrayList<>();
        }
        for (int d = 1; d <= maxValue; d++) {
            for (int multiple = d; multiple <= maxValue; multiple += d) {
                divisors[multiple].add(d);
            }
        }

        // maximum possible length of a strictly increasing divisor chain
        int maxLen = 0;
        long prod = 1;
        while (prod <= maxValue) {
            maxLen++;
            prod <<= 1; // multiply by 2
        }

        // dpStrict[v][l] = number of strictly increasing divisor chains of length l ending with v
        long[][] dp = new long[maxValue + 1][maxLen + 1];
        for (int v = 1; v <= maxValue; v++) {
            dp[v][1] = 1; // chain consisting of the single element v
        }

        for (int l = 2; l <= maxLen; l++) {
            for (int v = 1; v <= maxValue; v++) {
                long sum = 0;
                for (int d : divisors[v]) {
                    if (d == v) continue; // need strictly increasing, so previous must be smaller
                    sum += dp[d][l - 1];
                    if (sum >= MOD) sum -= MOD;
                }
                dp[v][l] = sum;
            }
        }

        // pre‑compute factorials and inverse factorials for combinations C(n‑1, k)
        long[] fact = new long[n];
        long[] invFact = new long[n];
        fact[0] = 1;
        for (int i = 1; i < n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[n - 1] = modPow(fact[n - 1], MOD - 2);
        for (int i = n - 2; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        }

        // helper to compute C(n‑1, k)
        java.util.function.IntUnaryOperator comb = k -> {
            if (k < 0 || k > n - 1) return 0;
            return (int) (fact[n - 1] * invFact[k] % MOD * invFact[n - 1 - k] % MOD);
        };

        long answer = 0;
        for (int v = 1; v <= maxValue; v++) {
            for (int l = 1; l <= maxLen; l++) {
                if (dp[v][l] == 0) continue;
                int ways = comb.applyAsInt(l - 1); // choose positions for the (l‑1) strict increases
                answer = (answer + dp[v][l] * ways) % MOD;
            }
        }
        return (int) answer;
    }

    private long modPow(long base, long exp) {
        long result = 1;
        long b = base % MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = result * b % MOD;
            }
            b = b * b % MOD;
            exp >>= 1;
        }
        return result;
    }
}

