public class Solution {
    private int[] edges;
    private int[] state; // 0 = unvisited, 1 = visiting, 2 = visited
    private int[] depth;
    private int maxLen;

    public int longestCycle(int[] edges) {
        this.edges = edges;
        int n = edges.length;
        state = new int[n];
        depth = new int[n];
        maxLen = -1;

        for (int i = 0; i < n; i++) {
            if (state[i] == 0) {
                dfs(i, 0);
            }
        }
        return maxLen;
    }

    private void dfs(int node, int step) {
        state[node] = 1;          // mark as visiting
        depth[node] = step;       // record entry step

        int next = edges[node];
        if (next != -1) {
            if (state[next] == 0) {
                dfs(next, step + 1);
            } else if (state[next] == 1) {
                // found a cycle
                int cycleLen = step + 1 - depth[next];
                if (cycleLen > maxLen) {
                    maxLen = cycleLen;
                }
            }
            // if state[next] == 2, the path leads to an already processed component; nothing to do
        }

        state[node] = 2; // mark as visited
    }
}

