public class Solution {
    public double calculateTax(int[][] brackets, int income) {
        double tax = 0.0;
        int previousUpper = 0;
        for (int[] bracket : brackets) {
            int upper = bracket[0];
            int percent = bracket[1];
            int taxable = Math.min(income, upper) - previousUpper;
            if (taxable > 0) {
                tax += taxable * percent / 100.0;
            }
            previousUpper = upper;
            if (income <= upper) {
                break;
            }
        }
        return tax;
    }
}

