import java.util.*;

public class Solution {
    private int maxRows;
    private int n;
    private int numSelect;
    private long[] rowMasks;

    public int maximumRows(int[][] matrix, int numSelect) {
        int m = matrix.length;
        if (m == 0) {
            return 0;
        }
        this.n = matrix[0].length;
        this.numSelect = numSelect;
        this.rowMasks = new long[m];

        for (int i = 0; i < m; i++) {
            long mask = 0L;
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == 1) {
                    mask |= 1L << j;
                }
            }
            rowMasks[i] = mask;
        }

        if (numSelect >= n) {
            return m; // all rows are covered
        }

        maxRows = 0;
        combine(0, 0, 0L);
        return maxRows;
    }

    private void combine(int start, int selected, long mask) {
        if (selected == numSelect) {
            int count = 0;
            for (long rowMask : rowMasks) {
                if ((rowMask & ~mask) == 0L) {
                    count++;
                }
            }
            if (count > maxRows) {
                maxRows = count;
            }
            return;
        }
        // prune: not enough columns left to reach numSelect
        for (int i = start; i <= n - (numSelect - selected); i++) {
            combine(i + 1, selected + 1, mask | (1L << i));
        }
    }
}

