public class Solution {
    public long sellingWood(int m, int n, int[][] prices) {
        long[][] dp = new long[m + 1][n + 1];

        // Initialize dp with given prices (take the maximum if duplicates exist)
        for (int[] p : prices) {
            int h = p[0];
            int w = p[1];
            int price = p[2];
            if (h <= m && w <= n) {
                dp[h][w] = Math.max(dp[h][w], price);
            }
        }

        // Compute dp for all sub-rectangles
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                // Try vertical cuts
                for (int cut = 1; cut < j; cut++) {
                    long candidate = dp[i][cut] + dp[i][j - cut];
                    if (candidate > dp[i][j]) {
                        dp[i][j] = candidate;
                    }
                }
                // Try horizontal cuts
                for (int cut = 1; cut < i; cut++) {
                    long candidate = dp[cut][j] + dp[i - cut][j];
                    if (candidate > dp[i][j]) {
                        dp[i][j] = candidate;
                    }
                }
            }
        }

        return dp[m][n];
    }
}

