import java.util.*;

public class Solution {
    // Using topological sort to solve this problem
    public int[][] buildMatrix(int k, int[][] rowC, int[][] colC) {
        int[] rowOrder = topologicalSort(k, rowC);
        int[] colOrder = topologicalSort(k, colC);
        if (rowOrder == null || colOrder == null) {
            return new int[0][0];
        }

        // map number -> row index and column index
        int[] rowPos = new int[k + 1];
        int[] colPos = new int[k + 1];
        for (int i = 0; i < k; i++) {
            rowPos[rowOrder[i]] = i;
            colPos[colOrder[i]] = i;
        }

        int[][] matrix = new int[k][k];
        for (int num = 1; num <= k; num++) {
            int r = rowPos[num];
            int c = colPos[num];
            matrix[r][c] = num;
        }
        return matrix;
    }

    // Returns a topological ordering of numbers 1..k according to conditions,
    // or null if a cycle exists.
    private int[] topologicalSort(int k, int[][] conditions) {
        List<Integer>[] graph = new ArrayList[k + 1];
        for (int i = 1; i <= k; i++) {
            graph[i] = new ArrayList<>();
        }
        int[] indegree = new int[k + 1];

        for (int[] cond : conditions) {
            int from = cond[0];
            int to = cond[1];
            graph[from].add(to);
            indegree[to]++;
        }

        Queue<Integer> queue = new ArrayDeque<>();
        for (int i = 1; i <= k; i++) {
            if (indegree[i] == 0) {
                queue.offer(i);
            }
        }

        int[] order = new int[k];
        int idx = 0;
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            order[idx++] = cur;
            for (int nxt : graph[cur]) {
                indegree[nxt]--;
                if (indegree[nxt] == 0) {
                    queue.offer(nxt);
                }
            }
        }

        if (idx != k) {
            return null; // cycle detected
        }
        return order;
    }
}

