public class Solution {
    public int[][] largestLocal(int[][] grid) {
        int n = grid.length;
        int size = n - 2;
        int[][] result = new int[size][size];
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < n - 1; j++) {
                int max = Integer.MIN_VALUE;
                for (int di = -1; di <= 1; di++) {
                    for (int dj = -1; dj <= 1; dj++) {
                        int val = grid[i + di][j + dj];
                        if (val > max) {
                            max = val;
                        }
                    }
                }
                result[i - 1][j - 1] = max;
            }
        }
        return result;
    }
}

