import java.util.Arrays;

public class Solution {
    public int[] numberOfPairs(int[] nums) {
        if (nums == null || nums.length == 0) {
            return new int[]{0, 0};
        }
        Arrays.sort(nums);
        int pairs = 0;
        int leftovers = 0;
        int i = 0;
        int n = nums.length;
        while (i < n) {
            int count = 1;
            while (i + count < n && nums[i + count] == nums[i]) {
                count++;
            }
            pairs += count / 2;
            leftovers += count % 2;
            i += count;
        }
        return new int[]{pairs, leftovers};
    }
}

