public class Solution {
    public int minimumNumbers(int nums, int k) {
        // If the target sum is zero, the empty set satisfies the condition.
        if (nums == 0) {
            return 0;
        }

        // If the unit digit of nums already equals k, a single number works.
        if (nums % 10 == k) {
            return 1;
        }

        // Try to find the smallest count m such that:
        // nums - m * k >= 0 and (nums - m * k) is divisible by 10.
        // The maximum useful m is limited because once m * k exceeds nums,
        // further values are impossible.
        for (int m = 1; m * k <= nums; m++) {
            int remaining = nums - m * k;
            if (remaining % 10 == 0) {
                return m;
            }
        }

        // No valid combination found.
        return -1;
    }
}

