import java.util.Stack;

public class Solution {
    public String smallestNumber(String pattern) {
        if (pattern == null) {
            return "";
        }
        int n = pattern.length();
        StringBuilder sb = new StringBuilder();
        Stack<Integer> stack = new Stack<>();

        for (int i = 0; i <= n; i++) {
            // push the next number (i+1) onto the stack
            stack.push(i + 1);

            // if at the end or current pattern character is 'I', pop all to result
            if (i == n || pattern.charAt(i) == 'I') {
                while (!stack.isEmpty()) {
                    sb.append(stack.pop());
                }
            }
        }
        return sb.toString();
    }
}

