import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int[] smallestTrimmedNumbers(String[] nums, int[][] queries) {
        int n = nums.length;
        int q = queries.length;
        int[] answer = new int[q];
        int len = nums[0].length();

        // Pre‑compute trimmed versions for every possible trim length to avoid repeated substring operations
        String[][] trimmed = new String[len + 1][n]; // trimmed[t][i] = rightmost t digits of nums[i]
        for (int i = 0; i < n; i++) {
            String s = nums[i];
            for (int t = 1; t <= len; t++) {
                trimmed[t][i] = s.substring(len - t);
            }
        }

        for (int i = 0; i < q; i++) {
            int k = queries[i][0];
            int trim = queries[i][1];

            Integer[] idx = new Integer[n];
            for (int j = 0; j < n; j++) idx[j] = j;

            Arrays.sort(idx, new Comparator<Integer>() {
                @Override
                public int compare(Integer a, Integer b) {
                    int cmp = trimmed[trim][a].compareTo(trimmed[trim][b]);
                    if (cmp != 0) return cmp;
                    return Integer.compare(a, b);
                }
            });

            answer[i] = idx[k - 1];
        }

        return answer;
    }
}

