public class Solution {
    private static final int MOD = 1_000_000_007;

    public int countHousePlacements(int n) {
        // f[i] = number of valid strings of length i (no adjacent 1s)
        // recurrence: f[i] = f[i-1] + f[i-2]
        // base: f[0] = 1 (empty), f[1] = 2 (0 or 1)
        long a = 1; // f[0]
        long b = 2; // f[1]
        if (n == 0) {
            return (int) ((a * a) % MOD);
        }
        if (n == 1) {
            return (int) ((b * b) % MOD);
        }
        long cur = 0;
        for (int i = 2; i <= n; i++) {
            cur = (b + a) % MOD; // f[i]
            a = b;
            b = cur;
        }
        long result = (b * b) % MOD;
        return (int) result;
    }
}

