import java.util.Arrays;

public class Solution {
    public int[] answerQueries(int[] nums, int[] queries) {
        // Sort the numbers to consider smallest elements first
        Arrays.sort(nums);
        int n = nums.length;
        // Build prefix sums using long to avoid overflow
        long[] prefix = new long[n];
        long sum = 0;
        for (int i = 0; i < n; i++) {
            sum += nums[i];
            prefix[i] = sum;
        }

        int m = queries.length;
        int[] answer = new int[m];
        for (int i = 0; i < m; i++) {
            int q = queries[i];
            // Binary search for the largest index where prefix[idx] <= q
            int idx = upperBound(prefix, q) - 1;
            answer[i] = idx + 1; // if idx == -1, result is 0
        }
        return answer;
    }

    // Returns first index where arr[idx] > target (i.e., upper bound)
    private int upperBound(long[] arr, long target) {
        int left = 0;
        int right = arr.length;
        while (left < right) {
            int mid = (left + right) >>> 1;
            if (arr[mid] <= target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

