import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int latestTimeCatchTheBus(int[] buses, int[] passengers, int capacity) {
        Arrays.sort(buses);
        Arrays.sort(passengers);
        Set<Integer> passengerSet = new HashSet<>();
        for (int p : passengers) {
            passengerSet.add(p);
        }

        int pIdx = 0; // index in passengers array
        int lastBoarded = -1; // time of the last passenger who boarded the last bus
        int boardedOnLastBus = 0; // number of passengers on the last bus

        for (int i = 0; i < buses.length; i++) {
            int busTime = buses[i];
            int cnt = 0;
            while (cnt < capacity && pIdx < passengers.length && passengers[pIdx] <= busTime) {
                cnt++;
                lastBoarded = passengers[pIdx];
                pIdx++;
            }
            if (i == buses.length - 1) {
                boardedOnLastBus = cnt;
            }
        }

        int answer;
        if (boardedOnLastBus < capacity) {
            // we can try to arrive at the bus departure time
            answer = buses[buses.length - 1];
        } else {
            // bus is full, we must arrive before the last boarded passenger
            answer = lastBoarded - 1;
        }

        // Ensure the answer does not coincide with any passenger arrival time
        while (passengerSet.contains(answer)) {
            answer--;
        }
        return answer;
    }
}

