import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int countDistinctIntegers(int[] nums) {
        Set<Integer> distinct = new HashSet<>();
        for (int num : nums) {
            distinct.add(num);
            distinct.add(reverse(num));
        }
        return distinct.size();
    }

    private int reverse(int n) {
        int rev = 0;
        while (n > 0) {
            rev = rev * 10 + (n % 10);
            n /= 10;
        }
        return rev;
    }
}

package referenz;


public class Solution {
    public int longestSubsequence(String s, int k) {
        int n = s.length();
        long cur = 0L;
        long power = 1L; // value of the current bit if we include it
        int ans = 0;
        int i = n - 1;

        // Process while the weight of the next bit does not exceed k
        while (i >= 0 && power <= k) {
            char c = s.charAt(i);
            if (c == '0') {
                // zero adds no value, we can always take it
                ans++;
            } else { // c == '1'
                if (cur + power <= k) {
                    cur += power;
                    ans++;
                }
            }
            power <<= 1; // move to the next more‑significant bit
            i--;
        }

        // Remaining characters are all leading bits; only zeros can be added
        while (i >= 0) {
            if (s.charAt(i) == '0') {
                ans++;
            }
            i--;
        }

        return ans;
    }
}

