import java.util.Arrays;

public class Solution {
    public int deleteGreatestValue(int[][] grid) {
        int m = grid.length;
        if (m == 0) {
            return 0;
        }
        int n = grid[0].length;
        int[][] sorted = new int[m][n];
        for (int i = 0; i < m; i++) {
            sorted[i] = grid[i].clone();
            Arrays.sort(sorted[i]); // ascending
        }
        long answer = 0L;
        for (int col = 0; col < n; col++) {
            int max = Integer.MIN_VALUE;
            for (int row = 0; row < m; row++) {
                int val = sorted[row][n - 1 - col]; // col‑th greatest element
                if (val > max) {
                    max = val;
                }
            }
            answer += max;
        }
        return (int) answer;
    }
}

