import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int countSubarrays(int[] nums, int k) {
        int n = nums.length;
        int idx = -1;
        for (int i = 0; i < n; i++) {
            if (nums[i] == k) {
                idx = i;
                break;
            }
        }
        // Prefix sums to the left of k (including position k with sum 0)
        Map<Integer, Integer> freq = new HashMap<>();
        int sum = 0;
        freq.put(0, 1);
        for (int i = idx - 1; i >= 0; i--) {
            if (nums[i] > k) {
                sum += 1;
            } else if (nums[i] < k) {
                sum -= 1;
            }
            freq.put(sum, freq.getOrDefault(sum, 0) + 1);
        }

        long ans = 0;
        sum = 0;
        for (int i = idx; i < n; i++) {
            if (i != idx) {
                if (nums[i] > k) {
                    sum += 1;
                } else if (nums[i] < k) {
                    sum -= 1;
                }
            }
            ans += freq.getOrDefault(sum, 0);
            ans += freq.getOrDefault(sum - 1, 0);
        }

        return (int) ans;
    }
}

