public class Solution {
    public int hardestWorker(int[][] logs) {
        int prevTime = 0;
        int maxDuration = -1;
        int resultId = -1;
        for (int[] log : logs) {
            int id = log[0];
            int leaveTime = log[1];
            int duration = leaveTime - prevTime;
            if (duration > maxDuration || (duration == maxDuration && id < resultId)) {
                maxDuration = duration;
                resultId = id;
            }
            prevTime = leaveTime;
        }
        return resultId;
    }
}

