import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int partitionString(String s) {
        if (s == null || s.isEmpty()) {
            return 0;
        }
        int partitions = 1;
        Set<Character> seen = new HashSet<>();
        for (char c : s.toCharArray()) {
            if (seen.contains(c)) {
                partitions++;
                seen.clear();
            }
            seen.add(c);
        }
        return partitions;
    }
}

