public class Solution {
    public int[][] onesMinusZeros(int[][] grid) {
        int m = grid.length;
        if (m == 0) {
            return new int[0][];
        }
        int n = grid[0].length;
        int[] rowOnes = new int[m];
        int[] colOnes = new int[n];

        // Count ones per row and column
        for (int i = 0; i < m; i++) {
            int[] row = grid[i];
            for (int j = 0; j < n; j++) {
                if (row[j] == 1) {
                    rowOnes[i]++;
                    colOnes[j]++;
                }
            }
        }

        int[][] diff = new int[m][n];
        // Pre‑compute row and column contributions
        int[] rowContribution = new int[m];
        int[] colContribution = new int[n];
        for (int i = 0; i < m; i++) {
            rowContribution[i] = 2 * rowOnes[i] - n; // onesRow_i - zerosRow_i
        }
        for (int j = 0; j < n; j++) {
            colContribution[j] = 2 * colOnes[j] - m; // onesCol_j - zerosCol_j
        }

        // Build the diff matrix
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                diff[i][j] = rowContribution[i] + colContribution[j];
            }
        }

        return diff;
    }
}

