import java.util.*;

public class Solution {
    public int unequalTriplets(int[] nums) {
        // Count frequencies of each distinct number
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : nums) {
            freqMap.merge(num, 1, Integer::sum);
        }

        // Extract frequencies into a list
        List<Integer> freqs = new ArrayList<>(freqMap.values());

        long sumPrev = 0;          // sum of frequencies processed so far
        long sumPrevPairs = 0;     // sum of products of all pairs among processed frequencies
        long result = 0;           // total number of unequal triplets

        for (int f : freqs) {
            long freq = f;
            // Each new frequency forms triplets with all previous pairs
            result += freq * sumPrevPairs;

            // Update pair sums and total sum for future iterations
            sumPrevPairs += freq * sumPrev;
            sumPrev += freq;
        }

        return (int) result;
    }
}

