import java.util.*;

public class Solution {
    public long numberOfPairs(int[] nums1, int[] nums2, int diff) {
        int n = nums1.length;
        long[] arr = new long[n];
        for (int i = 0; i < n; i++) {
            arr[i] = (long) nums1[i] - (long) nums2[i];
        }

        // coordinate compression of arr values
        long[] sorted = arr.clone();
        Arrays.sort(sorted);
        int uniqCount = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || sorted[i] != sorted[i - 1]) {
                sorted[uniqCount++] = sorted[i];
            }
        }
        long[] uniq = Arrays.copyOf(sorted, uniqCount);

        FenwickTree bit = new FenwickTree(uniqCount);
        long result = 0L;

        for (int j = 0; j < n; j++) {
            long threshold = arr[j] + diff;
            int idx = upperBound(uniq, threshold); // number of elements <= threshold
            result += bit.query(idx);
            int pos = lowerBound(uniq, arr[j]) + 1; // 1‑based index for BIT
            bit.update(pos, 1);
        }

        return result;
    }

    // first index of element > target (i.e., insertion point for target+epsilon)
    private int upperBound(long[] arr, long target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] <= target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo; // count of elements <= target
    }

    // first index of element >= target
    private int lowerBound(long[] arr, long target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    // Fenwick Tree (Binary Indexed Tree) for prefix sums
    private static class FenwickTree {
        private final int n;
        private final int[] bit;

        FenwickTree(int size) {
            this.n = size;
            this.bit = new int[n + 1];
        }

        void update(int idx, int delta) {
            while (idx <= n) {
                bit[idx] += delta;
                idx += idx & -idx;
            }
        }

        long query(int idx) {
            long sum = 0;
            while (idx > 0) {
                sum += bit[idx];
                idx -= idx & -idx;
            }
            return sum;
        }
    }
}

