import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int subarrayGCD(int[] nums, int k) {
        Map<Integer, Long> prev = new HashMap<>();
        long answer = 0L;

        for (int num : nums) {
            Map<Integer, Long> cur = new HashMap<>();

            // subarray consisting of only the current element
            cur.put(num, cur.getOrDefault(num, 0L) + 1L);

            // extend previous subarrays
            for (Map.Entry<Integer, Long> entry : prev.entrySet()) {
                int newGcd = gcd(entry.getKey(), num);
                cur.put(newGcd, cur.getOrDefault(newGcd, 0L) + entry.getValue());
            }

            answer += cur.getOrDefault(k, 0L);
            prev = cur;
        }

        return (int) answer;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int tmp = a % b;
            a = b;
            b = tmp;
        }
        return a;
    }
}

