import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {
    public long makeSimilar(int[] nums, int[] target) {
        List<Integer> numsEven = new ArrayList<>();
        List<Integer> numsOdd = new ArrayList<>();
        List<Integer> targetEven = new ArrayList<>();
        List<Integer> targetOdd = new ArrayList<>();

        for (int v : nums) {
            if ((v & 1) == 0) {
                numsEven.add(v);
            } else {
                numsOdd.add(v);
            }
        }

        for (int v : target) {
            if ((v & 1) == 0) {
                targetEven.add(v);
            } else {
                targetOdd.add(v);
            }
        }

        Collections.sort(numsEven);
        Collections.sort(numsOdd);
        Collections.sort(targetEven);
        Collections.sort(targetOdd);

        long diffSum = 0L;

        for (int i = 0; i < numsEven.size(); i++) {
            diffSum += Math.abs(numsEven.get(i) - targetEven.get(i));
        }
        for (int i = 0; i < numsOdd.size(); i++) {
            diffSum += Math.abs(numsOdd.get(i) - targetOdd.get(i));
        }

        // each operation changes two numbers by 2, so total diff is reduced by 4 per operation
        return diffSum / 4;
    }
}

