import java.util.Arrays;

public class Solution {
    public String oddString(String[] w) {
        if (w == null || w.length == 0) {
            return "";
        }
        int n = w[0].length();
        // Helper to compute difference array
        java.util.function.Function<String, int[]> diff = s -> {
            int[] d = new int[n - 1];
            for (int i = 0; i < n - 1; i++) {
                d[i] = (s.charAt(i + 1) - 'a') - (s.charAt(i) - 'a');
            }
            return d;
        };

        // Determine the common difference array using the first three strings
        int[] d0 = diff.apply(w[0]);
        int[] d1 = diff.apply(w[1]);
        int[] d2 = diff.apply(w[2]);

        int[] common;
        if (Arrays.equals(d0, d1) || Arrays.equals(d0, d2)) {
            common = d0;
        } else {
            common = d1; // d1 must be the common one
        }

        // Find and return the odd string
        for (String s : w) {
            if (!Arrays.equals(diff.apply(s), common)) {
                return s;
            }
        }
        // Fallback (should never happen per problem constraints)
        return "";
    }
}

