import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {
    private static class Factory implements Comparable<Factory> {
        int position;
        int limit;

        Factory(int position, int limit) {
            this.position = position;
            this.limit = limit;
        }

        @Override
        public int compareTo(Factory o) {
            return Integer.compare(this.position, o.position);
        }
    }

    public long minimumTotalDistance(List<Integer> robot, int[][] f) {
        int n = robot.size();
        int[] robots = new int[n];
        for (int i = 0; i < n; i++) {
            robots[i] = robot.get(i);
        }
        Arrays.sort(robots);

        List<Factory> factories = new ArrayList<>();
        for (int[] arr : f) {
            factories.add(new Factory(arr[0], arr[1]));
        }
        Collections.sort(factories);

        long INF = Long.MAX_VALUE / 4;
        long[] dp = new long[n + 1];
        for (int i = 1; i <= n; i++) dp[i] = INF;
        dp[0] = 0;

        for (Factory factory : factories) {
            int limit = factory.limit;
            if (limit == 0) continue; // cannot take any robot, skip

            long[] prefix = new long[n + 1];
            prefix[0] = 0;
            for (int i = 1; i <= n; i++) {
                prefix[i] = prefix[i - 1] + Math.abs((long) robots[i - 1] - factory.position);
            }

            long[] ndp = new long[n + 1];
            for (int i = 0; i <= n; i++) ndp[i] = INF;

            // assign 0 robots to this factory
            for (int i = 0; i <= n; i++) {
                ndp[i] = dp[i];
            }

            for (int i = 1; i <= n; i++) {
                long best = INF;
                int maxK = Math.min(limit, i);
                for (int k = 1; k <= maxK; k++) {
                    long candidate = dp[i - k] + (prefix[i] - prefix[i - k]);
                    if (candidate < best) {
                        best = candidate;
                    }
                }
                if (best < ndp[i]) {
                    ndp[i] = best;
                }
            }
            dp = ndp;
        }

        return dp[n];
    }
}

