import com_github_leetcode.TreeNode;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    private final Map<Integer, Integer> depth = new HashMap<>();
    private final Map<Integer, Integer> subMax = new HashMap<>();
    private final Map<Integer, Integer> max1 = new HashMap<>();
    private final Map<Integer, Integer> max2 = new HashMap<>();
    private final Map<Integer, Integer> bestOutside = new HashMap<>();

    private void dfs1(TreeNode node, int d) {
        if (node == null) return;
        depth.put(node.val, d);
        int curMax = d; // at least the node itself
        int first = -1, second = -1;

        if (node.left != null) {
            dfs1(node.left, d + 1);
            int leftMax = subMax.get(node.left.val);
            curMax = Math.max(curMax, leftMax);
            if (leftMax > first) {
                second = first;
                first = leftMax;
            } else if (leftMax > second) {
                second = leftMax;
            }
        }

        if (node.right != null) {
            dfs1(node.right, d + 1);
            int rightMax = subMax.get(node.right.val);
            curMax = Math.max(curMax, rightMax);
            if (rightMax > first) {
                second = first;
                first = rightMax;
            } else if (rightMax > second) {
                second = rightMax;
            }
        }

        subMax.put(node.val, curMax);
        max1.put(node.val, first);
        max2.put(node.val, second);
    }

    private void dfs2(TreeNode node, int outsideBest) {
        if (node == null) return;
        bestOutside.put(node.val, outsideBest);

        if (node.left != null) {
            int siblingBest = (max1.get(node.val) != null && max1.get(node.val) == subMax.get(node.left.val))
                    ? max2.get(node.val) : max1.get(node.val);
            int childBest = Math.max(outsideBest, siblingBest);
            dfs2(node.left, childBest);
        }

        if (node.right != null) {
            int siblingBest = (max1.get(node.val) != null && max1.get(node.val) == subMax.get(node.right.val))
                    ? max2.get(node.val) : max1.get(node.val);
            int childBest = Math.max(outsideBest, siblingBest);
            dfs2(node.right, childBest);
        }
    }

    public int[] treeQueries(TreeNode root, int[] queries) {
        dfs1(root, 0);
        dfs2(root, -1); // root has no outside nodes

        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int q = queries[i];
            int val = bestOutside.getOrDefault(q, 0);
            ans[i] = Math.max(val, 0); // height cannot be negative
        }
        return ans;
    }
}

