import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public int minGroups(int[][] intervals) {
        if (intervals == null || intervals.length == 0) {
            return 0;
        }
        // Sort intervals by start time (ascending)
        Arrays.sort(intervals, (a, b) -> {
            if (a[0] != b[0]) {
                return Integer.compare(a[0], b[0]);
            }
            return Integer.compare(a[1], b[1]);
        });

        // Min-heap to keep track of the earliest ending interval in each group
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        int maxGroups = 0;

        for (int[] interval : intervals) {
            int start = interval[0];
            int end = interval[1];

            // If the current interval starts after the earliest ending interval,
            // they do not intersect (need strict greater because intervals are inclusive)
            if (!heap.isEmpty() && start > heap.peek()) {
                heap.poll(); // reuse that group
            }
            heap.offer(end);
            maxGroups = Math.max(maxGroups, heap.size());
        }

        return maxGroups;
    }
}

