public class Solution {
    public int[] applyOperations(int[] nums) {
        int n = nums.length;
        // Apply the operations sequentially
        for (int i = 0; i < n - 1; i++) {
            if (nums[i] == nums[i + 1]) {
                nums[i] <<= 1; // multiply by 2
                nums[i + 1] = 0;
            }
        }
        // Shift all zeros to the end while preserving order of non-zero elements
        int[] result = new int[n];
        int idx = 0;
        for (int value : nums) {
            if (value != 0) {
                result[idx++] = value;
            }
        }
        // Remaining positions are already zero-initialized
        return result;
    }
}

