import java.util.*;

public class Solution {
    private static final long MOD1 = 1_000_000_007L;
    private static final long MOD2 = 1_000_000_009L;
    private static final long BASE = 91138233L;

    public int deleteString(String s) {
        int n = s.length();
        long[] pow1 = new long[n + 1];
        long[] pow2 = new long[n + 1];
        pow1[0] = 1;
        pow2[0] = 1;
        for (int i = 1; i <= n; i++) {
            pow1[i] = (pow1[i - 1] * BASE) % MOD1;
            pow2[i] = (pow2[i - 1] * BASE) % MOD2;
        }

        long[] pref1 = new long[n + 1];
        long[] pref2 = new long[n + 1];
        for (int i = 0; i < n; i++) {
            int c = s.charAt(i) - 'a' + 1;
            pref1[i + 1] = (pref1[i] * BASE + c) % MOD1;
            pref2[i + 1] = (pref2[i] * BASE + c) % MOD2;
        }

        // helper to get hash of substring [l, r)
        class Hash {
            long h1, h2;
            Hash(long h1, long h2) { this.h1 = h1; this.h2 = h2; }
            @Override
            public boolean equals(Object o) {
                if (this == o) return true;
                if (!(o instanceof Hash)) return false;
                Hash other = (Hash) o;
                return h1 == other.h1 && h2 == other.h2;
            }
            @Override
            public int hashCode() {
                return Objects.hash(h1, h2);
            }
        }

        java.util.function.BiFunction<Integer, Integer, Hash> getHash = (l, r) -> {
            long h1 = (pref1[r] - (pref1[l] * pow1[r - l]) % MOD1 + MOD1) % MOD1;
            long h2 = (pref2[r] - (pref2[l] * pow2[r - l]) % MOD2 + MOD2) % MOD2;
            return new Hash(h1, h2);
        };

        int[] dp = new int[n + 1];
        dp[n] = 0; // empty suffix needs 0 operations

        for (int i = n - 1; i >= 0; i--) {
            dp[i] = 1; // delete the whole remaining part in one operation
            int maxLen = (n - i) / 2;
            for (int len = 1; len <= maxLen; len++) {
                if (getHash.apply(i, i + len).equals(getHash.apply(i + len, i + 2 * len))) {
                    dp[i] = Math.max(dp[i], 1 + dp[i + len]);
                }
            }
        }
        return dp[0];
    }
}

