public class Solution {
    private static final int[] DAYS_IN_MONTH = {
        31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31
    };

    private int dayOfYear(String date) {
        int month = Integer.parseInt(date.substring(0, 2));
        int day = Integer.parseInt(date.substring(3, 5));
        int dayOfYear = day;
        for (int i = 0; i < month - 1; i++) {
            dayOfYear += DAYS_IN_MONTH[i];
        }
        return dayOfYear;
    }

    public int getOverlap(String arriveAlice, String leaveAlice,
                           String arriveBob, String leaveBob) {
        int startA = dayOfYear(arriveAlice);
        int endA   = dayOfYear(leaveAlice);
        int startB = dayOfYear(arriveBob);
        int endB   = dayOfYear(leaveBob);

        int start = Math.max(startA, startB);
        int end   = Math.min(endA, endB);

        if (start > end) {
            return 0;
        }
        return end - start + 1;
    }
}

