public class Solution {
    public int[][] closestNodes(TreeNode root, int[] queries) {
        TreeSet<Integer> set = new TreeSet<>();
        inorder(root, set);
        int n = queries.length;
        int[][] answer = new int[n][2];
        for (int i = 0; i < n; i++) {
            Integer floor = set.floor(queries[i]);
            Integer ceil = set.ceiling(queries[i]);
            answer[i][0] = floor != null ? floor : -1;
            answer[i][1] = ceil != null ? ceil : -1;
        }
        return answer;
    }

    private void inorder(TreeNode node, TreeSet<Integer> set) {
        if (node == null) {
            return;
        }
        inorder(node.left, set);
        set.add(node.val);
        inorder(node.right, set);
    }
}

