import java.util.Arrays;

public class Solution {
    public int[] smallestSubarrays(int[] nums) {
        int n = nums.length;
        int[] answer = new int[n];
        int[] next = new int[31];
        Arrays.fill(next, n);
        int suffixOr = 0;
        for (int i = n - 1; i >= 0; --i) {
            int val = nums[i];
            // update earliest positions for bits present at index i
            for (int b = 0; b < 31; ++b) {
                if ((val & (1 << b)) != 0) {
                    next[b] = i;
                }
            }
            suffixOr |= val; // OR of suffix starting at i
            int maxPos = i;
            int needed = suffixOr;
            for (int b = 0; b < 31; ++b) {
                if ((needed & (1 << b)) != 0) {
                    maxPos = Math.max(maxPos, next[b]);
                }
            }
            answer[i] = maxPos - i + 1;
        }
        return answer;
    }
}

