import java.util.PriorityQueue;

public class Solution {
    public long totalCost(int[] costs, int k, int candidates) {
        int n = costs.length;
        PriorityQueue<int[]> leftPQ = new PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
        });
        PriorityQueue<int[]> rightPQ = new PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
        });

        int leftPtr = 0;
        int rightPtr = n - 1;

        // Fill initial candidates from the left side
        for (int i = 0; i < candidates && leftPtr <= rightPtr; i++) {
            leftPQ.offer(new int[]{costs[leftPtr], leftPtr});
            leftPtr++;
        }
        // Fill initial candidates from the right side
        for (int i = 0; i < candidates && leftPtr <= rightPtr; i++) {
            rightPQ.offer(new int[]{costs[rightPtr], rightPtr});
            rightPtr--;
        }

        long total = 0L;
        for (int hired = 0; hired < k; hired++) {
            if (leftPQ.isEmpty()) {
                int[] r = rightPQ.poll();
                total += r[0];
                if (leftPtr <= rightPtr) {
                    rightPQ.offer(new int[]{costs[rightPtr], rightPtr});
                    rightPtr--;
                }
            } else if (rightPQ.isEmpty()) {
                int[] l = leftPQ.poll();
                total += l[0];
                if (leftPtr <= rightPtr) {
                    leftPQ.offer(new int[]{costs[leftPtr], leftPtr});
                    leftPtr++;
                }
            } else {
                int[] lTop = leftPQ.peek();
                int[] rTop = rightPQ.peek();
                if (lTop[0] < rTop[0] || (lTop[0] == rTop[0] && lTop[1] < rTop[1])) {
                    int[] l = leftPQ.poll();
                    total += l[0];
                    if (leftPtr <= rightPtr) {
                        leftPQ.offer(new int[]{costs[leftPtr], leftPtr});
                        leftPtr++;
                    }
                } else {
                    int[] r = rightPQ.poll();
                    total += r[0];
                    if (leftPtr <= rightPtr) {
                        rightPQ.offer(new int[]{costs[rightPtr], rightPtr});
                        rightPtr--;
                    }
                }
            }
        }
        return total;
    }
}

