    public int minScore(int n, int[][] roads) {
        // Build adjacency list
        List<int[]>[] adj = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] r : roads) {
            int a = r[0];
            int b = r[1];
            int d = r[2];
            adj[a].add(new int[]{b, d});
            adj[b].add(new int[]{a, d});
        }

        // DFS/BFS from city 1 to find all reachable cities
        boolean[] visited = new boolean[n + 1];
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(1);
        visited[1] = true;

        int min = Integer.MAX_VALUE;

        while (!stack.isEmpty()) {
            int u = stack.pop();
            for (int[] edge : adj[u]) {
                int v = edge[0];
                int dist = edge[1];
                // Update minimum distance seen in the component
                if (dist < min) {
                    min = dist;
                }
                if (!visited[v]) {
                    visited[v] = true;
                    stack.push(v);
                }
            }
        }

        return min;
    }
}

