import java.util.*;

public class Solution {
    private static class Node {
        int[] child = new int[26];
        int cnt = 0;
        Node() {
            Arrays.fill(child, -1);
        }
    }

    private final List<Node> nodes = new ArrayList<>();

    public Solution() {
        nodes.add(new Node()); // root node
    }

    public int[] sumPrefixScores(String[] words) {
        // Build the trie and count occurrences for each prefix
        for (String word : words) {
            int cur = 0;
            for (int i = 0; i < word.length(); i++) {
                int idx = word.charAt(i) - 'a';
                int next = nodes.get(cur).child[idx];
                if (next == -1) {
                    next = nodes.size();
                    nodes.get(cur).child[idx] = next;
                    nodes.add(new Node());
                }
                cur = next;
                nodes.get(cur).cnt++;
            }
        }

        int n = words.length;
        int[] answer = new int[n];
        // Compute the sum of prefix scores for each word
        for (int i = 0; i < n; i++) {
            String word = words[i];
            int cur = 0;
            int sum = 0;
            for (int j = 0; j < word.length(); j++) {
                int idx = word.charAt(j) - 'a';
                cur = nodes.get(cur).child[idx];
                sum += nodes.get(cur).cnt;
            }
            answer[i] = sum;
        }
        return answer;
    }
}

