public class Solution {
    public List<List<String>> mostPopularCreator(String[] creators, String[] ids, int[] views) {
        Map<String, Long> totalViews = new HashMap<>();
        Map<String, Integer> bestView = new HashMap<>();
        Map<String, String> bestId = new HashMap<>();

        for (int i = 0; i < creators.length; i++) {
            String creator = creators[i];
            String id = ids[i];
            int view = views[i];

            // update total popularity
            totalViews.put(creator, totalViews.getOrDefault(creator, 0L) + view);

            // update most viewed video for this creator
            int curBestView = bestView.getOrDefault(creator, -1);
            if (view > curBestView) {
                bestView.put(creator, view);
                bestId.put(creator, id);
            } else if (view == curBestView) {
                String curBestId = bestId.get(creator);
                if (id.compareTo(curBestId) < 0) {
                    bestId.put(creator, id);
                }
            }
        }

        // find global maximum popularity
        long maxPopularity = 0;
        for (long pop : totalViews.values()) {
            if (pop > maxPopularity) {
                maxPopularity = pop;
            }
        }

        // collect answer
        List<List<String>> answer = new ArrayList<>();
        for (Map.Entry<String, Long> entry : totalViews.entrySet()) {
            if (entry.getValue() == maxPopularity) {
                List<String> pair = new ArrayList<>(2);
                pair.add(entry.getKey());
                pair.add(bestId.get(entry.getKey()));
                answer.add(pair);
            }
        }

        return answer;
    }
}

