import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int destroyTargets(int[] nums, int space) {
        // Map to store count of each remainder
        Map<Integer, Integer> countMap = new HashMap<>();
        // Map to store the smallest number for each remainder
        Map<Integer, Integer> minMap = new HashMap<>();

        for (int num : nums) {
            int rem = num % space;
            countMap.put(rem, countMap.getOrDefault(rem, 0) + 1);
            if (!minMap.containsKey(rem) || num < minMap.get(rem)) {
                minMap.put(rem, num);
            }
        }

        int maxCount = 0;
        int answer = Integer.MAX_VALUE;

        for (Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
            int rem = entry.getKey();
            int cnt = entry.getValue();
            int minVal = minMap.get(rem);

            if (cnt > maxCount) {
                maxCount = cnt;
                answer = minVal;
            } else if (cnt == maxCount && minVal < answer) {
                answer = minVal;
            }
        }

        return answer;
    }
}

