        }
        dfs(0, -1, graph);
        return totalFuel;
    }

    private int dfs(int node, int parent, List<Integer>[] graph) {
        int representatives = 1; // the representative of this city
        for (int neighbor : graph[node]) {
            if (neighbor == parent) continue;
            int subSize = dfs(neighbor, node, graph);
            // trips needed on edge (node, neighbor)
            totalFuel += (long) ((subSize + seats - 1) / seats);
            representatives += subSize;
        }
        return representatives;
    }
