public class Solution {
    public int xorAllNums(int[] nums1, int[] nums2) {
        int xorA = 0;
        for (int v : nums1) {
            xorA ^= v;
        }
        int xorB = 0;
        for (int v : nums2) {
            xorB ^= v;
        }
        int n1 = nums1.length;
        int n2 = nums2.length;

        if ((n2 & 1) == 0) { // n2 even
            return (n1 & 1) == 0 ? 0 : xorB;
        } else { // n2 odd
            int result = xorA;
            if ((n1 & 1) == 1) {
                result ^= xorB;
            }
            return result;
        }
    }
}

