public class Solution {
    public int longestNiceSubarray(int[] nums) {
        int n = nums.length;
        int[] bitCount = new int[31];
        int left = 0;
        int maxLen = 0;
        int windowLen = 0;

        for (int right = 0; right < n; right++) {
            int val = nums[right];
            for (int b = 0; b < 31; b++) {
                if ((val & (1 << b)) != 0) {
                    bitCount[b]++;
                }
            }
            windowLen++;

            while (hasViolation(bitCount, windowLen)) {
                int leftVal = nums[left];
                for (int b = 0; b < 31; b++) {
                    if ((leftVal & (1 << b)) != 0) {
                        bitCount[b]--;
                    }
                }
                left++;
                windowLen--;
            }

            if (windowLen > maxLen) {
                maxLen = windowLen;
            }
        }

        return maxLen;
    }

    private boolean hasViolation(int[] bitCount, int windowLen) {
        for (int b = 0; b < 31; b++) {
            if (bitCount[b] >= 2 && bitCount[b] < windowLen) {
                return true;
            }
        }
        return false;
    }
}

