import com_github_leetcode.TreeNode;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int minimumOperations(TreeNode root) {
        if (root == null) {
            return 0;
        }
        int totalSwaps = 0;
        ArrayDeque<TreeNode> queue = new ArrayDeque<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            int[] values = new int[levelSize];
            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.poll();
                values[i] = node.val;
                if (node.left != null) {
                    queue.offer(node.left);
                }
                if (node.right != null) {
                    queue.offer(node.right);
                }
            }
            totalSwaps += minSwapsToSort(values);
        }
        return totalSwaps;
    }

    private int minSwapsToSort(int[] arr) {
        int n = arr.length;
        if (n <= 1) {
            return 0;
        }
        int[] sorted = arr.clone();
        Arrays.sort(sorted);
        Map<Integer, Integer> valueToIndex = new HashMap<>(n);
        for (int i = 0; i < n; i++) {
            valueToIndex.put(sorted[i], i);
        }
        int[] targetPos = new int[n];
        for (int i = 0; i < n; i++) {
            targetPos[i] = valueToIndex.get(arr[i]);
        }
        boolean[] visited = new boolean[n];
        int swaps = 0;
        for (int i = 0; i < n; i++) {
            if (visited[i] || targetPos[i] == i) {
                continue;
            }
            int cycleSize = 0;
            int j = i;
            while (!visited[j]) {
                visited[j] = true;
                j = targetPos[j];
                cycleSize++;
            }
            swaps += cycleSize - 1;
        }
        return swaps;
    }
}

