import java.util.Arrays;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numberOfPaths(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;

        int[][] prev = new int[n][k];
        int[][] cur = new int[n][k];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int val = ((grid[i][j] % k) + k) % k;

                if (i == 0 && j == 0) {
                    cur[0][val] = 1;
                    continue;
                }

                // from top
                if (i > 0) {
                    int[] top = prev[j];
                    for (int r = 0; r < k; r++) {
                        int cnt = top[r];
                        if (cnt != 0) {
                            int newR = (r + val) % k;
                            cur[j][newR] = (int) ((cur[j][newR] + (long) cnt) % MOD);
                        }
                    }
                }

                // from left
                if (j > 0) {
                    int[] left = cur[j - 1];
                    for (int r = 0; r < k; r++) {
                        int cnt = left[r];
                        if (cnt != 0) {
                            int newR = (r + val) % k;
                            cur[j][newR] = (int) ((cur[j][newR] + (long) cnt) % MOD);
                        }
                    }
                }
            }

            // prepare for next row
            int[][] temp = prev;
            prev = cur;
            cur = temp;
            for (int col = 0; col < n; col++) {
                Arrays.fill(cur[col], 0);
            }
        }

        return prev[n - 1][0];
    }
}

