import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<Integer> goodIndices(int[] nums, int k) {
        int n = nums.length;
        List<Integer> result = new ArrayList<>();
        if (n < 2 * k + 1) {
            return result;
        }

        int[] left = new int[n];
        int[] right = new int[n];

        // left[i] = length of longest non‑increasing subarray ending at i (including i)
        left[0] = 1;
        for (int i = 1; i < n; i++) {
            if (nums[i - 1] >= nums[i]) {
                left[i] = left[i - 1] + 1;
            } else {
                left[i] = 1;
            }
        }

        // right[i] = length of longest non‑decreasing subarray starting at i (including i)
        right[n - 1] = 1;
        for (int i = n - 2; i >= 0; i--) {
            if (nums[i] <= nums[i + 1]) {
                right[i] = right[i + 1] + 1;
            } else {
                right[i] = 1;
            }
        }

        // check each candidate index
        for (int i = k; i <= n - k - 1; i++) {
            if (left[i - 1] >= k && right[i + 1] >= k) {
                result.add(i);
            }
        }

        return result;
    }
}

