import java.util.*;

public class Solution {
    public int mostProfitablePath(int[][] edges, int bob, int[] amount) {
        int n = amount.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        int[] distBob = new int[n];
        Arrays.fill(distBob, -1);
        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(bob);
        distBob[bob] = 0;
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            for (int nb : graph[cur]) {
                if (distBob[nb] == -1) {
                    distBob[nb] = distBob[cur] + 1;
                    queue.add(nb);
                }
            }
        }

        int[] distAlice = new int[n];
        Arrays.fill(distAlice, -1);
        queue.add(0);
        distAlice[0] = 0;
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            for (int nb : graph[cur]) {
                if (distAlice[nb] == -1) {
                    distAlice[nb] = distAlice[cur] + 1;
                    queue.add(nb);
                }
            }
        }

        long[] adjusted = new long[n];
        for (int i = 0; i < n; i++) {
            if (distAlice[i] < distBob[i]) {
                adjusted[i] = amount[i];
            } else if (distAlice[i] > distBob[i]) {
                adjusted[i] = 0;
            } else {
                adjusted[i] = amount[i] / 2; // amounts are even
            }
        }

        long[] best = new long[]{Long.MIN_VALUE};
        dfs(0, -1, 0L, adjusted, graph, best);
        return (int) best[0];
    }

    private void dfs(int node, int parent, long sum, long[] adjusted,
                     List<Integer>[] graph, long[] best) {
        long curSum = sum + adjusted[node];
        boolean isLeaf = (node != 0 && graph[node].size() == 1) ||
                         (node == 0 && graph[node].isEmpty());
        if (isLeaf) {
            if (curSum > best[0]) {
                best[0] = curSum;
            }
        }
        for (int nb : graph[node]) {
            if (nb == parent) continue;
            dfs(nb, node, curSum, adjusted, graph, best);
        }
    }
}

