import java.util.Arrays;

public class Solution {
    public int maxPalindromes(String s, int k) {
        int n = s.length();
        if (k > n) return 0;

        // palindrome table
        boolean[][] pal = new boolean[n][n];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = i; j < n; j++) {
                if (s.charAt(i) == s.charAt(j) && (j - i < 2 || pal[i + 1][j - 1])) {
                    pal[i][j] = true;
                }
            }
        }

        // minimal ending index for a palindrome starting at i with length >= k
        int[] minEnd = new int[n];
        Arrays.fill(minEnd, -1);
        for (int i = 0; i < n; i++) {
            for (int end = i + k - 1; end < n; end++) {
                if (pal[i][end]) {
                    minEnd[i] = end;
                    break;
                }
            }
        }

        // dp[i] = max number of substrings we can obtain from suffix starting at i
        int[] dp = new int[n + 1];
        dp[n] = 0;
        for (int i = n - 1; i >= 0; i--) {
            dp[i] = dp[i + 1]; // skip position i
            if (minEnd[i] != -1) {
                dp[i] = Math.max(dp[i], 1 + dp[minEnd[i] + 1]);
            }
        }
        return dp[0];
    }
}

