import java.util.*;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int beautifulPartitions(String s, int k, int l) {
        int n = s.length();
        if (n == 0) return 0;

        boolean[] isPrimeStart = new boolean[n];
        boolean[] isNonPrimeEnd = new boolean[n];
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            boolean isPrime = (c == '2' || c == '3' || c == '5' || c == '7');
            isPrimeStart[i] = isPrime;
            isNonPrimeEnd[i] = !isPrime; // digits are 1-9, so non‑prime is the complement
        }

        // dp[i][j] – ways to partition prefix ending at i into j valid substrings
        long[][] dp = new long[n][k + 1];
        // pref[j][i] – prefix sum of dp[p][j] for p ≤ i where the next segment would start with a prime digit
        long[][] pref = new long[k + 1][n];

        for (int i = 0; i < n; i++) {
            if (!isNonPrimeEnd[i]) {
                // cannot end a segment here, all dp[i][*] stay 0
                // still need to update pref with zeros (no effect)
                for (int j = 1; j <= k; j++) {
                    if (i == 0) {
                        pref[j][i] = 0;
                    } else {
                        pref[j][i] = pref[j][i - 1];
                    }
                }
                continue;
            }

            // j = 1 (first segment starts at 0)
            if (i + 1 >= l && isPrimeStart[0]) {
                dp[i][1] = 1;
            }

            // j >= 2
            for (int j = 2; j <= k; j++) {
                int maxPrev = i - l;
                if (maxPrev >= 0) {
                    dp[i][j] = pref[j - 1][maxPrev];
                }
            }

            // update prefix sums for future transitions
            for (int j = 1; j <= k; j++) {
                long add = 0;
                if (i + 1 < n && isPrimeStart[i + 1]) {
                    add = dp[i][j];
                }
                if (i == 0) {
                    pref[j][i] = add % MOD;
                } else {
                    pref[j][i] = (pref[j][i - 1] + add) % MOD;
                }
            }
        }

        return (int) (dp[n - 1][k] % MOD);
    }
}

