    private int zeroCutCount;

    public int componentValue(int[] nums, int[][] edges) {
        int n = nums.length;
        values = nums;
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        long total = 0L;
        for (int v : nums) {
            total += v;
        }

        // Special case: total sum is zero
        if (total == 0L) {
            zeroCutCount = 0;
            dfsZero(0, -1);
            return zeroCutCount;
        }

        // Collect all positive divisors of total sum
        List<Long> divisors = new ArrayList<>();
        for (long d = 1; d * d <= total; d++) {
            if (total % d == 0) {
                divisors.add(d);
                if (d != total / d) {
                    divisors.add(total / d);
                }
            }
        }
        Collections.sort(divisors); // ascending target sum -> descending component count

        for (long target : divisors) {
            if (canPartition(target)) {
                int components = (int) (total / target);
                return components - 1; // number of deletable edges
            }
        }

        // If no partition possible, cannot delete any edge
        return 0;
    }

    // Checks if we can split the tree into components each having sum = target
    private boolean canPartition(long target) {
        return dfsPartition(0, -1, target) == 0L;
    }

    // Returns the accumulated sum of the current subtree after cutting off completed components.
    // Returns -1 if impossible.
    private long dfsPartition(int node, int parent, long target) {
        long sum = values[node];
        for (int nei : graph[node]) {
            if (nei == parent) continue;
            long childSum = dfsPartition(nei, node, target);
            if (childSum == -1L) return -1L;
            sum += childSum;
        }
        if (sum == target) {
            return 0L; // this subtree forms a component and is cut off
        }
        if (sum > target) {
            return -1L; // exceeds target, impossible
        }
        return sum; // propagate upward
    }

    // For total sum == 0: count edges whose removal yields a zero‑sum component
    private long dfsZero(int node, int parent) {
        long sum = values[node];
        for (int nei : graph[node]) {
            if (nei == parent) continue;
            sum += dfsZero(nei, node);
        }
        if (sum == 0L && parent != -1) {
            zeroCutCount++;
            return 0L; // cut this edge
        }
        return sum;
    }
}

