import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class Solution {
    public long minCost(int[] nums, int[] cost) {
        int n = nums.length;
        List<int[]> pairs = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            pairs.add(new int[]{nums[i], cost[i]});
        }
        pairs.sort(Comparator.comparingInt(a -> a[0]));

        long totalWeight = 0;
        for (int[] p : pairs) {
            totalWeight += p[1];
        }

        long prefix = 0;
        int median = 0;
        for (int[] p : pairs) {
            prefix += p[1];
            if (prefix * 2 >= totalWeight) {
                median = p[0];
                break;
            }
        }

        long answer = 0;
        for (int[] p : pairs) {
            answer += Math.abs((long) p[0] - median) * p[1];
        }
        return answer;
    }
}

