public class Solution {
    public int bestClosingTime(String customers) {
        int n = customers.length();
        int totalY = 0;
        for (int i = 0; i < n; i++) {
            if (customers.charAt(i) == 'Y') {
                totalY++;
            }
        }

        int countNOpen = 0;   // N's in the open interval [0, j)
        int countYSeen = 0;   // Y's in the open interval [0, j)
        int bestHour = 0;
        int minPenalty = Integer.MAX_VALUE;

        for (int j = 0; j <= n; j++) {
            int penalty = countNOpen + (totalY - countYSeen);
            if (penalty < minPenalty) {
                minPenalty = penalty;
                bestHour = j;
            }
            // prepare for next j (increase prefix by one character)
            if (j < n) {
                char c = customers.charAt(j);
                if (c == 'N') {
                    countNOpen++;
                } else { // 'Y'
                    countYSeen++;
                }
            }
        }

        return bestHour;
    }
