public class Solution {
    public long makeIntegerBeautiful(long n, int target) {
        if (digitSum(n) <= target) {
            return 0L;
        }
        long original = n;
        long pow10 = 1L;
        for (int i = 0; i <= 18; i++) {
            long prefix = n / pow10 + 1;
            long candidate = prefix * pow10;
            if (digitSum(candidate) <= target) {
                return candidate - original;
            }
            pow10 *= 10L;
        }
        // Fallback (should never be reached with valid inputs)
        return 0L;
    }

    private int digitSum(long value) {
        int sum = 0;
        while (value > 0) {
            sum += (int) (value % 10);
            value /= 10;
        }
        return sum;
    }
}

