import java.util.*;

public class Solution {

    public int longestSubsequence(int[] nums, int k) {
        if (nums == null || nums.length == 0) {
            return 0;
        }

        // coordinate compression of values in nums
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        int m = 0;
        for (int i = 0; i < sorted.length; i++) {
            if (i == 0 || sorted[i] != sorted[i - 1]) {
                sorted[m++] = sorted[i];
            }
        }
        int[] values = Arrays.copyOf(sorted, m);
        Map<Integer, Integer> indexMap = new HashMap<>();
        for (int i = 0; i < m; i++) {
            indexMap.put(values[i], i);
        }

        SegTree seg = new SegTree(m);
        int answer = 0;

        for (int num : nums) {
            int leftVal = num - k;
            int rightVal = num - 1;

            int lIdx = lowerBound(values, leftVal);
            int rIdx = upperBound(values, rightVal) - 1;

            int best = 0;
            if (lIdx <= rIdx) {
                best = seg.query(lIdx, rIdx);
            }

            int cur = best + 1;
            int pos = indexMap.get(num);
            // keep the maximum dp value for this exact value
            seg.update(pos, cur);

            if (cur > answer) {
                answer = cur;
            }
        }

        return answer;
    }

    // segment tree for range maximum query and point update (max)
    private static class SegTree {
        private final int n;
        private final int[] tree;

        public SegTree(int size) {
            int pow = 1;
            while (pow < size) {
                pow <<= 1;
            }
            this.n = pow;
            this.tree = new int[2 * n];
        }

        // set position idx to max(current, value)
        public void update(int idx, int value) {
            int pos = idx + n;
            tree[pos] = Math.max(tree[pos], value);
            pos >>= 1;
            while (pos > 0) {
                tree[pos] = Math.max(tree[pos << 1], tree[(pos << 1) | 1]);
                pos >>= 1;
            }
        }

        // query maximum in inclusive range [l, r]
        public int query(int l, int r) {
            if (l > r) {
                return 0;
            }
            int res = 0;
            int left = l + n;
            int right = r + n;
            while (left <= right) {
                if ((left & 1) == 1) {
                    res = Math.max(res, tree[left]);
                    left++;
                }
                if ((right & 1) == 0) {
                    res = Math.max(res, tree[right]);
                    right--;
                }
                left >>= 1;
                right >>= 1;
            }
            return res;
        }
    }

    // first index >= target
    private static int lowerBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    // first index > target
    private static int upperBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] <= target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

