import java.util.*;

public class Solution {
    private static class DSU {
        int[] parent;
        int[] rank;
        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        void union(int x, int y) {
            int rx = find(x);
            int ry = find(y);
            if (rx == ry) return;
            if (rank[rx] < rank[ry]) {
                parent[rx] = ry;
            } else if (rank[rx] > rank[ry]) {
                parent[ry] = rx;
            } else {
                parent[ry] = rx;
                rank[rx]++;
            }
        }
    }

    public int numberOfGoodPaths(int[] vals, int[][] edges) {
        int n = vals.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int a = e[0], b = e[1];
            graph[a].add(b);
            graph[b].add(a);
        }

        // nodes sorted by value
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, Comparator.comparingInt(i -> vals[i]));

        DSU dsu = new DSU(n);
        long answer = 0;

        int idx = 0;
        while (idx < n) {
            int curVal = vals[order[idx]];
            // process all nodes with this value
            int start = idx;
            while (idx < n && vals[order[idx]] == curVal) idx++;
            // union with neighbors whose value <= curVal
            for (int i = start; i < idx; i++) {
                int node = order[i];
                for (int nb : graph[node]) {
                    if (vals[nb] <= curVal) {
                        dsu.union(node, nb);
                    }
                }
            }
            // count nodes of this value per component
            Map<Integer, Integer> compCount = new HashMap<>();
            for (int i = start; i < idx; i++) {
                int root = dsu.find(order[i]);
                compCount.put(root, compCount.getOrDefault(root, 0) + 1);
            }
            for (int cnt : compCount.values()) {
                // each node itself is a good path, plus pairs
                answer += (long) cnt * (cnt + 1) / 2;
            }
        }

        return (int) answer;
    }
}

