public class Solution {
    public int minimizeXor(int num1, int num2) {
        int k = Integer.bitCount(num2);
        int x = 0;
        // First, set bits where num1 has 1, starting from most significant bit
        for (int i = 31; i >= 0 && k > 0; i--) {
            if (((num1 >> i) & 1) == 1) {
                x |= (1 << i);
                k--;
            }
        }
        // Then, set remaining bits where num1 has 0, starting from least significant bit
        for (int i = 0; i <= 31 && k > 0; i++) {
            if (((num1 >> i) & 1) == 0) {
                x |= (1 << i);
                k--;
            }
        }
        return x;
    }
}

