import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int[] secondGreaterElement(int[] nums) {
        int n = nums.length;
        int[] answer = new int[n];
        for (int i = 0; i < n; i++) {
            answer[i] = -1;
        }

        Deque<Integer> firstStack = new ArrayDeque<>();   // indices waiting for first greater
        Deque<Integer> secondStack = new ArrayDeque<>();  // indices waiting for second greater

        for (int i = 0; i < n; i++) {
            int cur = nums[i];

            // Resolve second greater for indices in secondStack
            while (!secondStack.isEmpty() && nums[secondStack.peek()] < cur) {
                int idx = secondStack.pop();
                answer[idx] = cur;
            }

            // Move indices that found their first greater to secondStack
            while (!firstStack.isEmpty() && nums[firstStack.peek()] < cur) {
                int idx = firstStack.pop();
                secondStack.push(idx);
            }

            // Current index may become first greater for future elements
            firstStack.push(i);
        }

        return answer;
    }
}

