import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public int mostBooked(int n, int[][] meetings) {
        // sort meetings by original start time
        Arrays.sort(meetings, (a, b) -> Integer.compare(a[0], b[0]));

        // available rooms: smallest index first
        PriorityQueue<Integer> freeRooms = new PriorityQueue<>();
        for (int i = 0; i < n; i++) {
            freeRooms.offer(i);
        }

        // occupied rooms: ordered by earliest finishing time,
        // each element is [endTime, roomIndex]
        PriorityQueue<long[]> occupied = new PriorityQueue<>(
                (a, b) -> {
                    if (a[0] == b[0]) {
                        return Long.compare(a[1], b[1]);
                    }
                    return Long.compare(a[0], b[0]);
                });

        int[] count = new int[n];

        for (int[] meeting : meetings) {
            int start = meeting[0];
            int end = meeting[1];
            long duration = (long) end - start;

            // release rooms that have become free by current start time
            while (!occupied.isEmpty() && occupied.peek()[0] <= start) {
                long[] freed = occupied.poll();
                freeRooms.offer((int) freed[1]);
            }

            if (!freeRooms.isEmpty()) {
                // assign the smallest indexed free room
                int room = freeRooms.poll();
                long newEnd = (long) start + duration;
                occupied.offer(new long[]{newEnd, room});
                count[room]++;
            } else {
                // all rooms are busy, delay the meeting
                long[] earliest = occupied.poll();
                int room = (int) earliest[1];
                long newStart = earliest[0];
                long newEnd = newStart + duration;
                occupied.offer(new long[]{newEnd, room});
                count[room]++;
            }
        }

        // find the room with the maximum meetings, tie-breaking by smallest index
        int bestRoom = 0;
        int maxMeetings = count[0];
        for (int i = 1; i < n; i++) {
            if (count[i] > maxMeetings) {
                maxMeetings = count[i];
                bestRoom = i;
            }
        }
        return bestRoom;
    }
}

