public class Solution {
    public long countSubarrays(int[] nums, int minK, int maxK) {
        long result = 0L;
        int lastInvalid = -1; // index of most recent element outside [minK, maxK]
        int lastMin = -1;     // most recent index where nums[i] == minK
        int lastMax = -1;     // most recent index where nums[i] == maxK

        for (int i = 0; i < nums.length; i++) {
            int val = nums[i];

            // If current value breaks the allowed range, reset tracking indices
            if (val < minK || val > maxK) {
                lastInvalid = i;
                lastMin = -1;
                lastMax = -1;
                continue;
            }

            // Update positions of minK and maxK when encountered
            if (val == minK) {
                lastMin = i;
            }
            if (val == maxK) {
                lastMax = i;
            }

            // Number of valid subarrays ending at i is determined by the
            // earliest of the last minK/maxK positions that is still after lastInvalid
            int validStart = Math.min(lastMin, lastMax);
            if (validStart > lastInvalid) {
                result += (validStart - lastInvalid);
            }
        }

        return result;
    }
}

