import java.util.ArrayList;
import java.util.List;

public class Solution {
    private static final int MOD = 1_000_000_007;

    private long modPow(long base, long exp) {
        long result = 1L;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1L) == 1L) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    public int[] productQueries(int n, int[][] queries) {
        // Extract exponents of set bits (powers of two) in ascending order
        List<Integer> exponents = new ArrayList<>();
        long value = n & 0xffffffffL; // treat as unsigned if needed
        int position = 0;
        while (value != 0) {
            if ((value & 1L) == 1L) {
                exponents.add(position);
            }
            value >>= 1;
            position++;
        }

        int m = exponents.size();
        long[] prefix = new long[m + 1];
        for (int i = 0; i < m; i++) {
            prefix[i + 1] = prefix[i] + exponents.get(i);
        }

        int[] answers = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int left = queries[i][0];
            int right = queries[i][1];
            long sumExp = prefix[right + 1] - prefix[left];
            answers[i] = (int) modPow(2L, sumExp);
        }
        return answers;
    }
}

