import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class Solution {
    public int magnificentSets(int n, int[][] edges) {
        List<Integer>[] graph = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int a = e[0];
            int b = e[1];
            graph[a].add(b);
            graph[b].add(a);
        }

        boolean[] visited = new boolean[n + 1];
        int[] color = new int[n + 1]; // 0 = uncolored, 1 or -1
        int answer = 0;

        for (int i = 1; i <= n; i++) {
            if (visited[i]) continue;

            // Collect component and check bipartite
            List<Integer> component = new ArrayList<>();
            Queue<Integer> q = new LinkedList<>();
            q.offer(i);
            visited[i] = true;
            color[i] = 1;

            while (!q.isEmpty()) {
                int u = q.poll();
                component.add(u);
                for (int v : graph[u]) {
                    if (!visited[v]) {
                        visited[v] = true;
                        color[v] = -color[u];
                        q.offer(v);
                    } else {
                        if (color[v] == color[u]) {
                            return -1; // not bipartite
                        }
                    }
                }
            }

            // Compute the maximum shortest‑path distance inside this component
            int maxDist = 0;
            for (int start : component) {
                int[] dist = new int[n + 1];
                Arrays.fill(dist, -1);
                Queue<Integer> bfs = new LinkedList<>();
                bfs.offer(start);
                dist[start] = 0;

                while (!bfs.isEmpty()) {
                    int cur = bfs.poll();
                    for (int nb : graph[cur]) {
                        if (dist[nb] == -1) {
                            dist[nb] = dist[cur] + 1;
                            bfs.offer(nb);
                        }
                    }
                }

                for (int node : component) {
                    if (dist[node] > maxDist) {
                        maxDist = dist[node];
                    }
                }
            }

            answer += maxDist + 1; // groups needed for this component
        }

        return answer;
    }
}

