import java.util.ArrayList;
import java.util.List;

public class Solution {
    /**
     * Returns all words from {@code queries} that can be transformed into
     * some word from {@code dictionary} with at most two character edits.
     *
     * @param queries    array of query words (all same length)
     * @param dictionary array of dictionary words (all same length as queries)
     * @return list of matching query words in the original order
     */
    public List<String> findWords(String[] queries, String[] dictionary) {
        List<String> result = new ArrayList<>();
        if (queries == null || dictionary == null || queries.length == 0 || dictionary.length == 0) {
            return result;
        }

        int wordLength = queries[0].length(); // all words have same length

        for (String query : queries) {
            // quick skip if length differs (should not happen per problem statement)
            if (query.length() != wordLength) {
                continue;
            }
            boolean matches = false;
            for (String dictWord : dictionary) {
                // also ensure same length
                if (dictWord.length() != wordLength) {
                    continue;
                }
                int mismatches = 0;
                for (int i = 0; i < wordLength; i++) {
                    if (query.charAt(i) != dictWord.charAt(i)) {
                        mismatches++;
                        if (mismatches > 2) {
                            break; // more than two edits, stop checking this dict word
                        }
                    }
                }
                if (mismatches <= 2) {
                    matches = true;
                    break; // no need to check other dictionary words
                }
            }
            if (matches) {
                result.add(query);
            }
        }
        return result;
    }
}

