import java.util.*;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int countPalindromes(String s) {
        int n = s.length();
        if (n < 5) return 0;

        // suffixPairs[i][b*10 + a] = number of pairs (l,m) with l>i, s[l]=b, s[m]=a
        int[][] suffixPairs = new int[n][100];
        int[] cnt = new int[10];
        int[][] pair = new int[10][10];

        for (int i = n - 1; i >= 0; i--) {
            // store current pair counts for positions > i
            int[] row = suffixPairs[i];
            for (int a = 0; a < 10; a++) {
                for (int b = 0; b < 10; b++) {
                    row[a * 10 + b] = pair[a][b];
                }
            }
            int d = s.charAt(i) - '0';
            // add new pairs where the first element is at i (digit d)
            for (int a = 0; a < 10; a++) {
                pair[d][a] = (pair[d][a] + cnt[a]) % MOD;
            }
            cnt[d]++;
        }

        int[] leftCnt = new int[10];
        int[][] leftPair = new int[10][10];
        long ans = 0;

        for (int k = 0; k < n; k++) {
            int mid = s.charAt(k) - '0';
            int[] row = suffixPairs[k];
            for (int a = 0; a < 10; a++) {
                for (int b = 0; b < 10; b++) {
                    long left = leftPair[a][b];
                    long right = row[b * 10 + a]; // b as first, a as second in the suffix pair
                    ans = (ans + left * right) % MOD;
                }
            }
            // update left pairs where the second index is k
            for (int a = 0; a < 10; a++) {
                leftPair[a][mid] = (leftPair[a][mid] + leftCnt[a]) % MOD;
            }
            leftCnt[mid]++;
        }

        return (int) ans;
    }
}

