import java.util.*;

public class Solution {
    public String[] splitMessage(String message, int limit) {
        int n = message.length();
        if (limit < 5) return new String[0]; // minimal suffix length is 5 ("<1/1>")
        // Upper bound for parts: at most n (one character per part)
        int low = 1, high = n;
        int answer = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (feasible(message, limit, mid)) {
                answer = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        if (answer == -1) return new String[0];
        return buildParts(message, limit, answer);
    }

    private boolean feasible(String message, int limit, int b) {
        int lenB = digits(b);
        // suffix length of the longest part (when a also has lenB digits)
        if (2 * lenB + 3 > limit) return false; // some suffix longer than limit
        long totalCap = 0;
        long capLast = limit - (lenB + lenB + 3);
        if (capLast < 0) return false;
        // compute total capacity using digit groups
        int start = 1;
        for (int d = 1; d <= lenB; d++) {
            int end = Math.min(b, (int) (Math.pow(10, d) - 1));
            if (start > end) break;
            int count = end - start + 1;
            int suffixLen = d + lenB + 3;
            int cap = limit - suffixLen;
            if (cap < 0) return false;
            totalCap += (long) count * cap;
            start = end + 1;
        }
        long totalMinusLast = totalCap - capLast;
        int msgLen = message.length();
        return msgLen >= totalMinusLast && msgLen <= totalCap;
    }

    private String[] buildParts(String message, int limit, int b) {
        String[] res = new String[b];
        int pos = 0;
        int lenB = digits(b);
        for (int i = 1; i <= b; i++) {
            int lenA = digits(i);
            String suffix = "<" + i + "/" + b + ">";
            int suffixLen = suffix.length(); // equals lenA + lenB + 3
            int capacity = limit - suffixLen;
            int take;
            if (i == b) {
                take = Math.max(0, message.length() - pos);
            } else {
                take = capacity;
            }
            if (take > message.length() - pos) {
                take = message.length() - pos; // safety, should not happen due to feasibility check
            }
            String part = message.substring(pos, pos + take) + suffix;
            res[i - 1] = part;
            pos += take;
        }
        return res;
    }

    private int digits(int x) {
        // x > 0
        return Integer.toString(x).length();
    }
}

