import java.util.HashMap;
import java.util.Map;

public class Solution {
    public long maximumSubarraySum(int[] nums, int k) {
        if (nums == null || k > nums.length || k <= 0) {
            return 0L;
        }

        Map<Integer, Integer> freq = new HashMap<>();
        long sum = 0;
        long max = 0;
        int left = 0;

        for (int right = 0; right < nums.length; right++) {
            int val = nums[right];
            sum += val;
            freq.put(val, freq.getOrDefault(val, 0) + 1);

            // shrink window to size k
            if (right - left + 1 > k) {
                int leftVal = nums[left];
                sum -= leftVal;
                int cnt = freq.get(leftVal) - 1;
                if (cnt == 0) {
                    freq.remove(leftVal);
                } else {
                    freq.put(leftVal, cnt);
                }
                left++;
            }

            // when window size equals k, evaluate
            if (right - left + 1 == k) {
                if (freq.size() == k) { // all distinct
                    if (sum > max) {
                        max = sum;
                    }
                }
            }
        }

        return max;
    }
}

