import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int subarrayLCM(int[] nums, int k) {
        long limit = k;
        long result = 0;
        Map<Long, Integer> prev = new HashMap<>();

        for (int num : nums) {
            Map<Long, Integer> cur = new HashMap<>();

            // start a new subarray at current position
            long l = num;
            if (l <= limit) {
                cur.put(l, cur.getOrDefault(l, 0) + 1);
            }

            // extend previous subarrays
            for (Map.Entry<Long, Integer> entry : prev.entrySet()) {
                long prevLcm = entry.getKey();
                int cnt = entry.getValue();
                long newLcm = lcmLimited(prevLcm, num, limit);
                if (newLcm <= limit) {
                    cur.put(newLcm, cur.getOrDefault(newLcm, 0) + cnt);
                }
            }

            result += cur.getOrDefault(limit, 0);
            prev = cur;
        }

        return (int) result;
    }

    private static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    private static long lcmLimited(long a, long b, long limit) {
        long g = gcd(a, b);
        long div = a / g;
        // if div * b would exceed limit, return limit+1 to indicate overflow
        if (div > limit / b) {
            return limit + 1;
        }
        long res = div * b;
        return res;
    }
}

