public class Solution {
    public int commonFactors(int a, int b) {
        int g = gcd(a, b);
        int count = 0;
        int sqrt = (int) Math.sqrt(g);
        for (int i = 1; i <= sqrt; i++) {
            if (g % i == 0) {
                count++; // i is a divisor
                int other = g / i;
                if (other != i) {
                    count++; // paired divisor
                }
            }
        }
        return count;
    }

    private int gcd(int x, int y) {
        while (y != 0) {
            int tmp = x % y;
            x = y;
            y = tmp;
        }
        return x;
    }
}

