import java.util.*;

public class Solution {
    public long minimumTotalCost(int[] nums1, int[] nums2) {
        int n = nums1.length;
        // Count frequencies of values in nums1
        Map<Integer, Integer> freq1 = new HashMap<>();
        for (int v : nums1) freq1.put(v, freq1.getOrDefault(v, 0) + 1);
        // Count how many positions each value is forbidden (where nums2 has that value)
        Map<Integer, Integer> forbid = new HashMap<>();
        for (int v : nums2) forbid.put(v, forbid.getOrDefault(v, 0) + 1);
        // Feasibility check: for each value, we must have enough places where it can be placed
        for (Map.Entry<Integer, Integer> e : freq1.entrySet()) {
            int val = e.getKey();
            int cnt = e.getValue();
            int bad = forbid.getOrDefault(val, 0);
            if (cnt > n - bad) return -1;
        }

        // Build bipartite graph: left side = original indices, right side = target positions
        // Edge exists if nums1[left] != nums2[right]
        // We need a perfect matching with minimal total swap cost.
        // Since swap cost depends on the permutation cycles, we will search over matchings
        // using a minimum-cost maximum-flow where the cost of assigning left i to right j is i (the cost of moving i once).
        // The total cost of swaps for a permutation σ can be computed from its cycles:
        // For each cycle C with indices {c1,...,ck}, minimal cost = sum(C) + (k - 2) * min(C)
        // or using global minimum index g: sum(C) + min(C) + (k + 1) * g
        // The overall minimal cost is the sum of minimal costs of all cycles.

        // To avoid exponential search, we use the following constructive algorithm:
        // 1. Start with all positions where nums1[i] != nums2[i] (already good). They need no change.
        // 2. Collect all bad positions B = {i | nums1[i] == nums2[i]}.
        // 3. If |B| is even, we can pair them arbitrarily using swaps that keep values valid.
        //    The minimal additional cost is the sum of indices in B.
        // 4. If |B| is odd, we need one extra good position g to participate.
        //    Choose the good position with the smallest index that can be swapped safely.
        //    The extra cost becomes sum(B) + g.

        List<Integer> bad = new ArrayList<>();
        List<Integer> good = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (nums1[i] == nums2[i]) bad.add(i);
            else good.add(i);
        }

        long cost = 0;
        for (int idx : bad) cost += idx;

        if (bad.size() % 2 == 0) {
            return cost;
        } else {
            // Need to find the minimal index among good positions that can be used.
            // A good position g is usable if swapping its value with some bad position
            // does not create a new conflict at g.
            int minExtra = Integer.MAX_VALUE;
            for (int g : good) {
                // Check if there exists a bad position b such that after swapping,
                // nums1[g] (original good value) != nums2[b] and nums1[b] (original bad value) != nums2[g]
                for (int b : bad) {
                    if (nums1[g] != nums2[b] && nums1[b] != nums2[g]) {
                        minExtra = Math.min(minExtra, g);
                        break;
                    }
                }
                if (minExtra == g) break; // smallest possible found
            }
            if (minExtra == Integer.MAX_VALUE) {
                // No single good position works, we need to involve two good positions.
                // Choose the two smallest good indices.
                if (good.size() < 2) return -1;
                Collections.sort(good);
                minExtra = good.get(0) + good.get(1);
                return cost + minExtra;
            } else {
                return cost + minExtra;
            }
        }
    }
}

