import java.util.HashMap;
import java.util.Map;

public class Solution {
    private int m, n, total;
    private int[] pow3;
    private Map<Long, Integer> memo;

    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        this.m = m;
        this.n = n;
        this.total = m * n;
        this.pow3 = new int[n];
        pow3[0] = 1;
        for (int i = 1; i < n; i++) {
            pow3[i] = pow3[i - 1] * 3;
        }
        this.memo = new HashMap<>();
        return dfs(0, 0, introvertsCount, extrovertsCount, 0);
    }

    private int dfs(int pos, int mask, int introLeft, int extroLeft, int left) {
        if (pos == total) {
            return 0;
        }
        long key = encode(pos, mask, introLeft, extroLeft, left);
        Integer cached = memo.get(key);
        if (cached != null) {
            return cached;
        }

        int col = pos % n;
        // When we start a new row, there is no left neighbor
        if (col == 0) {
            left = 0;
        }

        int best = dfs(pos + 1, mask / 3, introLeft, extroLeft, 0); // leave empty

        // Try placing an introvert
        if (introLeft > 0) {
            int cur = 1; // introvert
            int gain = 120;
            int up = mask % 3;
            if (up != 0) {
                gain += neighborEffect(up, cur) + neighborEffect(cur, up);
            }
            if (left != 0) {
                gain += neighborEffect(left, cur) + neighborEffect(cur, left);
            }
            int newMask = (mask / 3) + cur * pow3[n - 1];
            int totalGain = gain + dfs(pos + 1, newMask, introLeft - 1, extroLeft, cur);
            if (totalGain > best) best = totalGain;
        }

        // Try placing an extrovert
        if (extroLeft > 0) {
            int cur = 2; // extrovert
            int gain = 40;
            int up = mask % 3;
            if (up != 0) {
                gain += neighborEffect(up, cur) + neighborEffect(cur, up);
            }
            if (left != 0) {
                gain += neighborEffect(left, cur) + neighborEffect(cur, left);
            }
            int newMask = (mask / 3) + cur * pow3[n - 1];
            int totalGain = gain + dfs(pos + 1, newMask, introLeft, extroLeft - 1, cur);
            if (totalGain > best) best = totalGain;
        }

        memo.put(key, best);
        return best;
    }

    private int neighborEffect(int neighborType, int myType) {
        // neighborType: 1 introvert, 2 extrovert
        // myType: 1 introvert, 2 extrovert
        if (myType == 1) { // introvert loses 30 per neighbor
            return -30;
        } else { // extrovert gains 20 per neighbor
            return 20;
        }
    }

    private long encode(int pos, int mask, int intro, int extro, int left) {
        long key = pos;
        key = (key << 9) | mask;          // mask fits in 9 bits (3^5 = 243 < 2^9)
        key = (key << 5) | intro;         // intro <= 25 fits in 5 bits
        key = (key << 5) | extro;         // extro <= 25 fits in 5 bits
        key = (key << 2) | left;          // left 0..2 fits in 2 bits
        return key;
    }
}

