        int[] dp = new int[n + 1];
        dp[0] = 0;

        Deque<Integer> deque = new ArrayDeque<>();
        deque.addLast(0); // candidate index 0

        int left = 0;
        for (int i = 1; i <= n; i++) {
            // shrink window to satisfy constraints
            while (i - left > maxBoxes || preWeight[i] - preWeight[left] > maxWeight) {
                if (!deque.isEmpty() && deque.peekFirst() == left) {
                    deque.pollFirst();
                }
                left++;
            }

            // best candidate at front
            int bestIdx = deque.peekFirst();
            dp[i] = dp[bestIdx] + (prePortChanges[i] - prePortChanges[bestIdx + 1]) + 2;

            // prepare value for current index to be used later
            if (i < n) { // no need to add after the last box, but harmless if added
                int curVal = dp[i] - prePortChanges[i + 1];
                while (!deque.isEmpty()) {
                    int lastIdx = deque.peekLast();
                    int lastVal = dp[lastIdx] - prePortChanges[lastIdx + 1];
                    if (lastVal <= curVal) {
                        break;
                    }
                    deque.pollLast();
                }
                deque.addLast(i);
            }
        }

        return dp[n];
    }
}

