import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Solution {
    public List<Boolean> checkArithmeticSubarrays(int[] nums, int[] l, int[] r) {
        List<Boolean> answer = new ArrayList<>(l.length);
        for (int i = 0; i < l.length; i++) {
            int left = l[i];
            int right = r[i];
            int len = right - left + 1;

            if (len <= 2) {
                answer.add(true);
                continue;
            }

            int min = Integer.MAX_VALUE;
            int max = Integer.MIN_VALUE;
            for (int j = left; j <= right; j++) {
                int val = nums[j];
                if (val < min) min = val;
                if (val > max) max = val;
            }

            int diff = max - min;
            if (diff % (len - 1) != 0) {
                answer.add(false);
                continue;
            }

            int step = diff / (len - 1);
            if (step == 0) {
                // all elements must be equal
                boolean allEqual = true;
                for (int j = left + 1; j <= right; j++) {
                    if (nums[j] != nums[left]) {
                        allEqual = false;
                        break;
                    }
                }
                answer.add(allEqual);
                continue;
            }

            Set<Integer> seen = new HashSet<>(len);
            boolean ok = true;
            for (int j = left; j <= right; j++) {
                int val = nums[j];
                int offset = val - min;
                if (offset % step != 0) {
                    ok = false;
                    break;
                }
                int pos = offset / step;
                if (pos < 0 || pos >= len) {
                    ok = false;
                    break;
                }
                if (!seen.add(val)) {
                    ok = false;
                    break;
                }
            }
            answer.add(ok);
        }
        return answer;
    }
}

