public class Solution {
    public boolean canDistribute(int[] nums, int[] quantity) {
        // Count frequencies of each unique number
        Map<Integer, Integer> map = new HashMap<>();
        for (int num : nums) {
            map.put(num, map.getOrDefault(num, 0) + 1);
        }
        int[] counts = new int[map.size()];
        int idx = 0;
        for (int v : map.values()) {
            counts[idx++] = v;
        }

        int m = quantity.length;
        int totalMasks = 1 << m;
        int[] sum = new int[totalMasks];
        for (int mask = 1; mask < totalMasks; mask++) {
            int lsb = Integer.numberOfTrailingZeros(mask);
            int prev = mask ^ (1 << lsb);
            sum[mask] = sum[prev] + quantity[lsb];
        }

        boolean[] dp = new boolean[totalMasks];
        dp[0] = true;

        for (int cnt : counts) {
            boolean[] next = dp.clone();
            for (int mask = 0; mask < totalMasks; mask++) {
                if (!dp[mask]) continue;
                int remaining = (~mask) & (totalMasks - 1);
                // iterate over all non‑empty subsets of remaining
                for (int sub = remaining; sub > 0; sub = (sub - 1) & remaining) {
                    if (sum[sub] <= cnt) {
                        next[mask | sub] = true;
                    }
                }
            }
            dp = next;
        }

        return dp[totalMasks - 1];
    }
}

