public class Solution {
    private static final int MOD = 1_000_000_007;

    private static class BIT {
        private final long[] tree;
        private final int n;

        BIT(int n) {
            this.n = n;
            this.tree = new long[n + 2];
        }

        void update(int index, long delta) {
            while (index <= n) {
                tree[index] += delta;
                index += index & -index;
            }
        }

        long query(int index) {
            long sum = 0;
            while (index > 0) {
                sum += tree[index];
                index -= index & -index;
            }
            return sum;
        }
    }

    public int createSortedArray(int[] instructions) {
        int n = instructions.length;
        // Coordinate compression
        int[] sorted = instructions.clone();
        Arrays.sort(sorted);
        int m = 0;
        Map<Integer, Integer> map = new HashMap<>();
        for (int value : sorted) {
            if (!map.containsKey(value)) {
                map.put(value, ++m);
            }
        }

        BIT bit = new BIT(m);
        long totalCost = 0;

        for (int i = 0; i < n; i++) {
            int idx = map.get(instructions[i]);
            long less = bit.query(idx - 1);
            long greater = i - bit.query(idx);
            totalCost += Math.min(less, greater);
            if (totalCost >= MOD) totalCost %= MOD;
            bit.update(idx, 1);
        }

        return (int) (totalCost % MOD);
    }
}

