import java.util.*;

public class Solution {
    public int minimumIncompatibility(int[] nums, int k) {
        int n = nums.length;
        if (n % k != 0) return -1;
        int subsetSize = n / k;

        // Frequency check: no element may appear more than k times
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : nums) {
            freq.put(v, freq.getOrDefault(v, 0) + 1);
            if (freq.get(v) > k) return -1;
        }

        int totalMask = 1 << n;
        int[] incompat = new int[totalMask];
        Arrays.fill(incompat, -1);

        // Pre‑compute incompatibility for every mask of size subsetSize without duplicates
        for (int mask = 0; mask < totalMask; mask++) {
            if (Integer.bitCount(mask) != subsetSize) continue;
            boolean ok = true;
            int min = Integer.MAX_VALUE;
            int max = Integer.MIN_VALUE;
            Set<Integer> seen = new HashSet<>();
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    int val = nums[i];
                    if (!seen.add(val)) {
                        ok = false;
                        break;
                    }
                    if (val < min) min = val;
                    if (val > max) max = val;
                }
            }
            if (ok) {
                incompat[mask] = max - min;
            }
        }

        // Collect all valid group masks
        List<Integer> validGroups = new ArrayList<>();
        for (int mask = 0; mask < totalMask; mask++) {
            if (incompat[mask] != -1) {
                validGroups.add(mask);
            }
        }

        long INF = Long.MAX_VALUE / 4;
        long[] dp = new long[totalMask];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        for (int mask = 0; mask < totalMask; mask++) {
            if (dp[mask] == INF) continue;
            // try to add a valid group that does not intersect with current mask
            for (int groupMask : validGroups) {
                if ((mask & groupMask) != 0) continue;
                int newMask = mask | groupMask;
                long newVal = dp[mask] + incompat[groupMask];
                if (newVal < dp[newMask]) {
                    dp[newMask] = newVal;
                }
            }
        }

        long ans = dp[totalMask - 1];
        return ans == INF ? -1 : (int) ans;
    }
}

