import com_github_leetcode.TreeNode;
import java.util.Queue;
import java.util.LinkedList;

public class Solution {
    public boolean isEvenOddTree(TreeNode root) {
        if (root == null) {
            return true;
        }
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        int level = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            int prev;
            if (level % 2 == 0) {
                prev = Integer.MIN_VALUE; // need strictly increasing odd values
            } else {
                prev = Integer.MAX_VALUE; // need strictly decreasing even values
            }
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();
                int val = node.val;
                if (level % 2 == 0) {
                    // even level: values must be odd and increasing
                    if (val % 2 == 0 || val <= prev) {
                        return false;
                    }
                } else {
                    // odd level: values must be even and decreasing
                    if (val % 2 != 0 || val >= prev) {
                        return false;
                    }
                }
                prev = val;
                if (node.left != null) {
                    queue.offer(node.left);
                }
                if (node.right != null) {
                    queue.offer(node.right);
                }
            }
            level++;
        }
        return true;
    }
}

