public class Solution {
    public boolean canFormArray(int[] arr, int[][] pieces) {
        // Map the first element of each piece to the piece itself for O(1) lookup
        Map<Integer, int[]> firstToPiece = new HashMap<>();
        for (int[] piece : pieces) {
            if (piece.length > 0) {
                firstToPiece.put(piece[0], piece);
            }
        }

        int i = 0;
        while (i < arr.length) {
            int current = arr[i];
            int[] piece = firstToPiece.get(current);
            if (piece == null) {
                // No piece starts with this number
                return false;
            }
            // Verify that the whole piece matches the segment in arr
            for (int num : piece) {
                if (i >= arr.length || arr[i] != num) {
                    return false;
                }
                i++;
            }
        }
        return true;
    }
}

