public class Solution {
    public int countSubstrings(String s, String t) {
        int n = s.length();
        int m = t.length();
        int[][] pre = new int[n + 1][m + 1];
        int[][] suf = new int[n + 1][m + 1];

        // pre[i][j] = length of longest common suffix ending at s[i-1] and t[j-1]
        for (int i = 1; i <= n; i++) {
            char cs = s.charAt(i - 1);
            for (int j = 1; j <= m; j++) {
                if (cs == t.charAt(j - 1)) {
                    pre[i][j] = pre[i - 1][j - 1] + 1;
                } else {
                    pre[i][j] = 0;
                }
            }
        }

        // suf[i][j] = length of longest common prefix starting at s[i] and t[j]
        for (int i = n - 1; i >= 0; i--) {
            char cs = s.charAt(i);
            for (int j = m - 1; j >= 0; j--) {
                if (cs == t.charAt(j)) {
                    suf[i][j] = suf[i + 1][j + 1] + 1;
                } else {
                    suf[i][j] = 0;
                }
            }
        }

        long ans = 0L;
        for (int i = 0; i < n; i++) {
            char cs = s.charAt(i);
            for (int j = 0; j < m; j++) {
                if (cs != t.charAt(j)) {
                    ans += (long) (pre[i][j] + 1) * (suf[i + 1][j + 1] + 1);
                }
            }
        }
        return (int) ans;
    }
}

