            for (int[] pos : positions) {
                int i = pos[0];
                int j = pos[1];
                dsu.union(i, m + j);
            }

            // compute the maximum rank for each component
            Map<Integer, Integer> compMax = new HashMap<>();
            for (int[] pos : positions) {
