public class Solution {
    private static class DSU {
        private final int[] parent;
        private final int[] rank;

        DSU(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) return;

            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    public List<Boolean> areConnected(int n, int threshold, int[][] queries) {
        DSU dsu = new DSU(n + 1); // 1‑based indexing

        // Union all numbers that share a divisor greater than threshold
        for (int d = threshold + 1; d <= n; d++) {
            int firstMultiple = d;
            for (int multiple = 2 * d; multiple <= n; multiple += d) {
                dsu.union(firstMultiple, multiple);
            }
        }

        List<Boolean> result = new ArrayList<>(queries.length);
        for (int[] q : queries) {
            int a = q[0];
            int b = q[1];
            result.add(dsu.find(a) == dsu.find(b));
        }
        return result;
    }
