public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numWays(String[] words, String target) {
        if (words == null || words.length == 0 || target == null) {
            return 0;
        }
        int m = words[0].length();
        int n = target.length();
        if (n > m) {
            return 0;
        }

        // count[c][pos] = number of words having character c at position pos
        int[][] count = new int[26][m];
        for (String w : words) {
            for (int pos = 0; pos < m; pos++) {
                char ch = w.charAt(pos);
                count[ch - 'a'][pos]++;
            }
        }

        long[] dp = new long[n + 1];
        dp[0] = 1; // empty target

        for (int pos = 0; pos < m; pos++) {
            // iterate target length backwards to avoid overwriting needed values
            for (int i = Math.min(n, pos + 1); i >= 1; i--) {
                char need = target.charAt(i - 1);
                int cnt = count[need - 'a'][pos];
                if (cnt > 0) {
                    dp[i] = (dp[i] + dp[i - 1] * cnt) % MOD;
                }
            }
        }

        return (int) dp[n];
    }
}

