import java.util.*;

public class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0] - 1;
            int v = e[1] - 1;
            graph[u].add(v);
            graph[v].add(u);
        }

        int[] answer = new int[n - 1];
        int totalMasks = 1 << n;

        for (int mask = 1; mask < totalMasks; mask++) {
            int bits = Integer.bitCount(mask);
            if (bits < 2) continue; // diameter at least 1

            // find any node in the subset
            int start = Integer.numberOfTrailingZeros(mask);

            // check connectivity within the subset
            if (!isConnected(mask, start, graph, n)) continue;

            // compute diameter using two BFS passes
            int farNode = bfsFarthest(start, mask, graph, n);
            int diameter = bfsDistance(farNode, mask, graph, n);
            // diameter is number of edges, which is at least 1 and at most n-1
            answer[diameter - 1]++;
        }

        return answer;
    }

    private boolean isConnected(int mask, int start, List<Integer>[] graph, int n) {
        boolean[] visited = new boolean[n];
        Deque<Integer> dq = new ArrayDeque<>();
        dq.add(start);
        visited[start] = true;
        int count = 0;

        while (!dq.isEmpty()) {
            int cur = dq.poll();
            if ((mask & (1 << cur)) == 0) continue;
            count++;
            for (int nb : graph[cur]) {
                if ((mask & (1 << nb)) != 0 && !visited[nb]) {
                    visited[nb] = true;
                    dq.add(nb);
                }
            }
        }
        return count == Integer.bitCount(mask);
    }

    // returns the node farthest from src within the subset (mask)
    private int bfsFarthest(int src, int mask, List<Integer>[] graph, int n) {
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        Deque<Integer> dq = new ArrayDeque<>();
        dq.add(src);
        dist[src] = 0;
        int farNode = src;

        while (!dq.isEmpty()) {
            int cur = dq.poll();
            for (int nb : graph[cur]) {
                if ((mask & (1 << nb)) != 0 && dist[nb] == -1) {
                    dist[nb] = dist[cur] + 1;
                    dq.add(nb);
                    if (dist[nb] > dist[farNode]) {
                        farNode = nb;
                    }
                }
            }
        }
        return farNode;
    }

    // returns the maximum distance from src within the subset (mask)
    private int bfsDistance(int src, int mask, List<Integer>[] graph, int n) {
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        Deque<Integer> dq = new ArrayDeque<>();
        dq.add(src);
        dist[src] = 0;
        int maxDist = 0;

        while (!dq.isEmpty()) {
            int cur = dq.poll();
            for (int nb : graph[cur]) {
                if ((mask & (1 << nb)) != 0 && dist[nb] == -1) {
                    dist[nb] = dist[cur] + 1;
                    dq.add(nb);
                    if (dist[nb] > maxDist) {
                        maxDist = dist[nb];
                    }
                }
            }
        }
        return maxDist;
    }
}

