import com_github_leetcode.ListNode;

public class Solution {
    public ListNode mergeInBetween(ListNode list1, int a, int b, ListNode list2) {
        // Find node before position a
        ListNode prev = null;
        ListNode curr = list1;
        for (int i = 0; i < a; i++) {
            prev = curr;
            curr = curr.next;
        }

        // Find node after position b
        ListNode after = curr;
        for (int i = a; i <= b; i++) {
            after = after.next;
        }

        // Connect prev to list2
        if (prev != null) {
            prev.next = list2;
        } else {
            // a == 0, new head will be list2
            list1 = list2;
        }

        // Find tail of list2
        ListNode tail = list2;
        while (tail != null && tail.next != null) {
            tail = tail.next;
        }

        // Connect tail to after
        if (tail != null) {
            tail.next = after;
        }

        return list1;
    }
}

