import java.util.HashSet;
import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public String findLexSmallestString(String s, int a, int b) {
        int n = s.length();
        String best = s;
        HashSet<String> visited = new HashSet<>();
        Queue<String> queue = new LinkedList<>();
        visited.add(s);
        queue.offer(s);
        while (!queue.isEmpty()) {
            String cur = queue.poll();
            if (cur.compareTo(best) < 0) {
                best = cur;
            }
            // operation 1: add a to all odd indices
            char[] added = cur.toCharArray();
            for (int i = 1; i < n; i += 2) {
                int digit = added[i] - '0';
                digit = (digit + a) % 10;
                added[i] = (char) ('0' + digit);
            }
            String nextAdd = new String(added);
            if (!visited.contains(nextAdd)) {
                visited.add(nextAdd);
                queue.offer(nextAdd);
            }
            // operation 2: rotate right by b positions
            int shift = b % n;
            String nextRotate = cur.substring(n - shift) + cur.substring(0, n - shift);
            if (!visited.contains(nextRotate)) {
                visited.add(nextRotate);
                queue.offer(nextRotate);
            }
        }
        return best;
    }
}

