public class Solution {
    public int[] decrypt(int[] code, int k) {
        int n = code.length;
        int[] result = new int[n];
        if (k == 0) {
            // all zeros already
            return result;
        }
        if (k > 0) {
            int window = 0;
            // initial sum of next k elements after index 0
            for (int i = 1; i <= k; i++) {
                window += code[i % n];
            }
            for (int i = 0; i < n; i++) {
                result[i] = window;
                // slide window: remove element that is just after i, add element after i+k
                int removeIdx = (i + 1) % n;
                int addIdx = (i + 1 + k) % n;
                window = window - code[removeIdx] + code[addIdx];
            }
        } else { // k < 0
            int kNeg = -k;
            int window = 0;
            // initial sum of previous kNeg elements before index 0
            for (int i = 1; i <= kNeg; i++) {
                window += code[(n - i) % n];
            }
            for (int i = 0; i < n; i++) {
                result[i] = window;
                // slide window: remove element that is (i - kNeg) and add element i
                int removeIdx = (i - kNeg + n) % n;
                int addIdx = i;
                window = window - code[removeIdx] + code[addIdx];
            }
        }
        return result;
    }
}

