import java.util.*;

public class Solution {
    private static class State {
        int position;
        boolean lastWasBackward;
        State(int position, boolean lastWasBackward) {
            this.position = position;
            this.lastWasBackward = lastWasBackward;
        }
    }

    public int minimumJumps(int[] forbidden, int a, int b, int x) {
        Set<Integer> forbiddenSet = new HashSet<>();
        int maxForbidden = 0;
        for (int f : forbidden) {
            forbiddenSet.add(f);
            maxForbidden = Math.max(maxForbidden, f);
        }

        // Upper bound for search space.
        int limit = Math.max(maxForbidden + a + b, x + a + b) + 1000;

        // visited[pos][0] -> arrived at pos with last jump not backward (or start)
        // visited[pos][1] -> arrived at pos with last jump backward
        boolean[][] visited = new boolean[limit + 1][2];

        Queue<State> queue = new LinkedList<>();
        queue.offer(new State(0, false));
        visited[0][0] = true;

        int steps = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                State cur = queue.poll();
                if (cur.position == x) {
                    return steps;
                }

                // Forward jump
                int forwardPos = cur.position + a;
                if (forwardPos <= limit && !forbiddenSet.contains(forwardPos) && !visited[forwardPos][0]) {
                    visited[forwardPos][0] = true;
                    queue.offer(new State(forwardPos, false));
                }

                // Backward jump (only if previous jump wasn't backward)
                if (!cur.lastWasBackward) {
                    int backwardPos = cur.position - b;
                    if (backwardPos >= 0 && !forbiddenSet.contains(backwardPos) && !visited[backwardPos][1]) {
                        visited[backwardPos][1] = true;
                        queue.offer(new State(backwardPos, true));
                    }
                }
            }
            steps++;
        }

        return -1; // unreachable
    }
}

