public class Solution {
    public int getMaximumGenerated(int n) {
        if (n == 0) {
            return 0;
        }
        int[] nums = new int[n + 1];
        nums[0] = 0;
        nums[1] = 1;
        int max = 1;
        for (int i = 1; 2 * i <= n; i++) {
            int evenIdx = 2 * i;
            nums[evenIdx] = nums[i];
            if (nums[evenIdx] > max) {
                max = nums[evenIdx];
            }
            int oddIdx = evenIdx + 1;
            if (oddIdx <= n) {
                nums[oddIdx] = nums[i] + nums[i + 1];
                if (nums[oddIdx] > max) {
                    max = nums[oddIdx];
                }
            }
        }
        return max;
    }
}

