public class Solution {
    public int waysToMakeFair(int[] nums) {
        int n = nums.length;
        long[] prefixEven = new long[n + 1];
        long[] prefixOdd = new long[n + 1];

        for (int i = 0; i < n; i++) {
            prefixEven[i + 1] = prefixEven[i];
            prefixOdd[i + 1] = prefixOdd[i];
            if ((i & 1) == 0) {
                prefixEven[i + 1] += nums[i];
            } else {
                prefixOdd[i + 1] += nums[i];
            }
        }

        long totalEven = prefixEven[n];
        long totalOdd = prefixOdd[n];
        int count = 0;

        for (int i = 0; i < n; i++) {
            long leftEven = prefixEven[i];
            long leftOdd = prefixOdd[i];
            long rightEven = totalEven - prefixEven[i + 1];
            long rightOdd = totalOdd - prefixOdd[i + 1];

            long newEven = leftEven + rightOdd;
            long newOdd = leftOdd + rightEven;

            if (newEven == newOdd) {
                count++;
            }
        }

        return count;
    }
}

