public class Solution {
    public boolean arrayStringsAreEqual(String[] word1, String[] word2) {
        int i = 0, j = 0;          // indices for word1 and word2 arrays
        int p = 0, q = 0;          // indices within the current strings
        while (i < word1.length && j < word2.length) {
            char c1 = word1[i].charAt(p);
            char c2 = word2[j].charAt(q);
            if (c1 != c2) {
                return false;
            }
            // move to next character in word1
            if (++p == word1[i].length()) {
                i++;
                p = 0;
            }
            // move to next character in word2
            if (++q == word2[j].length()) {
                j++;
                q = 0;
            }
        }
        // Both arrays should be fully traversed
        return i == word1.length && j == word2.length;
    }
}

