import java.util.LinkedList;
import java.util.Objects;
import java.util.Queue;

public class Solution {
    public int countStudents(int[] students, int[] sandwiches) {
        // Count how many students prefer each type of sandwich
        int[] prefCount = new int[2];
        for (int s : students) {
            prefCount[s]++;
        }

        // Process sandwiches in order
        for (int sandwich : sandwiches) {
            if (prefCount[sandwich] > 0) {
                // A student who likes this sandwich takes it
                prefCount[sandwich]--;
            } else {
                // No student wants this sandwich; remaining students cannot eat
                break;
            }
        }

        // Remaining students are those who couldn't eat
        return prefCount[0] + prefCount[1];
    }
}

