import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int minimumMountainRemovals(int[] nums) {
        int n = nums.length;
        int[] inc = new int[n];
        int[] dec = new int[n];

        List<Integer> tails = new ArrayList<>();

        // Longest Increasing Subsequence ending at each position
        for (int i = 0; i < n; i++) {
            int pos = lowerBound(tails, nums[i]);
            if (pos == tails.size()) {
                tails.add(nums[i]);
            } else {
                tails.set(pos, nums[i]);
            }
            inc[i] = pos + 1;
        }

        tails.clear();

        // Longest Decreasing Subsequence starting at each position
        for (int i = n - 1; i >= 0; i--) {
            int pos = lowerBound(tails, nums[i]);
            if (pos == tails.size()) {
                tails.add(nums[i]);
            } else {
                tails.set(pos, nums[i]);
            }
            dec[i] = pos + 1;
        }

        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            if (inc[i] > 1 && dec[i] > 1) {
                int len = inc[i] + dec[i] - 1;
                if (len > maxLen) {
                    maxLen = len;
                }
            }
        }

        return n - maxLen;
    }

    // Returns the first index where list.get(idx) >= target
    private int lowerBound(List<Integer> list, int target) {
        int left = 0;
        int right = list.size();
        while (left < right) {
            int mid = (left + right) >>> 1;
            if (list.get(mid) < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

