import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;
import java.util.TreeSet;

public class Solution {

    private static class Busy implements Comparable<Busy> {
        long endTime;
        int serverId;

        Busy(long endTime, int serverId) {
            this.endTime = endTime;
            this.serverId = serverId;
        }

        @Override
        public int compareTo(Busy other) {
            if (this.endTime != other.endTime) {
                return Long.compare(this.endTime, other.endTime);
            }
            return Integer.compare(this.serverId, other.serverId);
        }
    }

    public List<Integer> busiestServers(int k, int[] arrival, int[] load) {
        int n = arrival.length;
        int[] handled = new int[k];
        TreeSet<Integer> free = new TreeSet<>();
        for (int i = 0; i < k; i++) {
            free.add(i);
        }
        PriorityQueue<Busy> busy = new PriorityQueue<>();

        for (int i = 0; i < n; i++) {
            long curTime = arrival[i];

            // release servers that have finished
            while (!busy.isEmpty() && busy.peek().endTime <= curTime) {
                Busy b = busy.poll();
                free.add(b.serverId);
            }

            if (free.isEmpty()) {
                continue; // drop request
            }

            int target = i % k;
            Integer server = free.ceiling(target);
            if (server == null) {
                server = free.first();
            }

            // assign request
            free.remove(server);
            handled[server]++;
            busy.offer(new Busy(curTime + load[i], server));
        }

        int max = 0;
        for (int cnt : handled) {
            if (cnt > max) {
                max = cnt;
            }
        }

        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            if (handled[i] == max) {
                result.add(i);
            }
        }
        return result;
    }
}

