import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int minimumEffort(int[][] tasks) {
        // Sort tasks by (actual - minimum) in descending order
        Arrays.sort(tasks, new Comparator<int[]>() {
            @Override
            public int compare(int[] a, int[] b) {
                int diffA = a[0] - a[1];
                int diffB = b[0] - b[1];
                return Integer.compare(diffB, diffA); // descending
            }
        });

        long need = 0;      // minimal initial energy required
        long current = 0;   // net energy change after completing processed tasks

        for (int[] task : tasks) {
            int actual = task[0];
            int minimum = task[1];

            // Ensure we have enough energy to start this task
            if (need < minimum - current) {
                need = minimum - current;
            }

            // Update current net energy after finishing the task
            current += actual - minimum;
        }

        return (int) need;
    }
}

