public class Solution {
    public int stoneGameVI(int[] aliceValues, int[] bobValues) {
        int n = aliceValues.length;
        Integer[] indices = new Integer[n];
        for (int i = 0; i < n; i++) {
            indices[i] = i;
        }
        Arrays.sort(indices, (i, j) -> {
            int sumI = aliceValues[i] + bobValues[i];
            int sumJ = aliceValues[j] + bobValues[j];
            return Integer.compare(sumJ, sumI); // descending
        });

        long aliceScore = 0;
        long bobScore = 0;
        for (int turn = 0; turn < n; turn++) {
            int idx = indices[turn];
            if ((turn & 1) == 0) { // Alice's turn
                aliceScore += aliceValues[idx];
            } else { // Bob's turn
                bobScore += bobValues[idx];
            }
        }

        long diff = aliceScore - bobScore;
        if (diff > 0) return 1;
        if (diff < 0) return -1;
        return 0;
    }
}

