import java.util.*;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numberOfSets(int n, int k) {
        if (k == 0) return 1;
        if (k > n - 1) return 0; // impossible

        int[][] dp = new int[n + 1][k + 1];
        int[][] pref = new int[n + 1][k + 1];

        dp[0][0] = 1;
        pref[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            dp[i][0] = 1;
            pref[i][0] = (pref[i - 1][0] + dp[i][0]) % MOD;

            for (int j = 1; j <= k; j++) {
                long val = dp[i - 1][j];
                long add = pref[i - 1][j - 1];
                if (j == 1) {
                    // exclude the term where start index would be 0 (DP[0][0])
                    add = (add - 1 + MOD) % MOD;
                }
                val = (val + add) % MOD;
                dp[i][j] = (int) val;
                pref[i][j] = (pref[i - 1][j] + dp[i][j]) % MOD;
            }
        }
        return dp[n][k];
    }
}

