public class Solution {
    public int maximumRequests(int n, int[][] requests) {
        int m = requests.length;
        int max = 0;
        // Enumerate all subsets of requests
        for (int mask = 0; mask < (1 << m); mask++) {
            int[] delta = new int[n];
            int count = Integer.bitCount(mask);
            // Early skip if count cannot exceed current max
            if (count <= max) {
                continue;
            }
            for (int i = 0; i < m; i++) {
                if ((mask & (1 << i)) != 0) {
                    int from = requests[i][0];
                    int to = requests[i][1];
                    delta[from]--;
                    delta[to]++;
                }
            }
            boolean ok = true;
            for (int d : delta) {
                if (d != 0) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                max = count;
            }
        }
        return max;
    }
}

