import java.util.HashMap;
import java.util.Map;

public class Solution {
    private final Map<Integer, Integer> memo = new HashMap<>();

    public int minimumOneBitOperations(int n) {
        return dfs(n);
    }

    private int dfs(int n) {
        if (n == 0) {
            return 0;
        }
        if (memo.containsKey(n)) {
            return memo.get(n);
        }
        // find the position of the highest set bit (0‑based)
        int msbPos = 31 - Integer.numberOfLeadingZeros(n);
        int nextPowerMask = (1 << (msbPos + 1)) - 1; // 2^{msb+1} - 1
        int complement = nextPowerMask - n;
        int result = nextPowerMask - dfs(complement);
        memo.put(n, result);
        return result;
    }
}

