import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int minOperations(int[] nums, int x) {
        int total = 0;
        for (int num : nums) {
            total += num;
        }
        int target = total - x;
        if (target < 0) {
            return -1;
        }
        if (target == 0) {
            return nums.length;
        }

        Map<Integer, Integer> prefixIndex = new HashMap<>();
        prefixIndex.put(0, -1);
        int sum = 0;
        int maxLen = -1;

        for (int i = 0; i < nums.length; i++) {
            sum += nums[i];
            if (prefixIndex.containsKey(sum - target)) {
                int prevIndex = prefixIndex.get(sum - target);
                int len = i - prevIndex;
                if (len > maxLen) {
                    maxLen = len;
                }
            }
            // store earliest occurrence of this prefix sum
            if (!prefixIndex.containsKey(sum)) {
                prefixIndex.put(sum, i);
            }
        }

        return maxLen == -1 ? -1 : nums.length - maxLen;
    }
}

