import java.util.Arrays;

public class Solution {
    public int specialArray(int[] nums) {
        if (nums == null || nums.length == 0) {
            return -1;
        }
        Arrays.sort(nums);
        // sort ascending, then check from largest to smallest
        int n = nums.length;
        // iterate possible x from 1 to n
        for (int x = 1; x <= n; x++) {
            // number of elements >= x is n - first index where value >= x
            int idx = lowerBound(nums, x);
            int count = n - idx;
            if (count == x) {
                return x;
            }
        }
        return -1;
    }

    // binary search for first index with value >= target
    private int lowerBound(int[] arr, int target) {
        int left = 0, right = arr.length;
        while (left < right) {
            int mid = (left + right) >>> 1;
            if (arr[mid] >= target) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }
}

