public class Solution {
    public int minimumDeletions(String s) {
        int n = s.length();
        if (n == 0) return 0;

        // total number of 'a' characters in the string
        int totalA = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == 'a') totalA++;
        }

        int minDeletions = totalA; // delete all 'a's (split before first character)
        int bSeen = 0;   // number of 'b's encountered so far (to be deleted if they appear before split)
        int aSeen = 0;   // number of 'a's encountered so far

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == 'b') {
                bSeen++;
            } else { // c == 'a'
                aSeen++;
            }
            // deletions if split after position i (i.e., keep prefix [0..i] as is)
            // need to delete all 'b's in the prefix and all 'a's in the suffix
            int deletions = bSeen + (totalA - aSeen);
            if (deletions < minDeletions) {
                minDeletions = deletions;
            }
        }

        return minDeletions;
    }
}

