import java.util.Arrays;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int maxProfit(int[] inventory, int orders) {
        Arrays.sort(inventory);
        int n = inventory.length;
        long profit = 0;
        int i = n - 1;

        while (orders > 0 && i >= 0) {
            int cur = inventory[i];
            int next = (i > 0) ? inventory[i - 1] : 0;
            int count = n - i; // number of colors with at least 'cur' balls

            long diff = cur - next; // levels we can drop
            long totalBalls = diff * count; // balls we can sell if we drop to 'next'

            if (orders >= totalBalls) {
                // sell all balls down to 'next'
                long sum = sumRange(next + 1, cur); // sum of values from next+1 to cur
                profit = (profit + (sum % MOD) * count) % MOD;
                orders -= totalBalls;
                i--;
            } else {
                // sell only part of the levels
                long fullLevels = orders / count; // how many full decrements we can apply
                long remainder = orders % count;

                long high = cur;
                long low = cur - fullLevels + 1;
                long sumFull = sumRange(low, high); // sum of a full decrement sequence
                profit = (profit + (sumFull % MOD) * count) % MOD;

                // sell the remaining balls at the next value after fullLevels decrements
                long nextValue = cur - fullLevels;
                profit = (profit + (remainder % MOD) * (nextValue % MOD)) % MOD;

                orders = 0; // all orders fulfilled
            }
        }

        return (int) (profit % MOD);
    }

    // Helper to compute sum of integers from l to r inclusive (l <= r)
    private long sumRange(long l, long r) {
        long cnt = r - l + 1;
        return (l + r) * cnt / 2;
    }
}

