public class Solution {
    public String reformatNumber(String number) {
        // Remove spaces and dashes
        StringBuilder digits = new StringBuilder();
        for (char c : number.toCharArray()) {
            if (c >= '0' && c <= '9') {
                digits.append(c);
            }
        }

        StringBuilder result = new StringBuilder();
        int i = 0;
        int n = digits.length();

        while (n - i > 0) {
            int remaining = n - i;
            if (remaining > 4) {
                // take a block of 3
                result.append(digits, i, i + 3).append('-');
                i += 3;
            } else if (remaining == 4) {
                // two blocks of 2
                result.append(digits, i, i + 2).append('-');
                result.append(digits, i + 2, i + 4);
                i = n; // finished
            } else if (remaining == 3) {
                result.append(digits, i, i + 3);
                i = n;
            } else { // remaining == 2
                result.append(digits, i, i + 2);
                i = n;
            }
        }

        // Remove trailing dash if present (only possible when remaining >4 case loop ends with a dash)
        if (result.length() > 0 && result.charAt(result.length() - 1) == '-') {
            result.setLength(result.length() - 1);
        }

        return result.toString();
    }
}

