public class Solution {
    public int maxHeight(int[][] arr) {
        int n = arr.length;
        // Sort dimensions of each cuboid to allow rotation
        for (int[] cuboid : arr) {
            Arrays.sort(cuboid);
        }
        // Sort cuboids lexicographically by dimensions
        Arrays.sort(arr, (a, b) -> {
            if (a[0] != b[0]) return a[0] - b[0];
            if (a[1] != b[1]) return a[1] - b[1];
            return a[2] - b[2];
        });

        int[] dp = new int[n];
        int maxHeight = 0;

        for (int i = 0; i < n; i++) {
            dp[i] = arr[i][2]; // height of the i‑th cuboid alone
            for (int j = 0; j < i; j++) {
                if (arr[j][0] <= arr[i][0] &&
                    arr[j][1] <= arr[i][1] &&
                    arr[j][2] <= arr[i][2]) {
                    dp[i] = Math.max(dp[i], dp[j] + arr[i][2]);
                }
            }
            maxHeight = Math.max(maxHeight, dp[i]);
        }

        return maxHeight;
    }
}

