        int pairs = n / 2;
        int maxSum = 2 * limit;
        int[] diff = new int[maxSum + 2]; // extra space for high+1 index

        for (int i = 0; i < pairs; i++) {
            int a = nums[i];
            int b = nums[n - 1 - i];
            int sum = a + b;

            int low = Math.min(a, b) + 1;
            int high = Math.max(a, b) + limit;

            // One move possible in [low, high]
            diff[low] -= 1;
            diff[high + 1] += 1;

            // Zero moves for exact sum
            diff[sum] -= 1;
            diff[sum + 1] += 1;
        }

        int base = 2 * pairs; // default 2 moves for each pair
        int cur = 0;
        int result = Integer.MAX_VALUE;

        for (int s = 2; s <= maxSum; s++) {
            cur += diff[s];
            int moves = base + cur;
            if (moves < result) {
                result = moves;
            }
        }

        return result;
    }
}

