import java.util.*;

public class Solution {
    // count the characters of every sticker
    // For each character, save the sticker index which has this character
    public int minStickers(String[] stickers, String target) {
        int m = target.length();
        int n = stickers.length;
        // preprocess sticker character counts
        int[][] stickerCounts = new int[n][26];
        for (int i = 0; i < n; i++) {
            for (char c : stickers[i].toCharArray()) {
                stickerCounts[i][c - 'a']++;
            }
        }
        // target characters array
        char[] targetChars = target.toCharArray();

        int fullMask = (1 << m) - 1;
        int[] dp = new int[1 << m];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;

        for (int mask = 0; mask <= fullMask; mask++) {
            if (dp[mask] == Integer.MAX_VALUE) continue;
            // try each sticker
            for (int i = 0; i < n; i++) {
                int[] cnt = Arrays.copyOf(stickerCounts[i], 26);
                int newMask = mask;
                // try to cover uncovered positions
                for (int j = 0; j < m; j++) {
                    if ((newMask & (1 << j)) != 0) continue; // already covered
                    int idx = targetChars[j] - 'a';
                    if (cnt[idx] > 0) {
                        cnt[idx]--;
                        newMask |= (1 << j);
                    }
                }
                if (newMask != mask) {
                    dp[newMask] = Math.min(dp[newMask], dp[mask] + 1);
                }
            }
        }

        return dp[fullMask] == Integer.MAX_VALUE ? -1 : dp[fullMask];
    }
}

