public class Solution {
    public int[] maxSumOfThreeSubarrays(int[] nums, int k) {
        int n = nums.length;
        int m = n - k + 1; // number of possible windows
        int[] windowSum = new int[m];
        // compute sums of all windows of size k
        int sum = 0;
        for (int i = 0; i < k; i++) {
            sum += nums[i];
        }
        windowSum[0] = sum;
        for (int i = 1; i < m; i++) {
            sum += nums[i + k - 1] - nums[i - 1];
            windowSum[i] = sum;
        }

        // left[i] = index of max-sum window in [0..i]
        int[] left = new int[m];
        int bestIdx = 0;
        for (int i = 0; i < m; i++) {
            if (windowSum[i] > windowSum[bestIdx]) {
                bestIdx = i;
            }
            left[i] = bestIdx;
        }

        // right[i] = index of max-sum window in [i..m-1]
        int[] right = new int[m];
        bestIdx = m - 1;
        for (int i = m - 1; i >= 0; i--) {
            if (windowSum[i] >= windowSum[bestIdx]) { // >= to keep earlier index on tie
                bestIdx = i;
            }
            right[i] = bestIdx;
        }

        int maxTotal = -1;
        int[] answer = new int[3];
        // middle window starts at i, must leave at least k elements on each side
        for (int i = k; i <= m - k - 1; i++) {
            int l = left[i - k];
            int r = right[i + k];
            int total = windowSum[l] + windowSum[i] + windowSum[r];
            if (total > maxTotal) {
                maxTotal = total;
                answer[0] = l;
                answer[1] = i;
                answer[2] = r;
            } else if (total == maxTotal) {
                // lexicographically smaller check
                if (l < answer[0] ||
                    (l == answer[0] && (i < answer[1] ||
                    (i == answer[1] && r < answer[2])))) {
                    answer[0] = l;
                    answer[1] = i;
                    answer[2] = r;
                }
            }
        }
        return answer;
    }
}

