import java.util.List;
import java.util.PriorityQueue;
import java.util.Queue;
import java.util.LinkedList;
import java.util.Comparator;

public class Solution {
    private static class Tree {
        int height;
        int x;
        int y;
        Tree(int h, int x, int y) {
            this.height = h;
            this.x = x;
            this.y = y;
        }
    }

    public int cutOffTree(List<List<Integer>> forest) {
        if (forest == null || forest.isEmpty() || forest.get(0).isEmpty()) {
            return -1;
        }

        int rows = forest.size();
        int cols = forest.get(0).size();

        // Collect all trees and sort by height
        PriorityQueue<Tree> pq = new PriorityQueue<>(Comparator.comparingInt(t -> t.height));
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int val = forest.get(i).get(j);
                if (val > 1) {
                    pq.offer(new Tree(val, i, j));
                }
            }
        }

        int totalSteps = 0;
        int curX = 0, curY = 0;

        // If starting cell is blocked, impossible
        if (forest.get(0).get(0) == 0) {
            return -1;
        }

        while (!pq.isEmpty()) {
            Tree target = pq.poll();
            int steps = bfs(forest, curX, curY, target.x, target.y);
            if (steps == -1) {
                return -1;
            }
            totalSteps += steps;
            // cut the tree
            forest.get(target.x).set(target.y, 1);
            curX = target.x;
            curY = target.y;
        }

        return totalSteps;
    }

    private int bfs(List<List<Integer>> forest, int sx, int sy, int tx, int ty) {
        if (sx == tx && sy == ty) {
            return 0;
        }
        int rows = forest.size();
        int cols = forest.get(0).size();
        boolean[][] visited = new boolean[rows][cols];
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{sx, sy, 0});
        visited[sx][sy] = true;

        int[] dx = {-1, 0, 1, 0};
        int[] dy = {0, 1, 0, -1};

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int x = cur[0];
            int y = cur[1];
            int dist = cur[2];

            for (int dir = 0; dir < 4; dir++) {
                int nx = x + dx[dir];
                int ny = y + dy[dir];
                if (nx < 0 || ny < 0 || nx >= rows || ny >= cols) {
                    continue;
                }
                if (visited[nx][ny]) {
                    continue;
                }
                if (forest.get(nx).get(ny) == 0) {
                    continue;
                }
                if (nx == tx && ny == ty) {
                    return dist + 1;
                }
                visited[nx][ny] = true;
                queue.offer(new int[]{nx, ny, dist + 1});
            }
        }
        return -1; // unreachable
    }
}

