public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numDecodings(String s) {
        int n = s.length();
        long[] dp = new long[n + 1];
        dp[0] = 1; // empty string

        for (int i = 1; i <= n; i++) {
            char cur = s.charAt(i - 1);

            // Single character decoding
            if (cur == '*') {
                dp[i] = (dp[i] + 9L * dp[i - 1]) % MOD;
            } else if (cur != '0') {
                dp[i] = (dp[i] + dp[i - 1]) % MOD;
            }

            // Two‑character decoding
            if (i >= 2) {
                char prev = s.charAt(i - 2);

                if (prev == '*') {
                    if (cur == '*') {
                        // 11‑19 and 21‑26
                        dp[i] = (dp[i] + 15L * dp[i - 2]) % MOD;
                    } else {
                        // prev can be '1' or '2'
                        if (cur >= '0' && cur <= '6') {
                            dp[i] = (dp[i] + 2L * dp[i - 2]) % MOD;
                        } else {
                            dp[i] = (dp[i] + dp[i - 2]) % MOD;
                        }
                    }
                } else if (prev == '1') {
                    if (cur == '*') {
                        // 11‑19
                        dp[i] = (dp[i] + 9L * dp[i - 2]) % MOD;
                    } else {
                        // 10‑19
                        dp[i] = (dp[i] + dp[i - 2]) % MOD;
                    }
                } else if (prev == '2') {
                    if (cur == '*') {
                        // 21‑26
                        dp[i] = (dp[i] + 6L * dp[i - 2]) % MOD;
                    } else if (cur >= '0' && cur <= '6') {
                        // 20‑26
                        dp[i] = (dp[i] + dp[i - 2]) % MOD;
                    }
                }
                // prev other digits ('0' or '3'‑'9') give no valid two‑digit decode
            }
        }

        return (int) dp[n];
    }
}

