public class Solution {
    public int findKthNumber(int m, int n, int k) {
        long low = 1;
        long high = (long) m * n;
        while (low < high) {
            long mid = low + (high - low) / 2;
            if (countLessOrEqual(mid, m, n) >= k) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return (int) low;
    }

    private long countLessOrEqual(long x, int m, int n) {
        long count = 0;
        for (int i = 1; i <= m; i++) {
            count += Math.min(n, x / i);
        }
        return count;
    }
}

