import java.util.List;

public class Solution {
    private static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        String word = null; // stores the root word when this node marks end of a root
    }

    private final TrieNode root = new TrieNode();

    private void insert(String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) {
                node.children[idx] = new TrieNode();
            }
            node = node.children[idx];
        }
        // store the root word; if multiple same prefixes, keep the shortest (first inserted)
        if (node.word == null) {
            node.word = word;
        }
    }

    private String replace(String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) {
                break;
            }
            node = node.children[idx];
            if (node.word != null) {
                return node.word; // shortest prefix found
            }
        }
        return word;
    }

    public String replaceWords(List<String> dictionary, String sentence) {
        // Build trie from dictionary
        for (String rootWord : dictionary) {
            if (rootWord != null && !rootWord.isEmpty()) {
                insert(rootWord);
            }
        }

        StringBuilder sb = new StringBuilder();
        int n = sentence.length();
        StringBuilder currentWord = new StringBuilder();

        for (int i = 0; i <= n; i++) {
            char ch = i < n ? sentence.charAt(i) : ' ';
            if (ch == ' ') {
                if (currentWord.length() > 0) {
                    String replaced = replace(currentWord.toString());
                    sb.append(replaced);
                    currentWord.setLength(0);
                }
                if (i < n) {
                    sb.append(' ');
                }
            } else {
                currentWord.append(ch);
            }
        }

        return sb.toString();
    }
}

