import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.TreeSet;

public class Solution {
    private int[] segMax;
    private int[] lazy;
    private int n; // number of elementary intervals

    private void pushDown(int node) {
        if (lazy[node] != -1) {
            int leftChild = node << 1;
            int rightChild = leftChild | 1;
            segMax[leftChild] = lazy[node];
            segMax[rightChild] = lazy[node];
            lazy[leftChild] = lazy[node];
            lazy[rightChild] = lazy[node];
            lazy[node] = -1;
        }
    }

    private int query(int node, int l, int r, int ql, int qr) {
        if (ql > r || qr < l) {
            return 0;
        }
        if (ql <= l && r <= qr) {
            return segMax[node];
        }
        pushDown(node);
        int mid = (l + r) >>> 1;
        int left = query(node << 1, l, mid, ql, qr);
        int right = query(node << 1 | 1, mid + 1, r, ql, qr);
        return Math.max(left, right);
    }

    private void update(int node, int l, int r, int ul, int ur, int val) {
        if (ul > r || ur < l) {
            return;
        }
        if (ul <= l && r <= ur) {
            segMax[node] = val;
            lazy[node] = val;
            return;
        }
        pushDown(node);
        int mid = (l + r) >>> 1;
        update(node << 1, l, mid, ul, ur, val);
        update(node << 1 | 1, mid + 1, r, ul, ur, val);
        segMax[node] = Math.max(segMax[node << 1], segMax[node << 1 | 1]);
    }

    public List<Integer> fallingSquares(int[][] positions) {
        // coordinate compression
        TreeSet<Integer> set = new TreeSet<>();
        for (int[] p : positions) {
            int left = p[0];
            int size = p[1];
            set.add(left);
            set.add(left + size);
        }
        List<Integer> xs = new ArrayList<>(set);
        int m = xs.size();
        if (m == 0) {
            return new ArrayList<>();
        }
        // number of elementary intervals is m-1
        n = m - 1;
        segMax = new int[4 * n];
        lazy = new int[4 * n];
        for (int i = 0; i < lazy.length; i++) {
            lazy[i] = -1;
        }

        HashMap<Integer, Integer> idxMap = new HashMap<>();
        for (int i = 0; i < xs.size(); i++) {
            idxMap.put(xs.get(i), i);
        }

        List<Integer> ans = new ArrayList<>();
        int globalMax = 0;

        for (int[] p : positions) {
            int left = p[0];
            int size = p[1];
            int l = idxMap.get(left);
            int r = idxMap.get(left + size) - 1; // inclusive interval index
            if (l > r) { // zero width, should not happen
                r = l;
            }
            int cur = query(1, 0, n - 1, l, r);
            int newHeight = cur + size;
            update(1, 0, n - 1, l, r, newHeight);
            globalMax = Math.max(globalMax, newHeight);
            ans.add(globalMax);
        }
        return ans;
    }
}

