public class Solution {
    private static final int MOD = 1_000_000_007;

    public int kInversePairs(int n, int k) {
        // dp[i][j] = number of arrays of length i with exactly j inverse pairs
        int[][] dp = new int[2][k + 1];
        dp[0][0] = 1; // length 0, 0 inversions

        for (int i = 1; i <= n; i++) {
            int cur = i & 1;
            int prev = cur ^ 1;
            dp[cur][0] = 1; // only one way to have 0 inversions (sorted array)

            for (int j = 1; j <= k; j++) {
                long val = dp[cur][j - 1] + dp[prev][j];
                if (j >= i) {
                    val -= dp[prev][j - i];
                }
                val %= MOD;
                if (val < 0) {
                    val += MOD;
                }
                dp[cur][j] = (int) val;
            }
        }
        return dp[n & 1][k];
    }
}

