public class Solution {
    public List<TreeNode> findDuplicateSubtrees(TreeNode root) {
        List<TreeNode> result = new ArrayList<>();
        Map<String, Integer> countMap = new HashMap<>();
        serialize(root, countMap, result);
        return result;
    }

    private String serialize(TreeNode node, Map<String, Integer> countMap, List<TreeNode> result) {
        if (node == null) {
            return "#";
        }
        String left = serialize(node.left, countMap, result);
        String right = serialize(node.right, countMap, result);
        String key = node.val + "," + left + "," + right;

        int cnt = countMap.getOrDefault(key, 0);
        if (cnt == 1) { // second time we see this subtree, add to result
            result.add(node);
        }
        countMap.put(key, cnt + 1);
        return key;
    }
}

