                        counts[i] = counts[j];
                    } else if (lengths[j] + 1 == lengths[i]) {
                        counts[i] += counts[j];
                    }
                }
            }
            if (lengths[i] > longest) {
                longest = lengths[i];
                result = counts[i];
            } else if (lengths[i] == longest) {
                result += counts[i];
            }
        }
        return result;
    }
}

