        int steps = 0;
        int divisor = 2;
        while (n > 1) {
            while (n % divisor == 0) {
                steps += divisor;
                n /= divisor;
            }
            divisor++;
            // No need to go beyond sqrt of current n
            if (divisor * divisor > n) {
                if (n > 1) {
                    steps += n;
                    break;
                }
            }
        }
        return steps;
