public class Solution {
    public String solveEquation(String equation) {
        String[] sides = equation.split("=");
        int[] left = parseSide(sides[0]);
        int[] right = parseSide(sides[1]);

        // bring all to left side: (leftCoeff - rightCoeff) * x = (rightConst - leftConst)
        int coeff = left[0] - right[0];
        int constant = right[1] - left[1];

        if (coeff == 0) {
            if (constant == 0) {
                return "Infinite solutions";
            } else {
                return "No solution";
            }
        } else {
            int x = constant / coeff;
            return "x=" + x;
        }
    }

    // returns int[2] where [0] = coefficient of x, [1] = constant term
    private int[] parseSide(String s) {
        int coeff = 0;
        int constant = 0;
        int i = 0;
        int n = s.length();
        int sign = 1; // current sign

        while (i < n) {
            char ch = s.charAt(i);
            if (ch == '+') {
                sign = 1;
                i++;
            } else if (ch == '-') {
                sign = -1;
                i++;
            } else {
                int num = 0;
                boolean isNumber = false;
                while (i < n && Character.isDigit(s.charAt(i))) {
                    isNumber = true;
                    num = num * 10 + (s.charAt(i) - '0');
                    i++;
                }
                if (i < n && s.charAt(i) == 'x') {
                    // term with x
                    if (!isNumber) {
                        num = 1; // implicit 1
                    }
                    coeff += sign * num;
                    i++; // skip 'x'
                } else {
                    // constant term
                    constant += sign * num;
                }
                // after processing a term, reset sign to positive for next iteration
                sign = 1;
            }
        }
        return new int[]{coeff, constant};
    }
}

