import java.util.*;

public class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        int[] parent = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            parent[i] = i;
        }

        int[] candidate1 = null; // first edge causing two parents
        int[] candidate2 = null; // second edge causing two parents
        int[] indegreeParent = new int[n + 1]; // store the first parent of each node

        // Step 1: find a node with two parents (if any)
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            if (indegreeParent[v] != 0) {
                // node v already has a parent
                candidate1 = new int[]{indegreeParent[v], v};
                candidate2 = new int[]{u, v};
                // mark this edge to be ignored later
            } else {
                indegreeParent[v] = u;
            }
        }

        // Union-Find initialization
        for (int i = 1; i <= n; i++) {
            parent[i] = i;
        }

        // Helper functions for Union-Find
        class UF {
            int find(int x) {
                if (parent[x] != x) {
                    parent[x] = find(parent[x]);
                }
                return parent[x];
            }

            boolean union(int x, int y) {
                int rootX = find(x);
                int rootY = find(y);
                if (rootX == rootY) {
                    return false; // cycle detected
                }
                parent[rootY] = rootX;
                return true;
            }
        }

        UF uf = new UF();

        // Step 2: process edges, skipping candidate2 if it exists
        for (int[] edge : edges) {
            if (candidate2 != null && edge[0] == candidate2[0] && edge[1] == candidate2[1]) {
                continue; // skip the second edge of the node with two parents
            }
            int u = edge[0];
            int v = edge[1];
            if (!uf.union(u, v)) {
                // Cycle detected
                if (candidate1 == null) {
                    // No node with two parents, so this edge creates the cycle
                    return edge;
                } else {
                    // Node with two parents exists, the first edge is the culprit
                    return candidate1;
                }
            }
        }

        // If we reach here, there was a node with two parents but no cycle
        // The second edge is the one to remove
        return candidate2;
    }
}

