public class Solution {
    public int repeatedStringMatch(String a, String b) {
        if (b.isEmpty()) {
            return 0;
        }
        if (a.isEmpty()) {
            return -1;
        }

        int repeat = (b.length() + a.length() - 1) / a.length(); // ceil division
        StringBuilder sb = new StringBuilder();

        // try repeat times
        sb.setLength(0);
        for (int i = 0; i < repeat; i++) {
            sb.append(a);
        }
        if (sb.indexOf(b) != -1) {
            return repeat;
        }

        // try one more repetition
        sb.append(a);
        if (sb.indexOf(b) != -1) {
            return repeat + 1;
        }

        return -1;
    }
}

