        build(t, sb);
        return sb.toString();
    }

    private void build(TreeNode node, StringBuilder sb) {
        if (node == null) {
            return;
        }
        sb.append(node.val);
        if (node.left == null && node.right == null) {
            return;
        }
        sb.append('(');
        if (node.left != null) {
            build(node.left, sb);
        }
        sb.append(')');
        if (node.right != null) {
            sb.append('(');
            build(node.right, sb);
            sb.append(')');
        }
    }
}

