import java.util.List;
import java.util.Objects;
import java.util.PriorityQueue;
import java.util.Comparator;

public class Solution {

    private static class Node {
        int value;
        int row;
        int col;

        Node(int value, int row, int col) {
            this.value = value;
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Finds the smallest range that includes at least one number from each of the k sorted lists.
     *
     * @param nums a list containing k sorted integer lists
     * @return an int array of size 2 where result[0] is the start of the range and result[1] is the end
     */
    public int[] smallestRange(List<List<Integer>> nums) {
        Objects.requireNonNull(nums, "Input list cannot be null");
        int k = nums.size();
        if (k == 0) {
            return new int[0];
        }

        PriorityQueue<Node> minHeap = new PriorityQueue<>(Comparator.comparingInt(a -> a.value));
        int currentMax = Integer.MIN_VALUE;

        // Initialize heap with the first element of each list
        for (int i = 0; i < k; i++) {
            List<Integer> list = nums.get(i);
            if (list == null || list.isEmpty()) {
                // If any list is empty, no valid range exists
                return new int[0];
            }
            int val = list.get(0);
            minHeap.offer(new Node(val, i, 0));
            if (val > currentMax) {
                currentMax = val;
            }
        }

        int bestStart = 0;
        int bestEnd = Integer.MAX_VALUE;
        int bestLen = bestEnd - bestStart;

        while (true) {
            Node minNode = minHeap.poll();
            int currentMin = minNode.value;

            // Update best range if needed
            int currentLen = currentMax - currentMin;
            if (currentLen < bestLen || (currentLen == bestLen && currentMin < bestStart)) {
                bestStart = currentMin;
                bestEnd = currentMax;
                bestLen = currentLen;
            }

            // Move to the next element in the list from which the min element was taken
            if (minNode.col + 1 == nums.get(minNode.row).size()) {
                // One of the lists is exhausted; cannot find a better range
                break;
            }

            int nextCol = minNode.col + 1;
            int nextVal = nums.get(minNode.row).get(nextCol);
            minHeap.offer(new Node(nextVal, minNode.row, nextCol));
            if (nextVal > currentMax) {
                currentMax = nextVal;
            }
        }

        return new int[]{bestStart, bestEnd};
    }
}

