import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    private final Map<String, Integer> memo = new HashMap<>();

    public int shoppingOffers(List<Integer> price, List<List<Integer>> special, List<Integer> needs) {
        return dfs(price, special, needs);
    }

    private int dfs(List<Integer> price, List<List<Integer>> special, List<Integer> needs) {
        String key = encode(needs);
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        // Cost without any special offer
        int minCost = 0;
        for (int i = 0; i < price.size(); i++) {
            minCost += price.get(i) * needs.get(i);
        }

        // Try every special offer
        for (List<Integer> offer : special) {
            List<Integer> nextNeeds = new ArrayList<>(needs.size());
            boolean valid = true;
            for (int i = 0; i < needs.size(); i++) {
                int remain = needs.get(i) - offer.get(i);
                if (remain < 0) {
                    valid = false;
                    break;
                }
                nextNeeds.add(remain);
            }
            if (!valid) {
                continue;
            }
            int offerPrice = offer.get(offer.size() - 1);
            int costWithOffer = offerPrice + dfs(price, special, nextNeeds);
            if (costWithOffer < minCost) {
                minCost = costWithOffer;
            }
        }

        memo.put(key, minCost);
        return minCost;
    }

    private String encode(List<Integer> needs) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < needs.size(); i++) {
            sb.append(needs.get(i));
            if (i < needs.size() - 1) {
                sb.append('#');
            }
        }
        return sb.toString();
    }
}

