import java.util.Arrays;

public class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        if (k <= 0) return false;
        int n = nums.length;
        int total = 0;
        for (int num : nums) total += num;
        if (total % k != 0) return false;
        int target = total / k;
        Arrays.sort(nums);
        // sort descending for pruning
        for (int i = 0; i < n / 2; i++) {
            int tmp = nums[i];
            nums[i] = nums[n - 1 - i];
            nums[n - 1 - i] = tmp;
        }
        if (nums[0] > target) return false;

        int fullMask = (1 << n) - 1;
        int[] memo = new int[1 << n]; // -1 unknown, 0 false, 1 true
        Arrays.fill(memo, -1);

        return dfs(nums, target, 0, 0, fullMask, memo);
    }

    private boolean dfs(int[] nums, int target, int usedMask, int curSum, int fullMask, int[] memo) {
        if (usedMask == fullMask) {
            // all numbers are used, last bucket must also be valid
            return true;
        }
        if (memo[usedMask] != -1) {
            return memo[usedMask] == 1;
        }

        int n = nums.length;
        // try to place next unused number
        for (int i = 0; i < n; i++) {
            int bit = 1 << i;
            if ((usedMask & bit) != 0) continue; // already used
            int nextSum = curSum + nums[i];
            if (nextSum > target) continue; // exceeds bucket sum

            int nextMask = usedMask | bit;
            if (nextSum == target) {
                // bucket completed, start a new bucket from sum 0
                if (dfs(nums, target, nextMask, 0, fullMask, memo)) {
                    memo[usedMask] = 1;
                    return true;
                }
            } else {
                // continue filling current bucket
                if (dfs(nums, target, nextMask, nextSum, fullMask, memo)) {
                    memo[usedMask] = 1;
                    return true;
                }
            }
        }

        memo[usedMask] = 0;
        return false;
    }
}

