public class Solution {
    public List<Integer> findClosestElements(int[] arr, int k, int x) {
        int n = arr.length;
        int low = 0;
        int high = n - k; // inclusive start index range

        while (low < high) {
            int mid = low + (high - low) / 2;
            // Compare distances between x and the two border elements of the window
            int leftDist = Math.abs(x - arr[mid]);
            int rightDist = Math.abs(arr[mid + k] - x);
            if (leftDist > rightDist) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }

        List<Integer> result = new ArrayList<>(k);
        for (int i = low; i < low + k; i++) {
            result.add(arr[i]);
        }
        return result;
    }
}

