public class Solution {
    public List<List<String>> printTree(TreeNode root) {
        int height = getHeight(root);
        int rows = height + 1;
        int cols = (1 << (height + 1)) - 1; // 2^(height+1) - 1

        List<List<String>> res = new ArrayList<>(rows);
        for (int i = 0; i < rows; i++) {
            List<String> row = new ArrayList<>(cols);
            for (int j = 0; j < cols; j++) {
                row.add("");
            }
            res.add(row);
        }

        fill(root, 0, 0, cols - 1, res);
        return res;
    }

    private int getHeight(TreeNode node) {
        if (node == null) {
            return -1; // height of empty tree is -1 so that a single node has height 0
        }
        return 1 + Math.max(getHeight(node.left), getHeight(node.right));
    }

    private void fill(TreeNode node, int row, int left, int right, List<List<String>> res) {
        if (node == null) {
            return;
        }
        int mid = left + (right - left) / 2;
        res.get(row).set(mid, Integer.toString(node.val));
        fill(node.left, row + 1, left, mid - 1, res);
        fill(node.right, row + 1, mid + 1, right, res);
    }
}

