public class Solution {

    private static class Pair {
        TreeNode node;
        long idx;

        Pair(TreeNode node, long idx) {
            this.node = node;
            this.idx = idx;
        }
    }

    public int widthOfBinaryTree(TreeNode root) {
        if (root == null) {
            return 0;
        }
        Queue<Pair> queue = new LinkedList<>();
        queue.offer(new Pair(root, 0L));
        int maxWidth = 0;

        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            long levelStart = queue.peek().idx; // reference to normalize indices
            long first = 0, last = 0;

            for (int i = 0; i < levelSize; i++) {
                Pair cur = queue.poll();
                long curIdx = cur.idx - levelStart; // keep numbers small

                if (i == 0) {
                    first = curIdx;
                }
                if (i == levelSize - 1) {
                    last = curIdx;
                }

                if (cur.node.left != null) {
                    queue.offer(new Pair(cur.node.left, curIdx * 2 + 1));
                }
                if (cur.node.right != null) {
                    queue.offer(new Pair(cur.node.right, curIdx * 2 + 2));
                }
            }

            int width = (int) (last - first + 1);
            if (width > maxWidth) {
                maxWidth = width;
            }
        }

        return maxWidth;
    }
}

