            strNums[i] = String.valueOf(nums[i]);
        }
        Comparator<String> comp = (a, b) -> (b + a).compareTo(a + b);
        Arrays.sort(strNums, comp);
        if (strNums[0].equals("0")) {
            return "0";
        }
        StringBuilder sb = new StringBuilder();
        for (String s : strNums) {
            sb.append(s);
        }
        return sb.toString();
    }
}

