import com_github_leetcode.Node;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Queue;

public class Solution {
    public Node cloneGraph(Node node) {
        if (node == null) {
            return null;
        }

        // Map original node reference to its clone
        Map<Node, Node> visited = new HashMap<>();

        // Initialize BFS
        Queue<Node> queue = new ArrayDeque<>();
        queue.add(node);
        visited.put(node, new Node(node.val, new ArrayList<>()));

        while (!queue.isEmpty()) {
            Node current = queue.poll();
            Node currentClone = visited.get(current);

            for (Node neighbor : current.neighbors) {
                if (!visited.containsKey(neighbor)) {
                    // Clone neighbor and add to map
                    visited.put(neighbor, new Node(neighbor.val, new ArrayList<>()));
                    queue.add(neighbor);
                }
                // Add the cloned neighbor to the current node's clone neighbor list
                currentClone.neighbors.add(visited.get(neighbor));
            }
        }

        return visited.get(node);
    }
}

