import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int maxPoints(int[][] points) {
        if (points == null) return 0;
        int n = points.length;
        if (n <= 2) return n;

        int result = 0;
        for (int i = 0; i < n; i++) {
            Map<String, Integer> slopeCount = new HashMap<>();
            int duplicates = 1; // count the point itself
            int curMax = 0;

            int xi = points[i][0];
            int yi = points[i][1];

            for (int j = i + 1; j < n; j++) {
                int xj = points[j][0];
                int yj = points[j][1];

                int dx = xj - xi;
                int dy = yj - yi;

                if (dx == 0 && dy == 0) {
                    // same point
                    duplicates++;
                } else {
                    int g = gcd(dx, dy);
                    dx /= g;
                    dy /= g;

                    // keep sign consistent: make dx positive; if dx == 0, make dy positive
                    if (dx < 0) {
                        dx = -dx;
                        dy = -dy;
                    } else if (dx == 0) {
                        dy = Math.abs(dy);
                    }

                    String key = dy + "/" + dx;
                    int count = slopeCount.getOrDefault(key, 0) + 1;
                    slopeCount.put(key, count);
                    curMax = Math.max(curMax, count);
                }
            }
            result = Math.max(result, curMax + duplicates);
        }
        return result;
    }

    private int gcd(int a, int b) {
        if (a == 0) return Math.abs(b);
        if (b == 0) return Math.abs(a);
        a = Math.abs(a);
        b = Math.abs(b);
        while (b != 0) {
            int tmp = a % b;
            a = b;
            b = tmp;
        }
        return a;
    }
}

