        for (int row = 0; row < m; row++) {
            if (board[row][0] == 'O') {
                bfs(board, row, 0);
            }
            if (board[row][n - 1] == 'O') {
                bfs(board, row, n - 1);
            }
        }

        // Flip the cells to final state
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'O') {
                    board[i][j] = 'X';
                } else if (board[i][j] == '#') {
                    board[i][j] = 'O';
                }
            }
        }
    }

    private void bfs(char[][] board, int startRow, int startCol) {
        int m = board.length;
        int n = board[0].length;
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startRow, startCol});
        board[startRow][startCol] = '#';

        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};

        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int r = cur[0];
            int c = cur[1];
            for (int[] d : dirs) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && board[nr][nc] == 'O') {
                    board[nr][nc] = '#';
                    stack.push(new int[]{nr, nc});
                }
            }
        }
    }
}

