import java.util.*;

public class Solution {
    public int minCut(String s) {
        if (s == null || s.length() <= 1) {
            return 0;
        }
        int n = s.length();
        int[] cuts = new int[n];
        for (int i = 0; i < n; i++) {
            cuts[i] = i; // maximum cuts
        }

        for (int center = 0; center < n; center++) {
            // odd length palindromes
            for (int left = center, right = center;
                 left >= 0 && right < n && s.charAt(left) == s.charAt(right);
                 left--, right++) {
                if (left == 0) {
                    cuts[right] = 0;
                } else {
                    cuts[right] = Math.min(cuts[right], cuts[left - 1] + 1);
                }
            }

            // even length palindromes
            for (int left = center - 1, right = center;
                 left >= 0 && right < n && s.charAt(left) == s.charAt(right);
                 left--, right++) {
                if (left == 0) {
                    cuts[right] = 0;
                } else {
                    cuts[right] = Math.min(cuts[right], cuts[left - 1] + 1);
                }
            }
        }

        return cuts[n - 1];
    }
}

