public class Solution {
    public int rob(int[] nums) {
        if (nums == null || nums.length == 0) {
            return 0;
        }
        int n = nums.length;
        if (n == 1) {
            return nums[0];
        }
        int prevTwo = nums[0];
        int prevOne = Math.max(nums[0], nums[1]);
        for (int i = 2; i < n; i++) {
            int current = Math.max(prevOne, prevTwo + nums[i]);
            prevTwo = prevOne;
            prevOne = current;
        }
        return prevOne;
    }
}

