import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Solution {
    public List<String> findRepeatedDnaSequences(String s) {
        List<String> result = new ArrayList<>();
        if (s == null || s.length() < 10) {
            return result;
        }

        // Encode each nucleotide with 2 bits: A=00, C=01, G=10, T=11
        final int MASK = (1 << 20) - 1; // keep only last 20 bits (10 chars * 2 bits)
        Set<Integer> seen = new HashSet<>();
        Set<Integer> added = new HashSet<>();

        int hash = 0;
        for (int i = 0; i < 10; i++) {
            hash = (hash << 2) | encode(s.charAt(i));
        }
        seen.add(hash);

        for (int i = 10; i < s.length(); i++) {
            // slide window: shift left 2 bits, add new char, keep only 20 bits
            hash = ((hash << 2) & MASK) | encode(s.charAt(i));
            if (seen.contains(hash)) {
                if (!added.contains(hash)) {
                    result.add(s.substring(i - 9, i + 1));
                    added.add(hash);
                }
            } else {
                seen.add(hash);
            }
        }

        return result;
    }

    private int encode(char c) {
        // A -> 0, C -> 1, G -> 2, T -> 3
        return switch (c) {
            case 'A' -> 0;
            case 'C' -> 1;
            case 'G' -> 2;
            case 'T' -> 3;
            default -> 0; // should not happen for valid DNA strings
        };
    }
}

