import com_github_leetcode.ListNode;

public class Solution {
    public ListNode getIntersectionNode(ListNode headA, ListNode headB) {
        if (headA == null || headB == null) {
            return null;
        }

        // Compute lengths of both lists
        int lenA = 0, lenB = 0;
        ListNode currA = headA;
        ListNode currB = headB;
        while (currA != null) {
            lenA++;
            currA = currA.next;
        }
        while (currB != null) {
            lenB++;
            currB = currB.next;
        }

        // Align the start pointers
        currA = headA;
        currB = headB;
        if (lenA > lenB) {
            int diff = lenA - lenB;
            while (diff-- > 0) {
                currA = currA.next;
            }
        } else if (lenB > lenA) {
            int diff = lenB - lenA;
            while (diff-- > 0) {
                currB = currB.next;
            }
        }

        // Move together until they meet or reach the end
        while (currA != null && currB != null) {
            if (currA == currB) {
                return currA;
            }
            currA = currA.next;
            currB = currB.next;
        }

        return null;
    }
}

