import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Set;

public class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> wordSet = new HashSet<>(wordList);
        if (!wordSet.contains(endWord)) {
            return new ArrayList<>();
        }

        Map<String, List<String>> parents = new HashMap<>();
        Queue<String> queue = new LinkedList<>();
        Set<String> visited = new HashSet<>();

        queue.add(beginWord);
        visited.add(beginWord);
        boolean found = false;

        while (!queue.isEmpty() && !found) {
            int size = queue.size();
            Set<String> thisLevelVisited = new HashSet<>();

            for (int i = 0; i < size; i++) {
                String word = queue.poll();
                char[] chars = word.toCharArray();

                for (int pos = 0; pos < chars.length; pos++) {
                    char original = chars[pos];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == original) continue;
                        chars[pos] = c;
                        String next = new String(chars);
                        if (!wordSet.contains(next)) continue;

                        if (!visited.contains(next)) {
                            if (!thisLevelVisited.contains(next)) {
                                queue.add(next);
                                thisLevelVisited.add(next);
                            }
                            parents.computeIfAbsent(next, k -> new ArrayList<>()).add(word);
                        } else if (thisLevelVisited.contains(next)) {
                            parents.computeIfAbsent(next, k -> new ArrayList<>()).add(word);
                        }

                        if (next.equals(endWord)) {
                            found = true;
                        }
                    }
                    chars[pos] = original;
                }
            }
            visited.addAll(thisLevelVisited);
        }

        if (!found) {
            return new ArrayList<>();
        }

        List<List<String>> results = new ArrayList<>();
        List<String> path = new ArrayList<>();
        path.add(endWord);
        dfs(endWord, beginWord, parents, path, results);
        return results;
    }

    private void dfs(String word, String begin,
                     Map<String, List<String>> parents,
                     List<String> path,
                     List<List<String>> results) {
        if (word.equals(begin)) {
            List<String> list = new ArrayList<>(path);
            Collections.reverse(list);
            results.add(list);
            return;
        }
        List<String> preds = parents.get(word);
        if (preds == null) return;
        for (String p : preds) {
            path.add(p);
            dfs(p, begin, parents, path, results);
            path.remove(path.size() - 1);
        }
    }
}

