import com_github_leetcode.random.Node;

public class Solution {
    public Node copyRandomList(Node head) {
        if (head == null) {
            return null;
        }

        // First pass: create cloned nodes and interleave them with original nodes
        Node current = head;
        while (current != null) {
            Node cloned = new Node(current.val);
            cloned.next = current.next;
            current.next = cloned;
            current = cloned.next;
        }

        // Second pass: assign random pointers for the cloned nodes
        current = head;
        while (current != null) {
            if (current.random != null) {
                current.next.random = current.random.next;
            }
            current = current.next.next;
        }

        // Third pass: separate the cloned list from the original list
        Node dummy = new Node(0);
        Node copyTail = dummy;
        current = head;
        while (current != null) {
            Node cloned = current.next;
            copyTail.next = cloned;
            copyTail = cloned;

            current.next = cloned.next;
            current = current.next;
        }

        return dummy.next;
    }
}

