import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        // Sort arr2 and remove duplicates
        Arrays.sort(arr2);
        int[] uniq = new int[arr2.length];
        int u = 0;
        for (int v : arr2) {
            if (u == 0 || v != uniq[u - 1]) {
                uniq[u++] = v;
            }
        }
        uniq = Arrays.copyOf(uniq, u);
        // dp maps the last value of the processed prefix to the minimal operations used
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(Integer.MIN_VALUE, 0); // sentinel previous value
        for (int a : arr1) {
            Map<Integer, Integer> ndp = new HashMap<>();
            for (Map.Entry<Integer, Integer> e : dp.entrySet()) {
                int prev = e.getKey();
                int ops = e.getValue();
                // Keep current element if it keeps the sequence strictly increasing
                if (a > prev) {
                    ndp.merge(a, ops, Math::min);
                }
                // Replace with the smallest element in arr2 that is greater than prev
                int idx = Arrays.binarySearch(uniq, prev + 1);
                if (idx < 0) {
                    idx = -idx - 1;
                }
                if (idx < uniq.length) {
                    int val = uniq[idx];
                    ndp.merge(val, ops + 1, Math::min);
                }
            }
            dp = ndp;
            if (dp.isEmpty()) {
                return -1; // no possible sequences any more
            }
        }
        int ans = Integer.MAX_VALUE;
        for (int v : dp.values()) {
            ans = Math.min(ans, v);
        }
        return ans == Integer.MAX_VALUE ? -1 : ans;
    }
}

