public class Solution {
    public int maximumSum(int[] arr) {
        int n = arr.length;
        if (n == 0) {
            return 0;
        }
        // forward[i] = max subarray sum ending at i (no deletion)
        int[] forward = new int[n];
        // backward[i] = max subarray sum starting at i (no deletion)
        int[] backward = new int[n];

        forward[0] = arr[0];
        int maxAns = arr[0];
        for (int i = 1; i < n; i++) {
            forward[i] = Math.max(arr[i], forward[i - 1] + arr[i]);
            maxAns = Math.max(maxAns, forward[i]); // no deletion case
        }

        backward[n - 1] = arr[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            backward[i] = Math.max(arr[i], backward[i + 1] + arr[i]);
        }

        // consider deletion of each element
        for (int i = 1; i < n - 1; i++) {
            int combined = forward[i - 1] + backward[i + 1];
            maxAns = Math.max(maxAns, combined);
        }

        // deletion at the boundaries (if array length > 1)
        if (n > 1) {
            maxAns = Math.max(maxAns, backward[1]);      // delete first element
            maxAns = Math.max(maxAns, forward[n - 2]);   // delete last element
        }

        return maxAns;
    }
}

