import java.util.ArrayList;
import java.util.List;

public class Solution {

    private static class Pair {
        char c;
        int count;

        Pair(char c, int count) {
            this.c = c;
            this.count = count;
        }
    }

    /**
     * Returns the length of the longest substring consisting of the same character
     * that can be obtained by swapping any two characters in the given string.
     *
     * @param text the input string consisting of lowercase English letters
     * @return the maximum possible length of a repeated‑character substring after at most one swap
     */
    public int longestRepeatedSubstring(String text) {
        int n = text.length();
        if (n == 0) {
            return 0;
        }

        // total occurrences of each character
        int[] total = new int[26];
        for (int i = 0; i < n; i++) {
            total[text.charAt(i) - 'a']++;
        }

        // compress the string into blocks of consecutive identical characters
        List<Pair> blocks = new ArrayList<>();
        int i = 0;
        while (i < n) {
            char ch = text.charAt(i);
            int j = i;
            while (j < n && text.charAt(j) == ch) {
                j++;
            }
            blocks.add(new Pair(ch, j - i));
            i = j;
        }

        int max = 0;

        // case 1: extend a single block by swapping in one more same character from elsewhere
        for (Pair block : blocks) {
            int len = block.count;
            if (total[block.c - 'a'] > len) {
                len++; // we can bring one more of the same character
            }
            max = Math.max(max, len);
        }

        // case 2: merge two blocks separated by a single different character
        for (int idx = 0; idx < blocks.size() - 2; idx++) {
            Pair left = blocks.get(idx);
            Pair middle = blocks.get(idx + 1);
            Pair right = blocks.get(idx + 2);

            if (middle.count == 1 && left.c == right.c) {
                int combined = left.count + right.count;
                if (total[left.c - 'a'] > combined) {
                    combined++; // we can bring an extra character of the same type
                }
                max = Math.max(max, combined);
            }
        }

        return max;
    }
