public class Solution {
    public int maxDistance(int[][] grid) {
        int n = grid.length;
        if (n == 0) return -1;

        int[][] dist = new int[n][n];
        Queue<int[]> q = new LinkedList<>();

        // Initialize distances and queue with all land cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    dist[i][j] = 0;
                    q.offer(new int[]{i, j});
                } else {
                    dist[i][j] = -1; // unvisited water
                }
            }
        }

        // If there is no land or no water, return -1
        if (q.isEmpty() || q.size() == n * n) {
            return -1;
        }

        int maxDist = -1;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0];
            int c = cur[1];
            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n && dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[r][c] + 1;
                    maxDist = Math.max(maxDist, dist[nr][nc]);
                    q.offer(new int[]{nr, nc});
                }
            }
        }

        return maxDist;
    }
}

