        if (node == null) {
            return null;
        }
        boolean toDelete = delSet.contains(node.val);
        if (isRoot && !toDelete) {
            forest.add(node);
        }
        node.left = dfs(node.left, delSet, forest, toDelete);
        node.right = dfs(node.right, delSet, forest, toDelete);
        return toDelete ? null : node;
    }
}

