public class Solution {
    public int movesToMakeZigzag(int[] nums) {
        int n = nums.length;
        long movesEvenPeak = 0; // pattern: even indices are peaks, odd are valleys
        long movesOddPeak = 0;  // pattern: odd indices are peaks, even are valleys

        for (int i = 0; i < n; i++) {
            int left = i > 0 ? nums[i - 1] : Integer.MAX_VALUE;
            int right = i + 1 < n ? nums[i + 1] : Integer.MAX_VALUE;
            int minNeighbor = Math.min(left, right);

            if (i % 2 == 0) {
                // even index should be peak in movesEvenPeak, valley in movesOddPeak
                // For movesEvenPeak (even peak) no change needed here.
                // For movesOddPeak (even valley) ensure nums[i] < minNeighbor
                if (nums[i] >= minNeighbor) {
                    movesOddPeak += (long) nums[i] - minNeighbor + 1;
                }
            } else {
                // odd index should be valley in movesEvenPeak, peak in movesOddPeak
                // For movesEvenPeak (odd valley) ensure nums[i] < minNeighbor
                if (nums[i] >= minNeighbor) {
                    movesEvenPeak += (long) nums[i] - minNeighbor + 1;
                }
                // For movesOddPeak (odd peak) no change needed here.
            }
        }

        return (int) Math.min(movesEvenPeak, movesOddPeak);
    }
}

