        // sentinel to avoid empty checks
        stack.push(Integer.MAX_VALUE);
        int cost = 0;
        for (int num : arr) {
            // maintain increasing order in stack
            while (stack.peek() <= num) {
                int mid = stack.pop();
                int left = stack.peek();
                cost += mid * Math.min(left, num);
            }
            stack.push(num);
        }
        // combine remaining elements
        while (stack.size() > 2) { // more than sentinel + one element
            int mid = stack.pop();
            cost += mid * stack.peek();
        }
        return cost;
    }
}

