import java.util.*;

public class Solution {
    public int stoneGameII(int[] piles) {
        int n = piles.length;
        int[] suffix = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            suffix[i] = suffix[i + 1] + piles[i];
        }
        // dp[i][M] where M ranges from 1..n (inclusive). Use -1 for uncomputed.
        int[][] memo = new int[n][n + 1];
        for (int[] row : memo) {
            Arrays.fill(row, -1);
        }
        return dfs(0, 1, n, suffix, memo);
    }

    private int dfs(int i, int M, int n, int[] suffix, int[][] memo) {
        if (i >= n) {
            return 0;
        }
        if (memo[i][M] != -1) {
            return memo[i][M];
        }
        int maxTake = Math.min(2 * M, n - i);
        int best = 0;
        for (int x = 1; x <= maxTake; x++) {
            int nextM = Math.max(M, x);
            int opponent = dfs(i + x, nextM, n, suffix, memo);
            int current = suffix[i] - opponent;
            if (current > best) {
                best = current;
            }
        }
        memo[i][M] = best;
        return best;
    }
}

