import java.util.*;

public class Solution {
    public int longestWPI(int[] hours) {
        int n = hours.length;
        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + (hours[i] > 8 ? 1 : -1);
        }

        // Build a monotonic decreasing stack of indices
        int[] stack = new int[n + 1];
        int top = -1;
        for (int i = 0; i <= n; i++) {
            if (top == -1 || prefix[i] < prefix[stack[top]]) {
                stack[++top] = i;
            }
        }

        int longest = 0;
        // Scan from the end to find the farthest index with larger prefix sum
        for (int i = n; i >= 0; i--) {
            while (top >= 0 && prefix[i] > prefix[stack[top]]) {
                longest = Math.max(longest, i - stack[top]);
                top--;
            }
        }
        return longest;
    }
}

