import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

public class Solution {
    public boolean parseBoolExpr(String expression) {
        Deque<Character> stack = new ArrayDeque<>();
        for (char ch : expression.toCharArray()) {
            if (ch == ')') {
                // collect values inside the current parentheses
                List<Character> values = new ArrayList<>();
                while (stack.peek() != '(') {
                    char c = stack.pop();
                    if (c == 't' || c == 'f') {
                        values.add(c);
                    }
                    // commas are ignored
                }
                // remove '('
                stack.pop();
                // operator is just before '('
                char op = stack.pop();

                char result;
                if (op == '!') {
                    // NOT has exactly one operand
                    result = (values.get(0) == 't') ? 'f' : 't';
                } else if (op == '&') {
                    // AND: true only if all are true
                    result = 't';
                    for (char v : values) {
                        if (v == 'f') {
                            result = 'f';
                            break;
                        }
                    }
                } else { // op == '|'
                    // OR: true if any is true
                    result = 'f';
                    for (char v : values) {
                        if (v == 't') {
                            result = 't';
                            break;
                        }
                    }
                }
                stack.push(result);
            } else if (ch != ',') {
                // push all other characters except commas
                stack.push(ch);
            }
        }
        // final result is the only element left on the stack
        return stack.pop() == 't';
    }
}

