public class Solution {
    public String lastSubstring(String s) {
        int n = s.length();
        int i = 0; // candidate start
        int j = 1; // competitor start
        int k = 0; // offset for comparison

        while (j + k < n) {
            char a = s.charAt(i + k);
            char b = s.charAt(j + k);
            if (a == b) {
                k++;
                continue;
            }
            if (a < b) {
                // competitor is better, move i forward
                i = i + k + 1;
                if (i <= j) {
                    i = j + 1;
                }
            } else {
                // candidate is better, move j forward
                j = j + k + 1;
                if (j <= i) {
                    j = i + 1;
                }
            }
            k = 0;
        }

        int start = Math.min(i, j);
        return s.substring(start);
    }
}

