import java.util.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    private long kadane(int[] arr) {
        long maxSoFar = 0;
        long cur = 0;
        for (int value : arr) {
            cur = Math.max(0, cur + value);
            maxSoFar = Math.max(maxSoFar, cur);
        }
        return maxSoFar;
    }

    private long kadaneTwoCopies(int[] arr) {
        long maxSoFar = 0;
        long cur = 0;
        int n = arr.length;
        for (int i = 0; i < 2 * n; i++) {
            int value = arr[i % n];
            cur = Math.max(0, cur + value);
            maxSoFar = Math.max(maxSoFar, cur);
        }
        return maxSoFar;
    }

    public int kConcatenationMaxSum(int[] arr, int k) {
        if (arr == null || arr.length == 0 || k <= 0) {
            return 0;
        }

        long totalSum = 0;
        for (int v : arr) {
            totalSum += v;
        }

        long maxSingle = kadane(arr);

        if (k == 1) {
            return (int) (maxSingle % MOD);
        }

        long maxTwo = kadaneTwoCopies(arr);
        long result;

        if (totalSum > 0) {
            long candidate = maxSingle + totalSum * (k - 1);
            result = Math.max(maxTwo, candidate);
        } else {
            result = maxTwo;
        }

        result %= MOD;
        return (int) result;
    }
}

