public class Solution {
    private static class Transaction {
        String name;
        int time;
        int amount;
        String city;
        String original;
        int index;

        Transaction(String s, int idx) {
            this.original = s;
            this.index = idx;
            String[] parts = s.split(",");
            this.name = parts[0];
            this.time = Integer.parseInt(parts[1]);
            this.amount = Integer.parseInt(parts[2]);
            this.city = parts[3];
        }
    }

    public List<String> invalidTransactions(String[] transactions) {
        int n = transactions.length;
        Transaction[] trans = new Transaction[n];
        for (int i = 0; i < n; i++) {
            trans[i] = new Transaction(transactions[i], i);
        }

        boolean[] invalid = new boolean[n];

        // Map name -> list of indices
        Map<String, List<Integer>> byName = new HashMap<>();
        for (int i = 0; i < n; i++) {
            byName.computeIfAbsent(trans[i].name, k -> new ArrayList<>()).add(i);
        }

        for (int i = 0; i < n; i++) {
            // Rule 1: amount > 1000
            if (trans[i].amount > 1000) {
                invalid[i] = true;
            }

            // Rule 2: same name, different city, within 60 minutes
            List<Integer> sameNameList = byName.get(trans[i].name);
            for (int j : sameNameList) {
                if (i == j) continue;
                if (!trans[i].city.equals(trans[j].city) && Math.abs(trans[i].time - trans[j].time) <= 60) {
                    invalid[i] = true;
                    invalid[j] = true;
                }
            }
        }

        List<String> result = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (invalid[i]) {
                result.add(trans[i].original);
            }
        }
        return result;
    }
}

