import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        List<Integer> path = new ArrayList<>();
        int current = label;
        while (current >= 1) {
            path.add(current);
            if (current == 1) {
                break;
            }
            int level = 32 - Integer.numberOfLeadingZeros(current);
            // Convert current label to its "normal" (left‑to‑right) value
            int normal;
            if ((level & 1) == 0) { // even level: reversed
                int start = 1 << (level - 1);
                int end = (1 << level) - 1;
                normal = end - (current - start);
            } else {
                normal = current;
            }
            // Parent in normal ordering
            int parentNormal = normal / 2;
            int parentLevel = level - 1;
            // Convert parent back to zigzag label
            if ((parentLevel & 1) == 0 && parentLevel > 0) { // even level: reversed
                int start = 1 << (parentLevel - 1);
                int end = (1 << parentLevel) - 1;
                current = end - (parentNormal - start);
            } else {
                current = parentNormal;
            }
        }
        Collections.reverse(path);
        return path;
    }
}

