public class Solution {
    public int[] relativeSortArray(int[] arr1, int[] arr2) {
        // Counting sort based solution
        int[] count = new int[1001]; // assuming values are in the range [0,1000]
        for (int num : arr1) {
            count[num]++;
        }

        int index = 0;
        // Place elements according to the order in arr2
        for (int num : arr2) {
            while (count[num] > 0) {
                arr1[index++] = num;
                count[num]--;
