import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public List<Integer> findNumOfValidWords(String[] words, String[] puzzles) {
        // Frequency map of word bitmasks
        Map<Integer, Integer> freq = new HashMap<>();
        for (String word : words) {
            int mask = 0;
            for (int i = 0; i < word.length(); i++) {
                mask |= 1 << (word.charAt(i) - 'a');
            }
            // Optional optimization: ignore words with more than 7 distinct letters
            if (Integer.bitCount(mask) <= 7) {
                freq.put(mask, freq.getOrDefault(mask, 0) + 1);
            }
        }

        List<Integer> answer = new ArrayList<>(puzzles.length);
        for (String puzzle : puzzles) {
            int firstBit = 1 << (puzzle.charAt(0) - 'a');
            int puzzleMask = 0;
            for (int i = 0; i < puzzle.length(); i++) {
                puzzleMask |= 1 << (puzzle.charAt(i) - 'a');
            }

            int subMask = puzzleMask;
            int count = 0;
            // Enumerate all subsets of puzzleMask that contain the first letter
            while (subMask != 0) {
                if ((subMask & firstBit) != 0) {
                    count += freq.getOrDefault(subMask, 0);
                }
                subMask = (subMask - 1) & puzzleMask;
            }
            answer.add(count);
        }
        return answer;
    }
}

