public class Solution {
    public int largest1BorderedSquare(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return 0;
        }
        int m = grid.length;
        int n = grid[0].length;
        int[][] right = new int[m][n];
        int[][] down = new int[m][n];

        // Fill right and down arrays
        for (int i = m - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (grid[i][j] == 1) {
                    right[i][j] = 1 + (j + 1 < n ? right[i][j + 1] : 0);
                    down[i][j] = 1 + (i + 1 < m ? down[i + 1][j] : 0);
                } else {
                    right[i][j] = 0;
                    down[i][j] = 0;
                }
            }
        }

        int maxSize = 0;
        // Iterate over all possible top-left corners
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                // The maximum possible size from this cell
                int possible = Math.min(right[i][j], down[i][j]);
                // Try from largest possible down to current maxSize+1
                for (int size = possible; size > maxSize; size--) {
                    // Check bottom border and right border
                    if (right[i + size - 1][j] >= size && down[i][j + size - 1] >= size) {
                        maxSize = size;
                        break; // no need to try smaller sizes for this cell
                    }
                }
            }
        }
        return maxSize * maxSize;
    }
}

