public class Solution {
    public int longestDecomposition(String text) {
        return decompose(text, 0, text.length() - 1);
    }

    private int decompose(String s, int left, int right) {
        if (left > right) {
            return 0;
        }
        if (left == right) {
            return 1;
        }

        int maxK = 1; // at least the whole middle part as one piece
        // try to find the smallest matching prefix and suffix
        for (int len = 1; left + len - 1 < right - len + 1; len++) {
            // compare s[left, left+len) with s[right-len+1, right+1)
            if (s.regionMatches(left, s, right - len + 1, len)) {
                // found a matching pair
                return 2 + decompose(s, left + len, right - len);
            }
        }
        // no matching pair found, the whole remaining substring is one piece
        return maxK;
    }
}

