            redAdj[e[0]].add(e[1]);
        }
        for (int[] e : blueEdges) {
            blueAdj[e[0]].add(e[1]);
        }

        // distances[node][color] : shortest distance to node ending with given color edge
        int INF = Integer.MAX_VALUE / 2;
        int[][] dist = new int[n][2];
        for (int i = 0; i < n; i++) {
            dist[i][0] = INF;
            dist[i][1] = INF;
        }
        // start node 0 can be considered reached with 0 steps regardless of last color
        dist[0][0] = 0;
        dist[0][1] = 0;

        Queue<int[]> q = new LinkedList<>();
        // push both possibilities for starting node
        q.offer(new int[]{0, 0}); // last edge red (virtual)
        q.offer(new int[]{0, 1}); // last edge blue (virtual)

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int node = cur[0];
            int lastColor = cur[1];
            int nextColor = 1 - lastColor; // must alternate

            List<Integer>[] nextAdj = (nextColor == 0) ? redAdj : blueAdj;
            for (int nei : nextAdj[node]) {
                if (dist[nei][nextColor] == INF) {
                    dist[nei][nextColor] = dist[node][lastColor] + 1;
                    q.offer(new int[]{nei, nextColor});
                }
            }
        }

        int[] answer = new int[n];
        for (int i = 0; i < n; i++) {
            int best = Math.min(dist[i][0], dist[i][1]);
            answer[i] = (best == INF) ? -1 : best;
        }
        return answer;
    }
}

