import com_github_leetcode.ListNode;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public ListNode removeZeroSumSublists(ListNode head) {
        // Dummy node to handle deletions at the head
        ListNode dummy = new ListNode(0);
        dummy.next = head;

        // First pass: record the last occurrence of each prefix sum
        Map<Integer, ListNode> prefixMap = new HashMap<>();
        int sum = 0;
        for (ListNode node = dummy; node != null; node = node.next) {
            sum += node.val;
            prefixMap.put(sum, node);
        }

        // Second pass: skip nodes that are part of zero-sum sequences
        sum = 0;
        for (ListNode node = dummy; node != null; node = node.next) {
            sum += node.val;
            ListNode lastNodeWithSameSum = prefixMap.get(sum);
            if (lastNodeWithSameSum != node) {
                node.next = lastNodeWithSameSum.next;
            }
        }

        return dummy.next;
    }
}

