public class Solution {
    public int[] distributeCandies(int candies, int numPeople) {
        int[] distribution = new int[numPeople];
        int give = 1;
        int index = 0;
        while (candies > 0) {
            int giveNow = Math.min(give, candies);
            distribution[index] += giveNow;
