import java.util.Arrays;

public class Solution {
    private int frequencyOfSmallestChar(String s) {
        char minChar = 'z' + 1;
        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < minChar) {
                minChar = c;
                count = 1;
            } else if (c == minChar) {
                count++;
            }
        }
        return count;
    }

    public int[] numSmallerByFrequency(String[] queries, String[] words) {
        int n = words.length;
        int[] wordFreq = new int[n];
        for (int i = 0; i < n; i++) {
            wordFreq[i] = frequencyOfSmallestChar(words[i]);
        }
        Arrays.sort(wordFreq);

        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int qFreq = frequencyOfSmallestChar(queries[i]);
            int idx = upperBound(wordFreq, qFreq);
            answer[i] = n - idx;
        }
        return answer;
    }

    // Returns first index where value > target (i.e., upper bound)
    private int upperBound(int[] arr, int target) {
        int left = 0, right = arr.length;
        while (left < right) {
            int mid = (left + right) >>> 1;
            if (arr[mid] <= target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

