public class Solution {
    public int distanceBetweenBusStops(int[] distance, int start, int destination) {
        int n = distance.length;
        // Ensure start is the smaller index for easier calculation, but not required.
        // Compute clockwise distance from start to destination.
        int clockwise = 0;
        int i = start;
        while (i != destination) {
            clockwise += distance[i];
            i = (i + 1) % n;
        }
        // Total distance around the circle.
        int total = 0;
        for (int d : distance) {
            total += d;
        }
        // Shortest distance is the minimum of clockwise and counter‑clockwise.
        return Math.min(clockwise, total - clockwise);
    }
}

