import java.util.ArrayList;
import java.util.List;

public class Solution {
    private List<List<Integer>> bridges;
    private List<Integer>[] graph;
    private int[] disc;
    private int[] low;
    private int time;

    public List<List<Integer>> criticalConnections(int n, List<List<Integer>> connections) {
        // initialize structures
        bridges = new ArrayList<>();
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (List<Integer> edge : connections) {
            int u = edge.get(0);
            int v = edge.get(1);
            graph[u].add(v);
            graph[v].add(u);
        }

        disc = new int[n];
        low = new int[n];
        for (int i = 0; i < n; i++) {
            disc[i] = -1; // unvisited
        }
        time = 0;

        // run DFS from any node (graph is connected)
        dfs(0, -1);

        return bridges;
    }

    private void dfs(int u, int parent) {
        disc[u] = low[u] = time++;
        for (int v : graph[u]) {
            if (v == parent) {
                continue; // skip the edge leading back to parent
            }
            if (disc[v] == -1) { // not visited
                dfs(v, u);
                // after visiting v, update low[u]
                low[u] = Math.min(low[u], low[v]);
                // check if the edge u-v is a bridge
                if (low[v] > disc[u]) {
                    List<Integer> bridge = new ArrayList<>(2);
                    bridge.add(u);
                    bridge.add(v);
                    bridges.add(bridge);
                }
            } else {
                // back edge
                low[u] = Math.min(low[u], disc[v]);
            }
        }
    }
}

