import java.util.*;

public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        Arrays.sort(sums);
        List<Integer> current = new ArrayList<>();
        for (int s : sums) current.add(s);
        List<Integer> answer = new ArrayList<>();

        while (answer.size() < n) {
            int diff = current.get(1) - current.get(0); // absolute value of the next element
            Map<Integer, Integer> count = new HashMap<>();
            for (int v : current) {
                count.put(v, count.getOrDefault(v, 0) + 1);
            }

            List<Integer> without = new ArrayList<>();
            List<Integer> with = new ArrayList<>();

            for (int v : current) {
                int c = count.getOrDefault(v, 0);
                if (c == 0) continue;
                // v belongs to the group without the element
                without.add(v);
                count.put(v, c - 1);

                int paired = v + diff;
                count.put(paired, count.get(paired) - 1);
                with.add(paired);
            }

            if (without.contains(0)) {
                answer.add(diff);
                current = without;
            } else {
                answer.add(-diff);
                current = with;
            }
        }

        int[] res = new int[n];
        for (int i = 0; i < n; i++) {
            res[i] = answer.get(i);
        }
        return res;
    }
}

