public class Solution {
    public boolean canBeIncreasing(int[] nums) {
        int n = nums.length;
        if (n <= 2) {
            return true;
        }
        int violations = 0;
        int idx = -1;
        for (int i = 1; i < n; i++) {
            if (nums[i] <= nums[i - 1]) {
                violations++;
                idx = i;
                if (violations > 1) {
                    return false;
                }
            }
        }
        if (violations == 0) {
            return true;
        }
        // One violation at idx
        // Check if removing nums[idx] or nums[idx-1] fixes the sequence
        boolean removeCurrent = (idx == 1) || (nums[idx] > nums[idx - 2]);
        boolean removePrev = (idx == n - 1) || (nums[idx + 1] > nums[idx - 1]);
        return removeCurrent && removePrev;
    }
}

