import java.util.*;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numberOfUniqueGoodSubsequences(String binary) {
        long[] dp = new long[2];          // dp[0] – distinct good subsequences ending with '0'
                                          // dp[1] – distinct good subsequences ending with '1'
        boolean hasZero = false;          // we need to add the subsequence "0" at most once

        for (char ch : binary.toCharArray()) {
            int idx = ch - '0';
            if (idx == 0) {
                hasZero = true;
                // any good subsequence (including empty) can be extended with '0',
                // but the only valid good subsequence that ends with '0' is "0" itself.
                // Therefore we keep dp[0] as 1 (if a zero has appeared) and do not
                // create longer strings that would have a leading zero.
                dp[0] = 1;
            } else { // ch == '1'
                // new distinct subsequences ending with '1' are formed by appending
                // this '1' to every existing good subsequence (including empty).
                // To avoid duplicates we subtract the previous count of subsequences
                // that already ended with '1' before the last occurrence of '1'.
                long newEnd1 = (dp[0] + dp[1] + 1) % MOD;
                dp[1] = newEnd1;
            }
        }

        long result = (dp[0] + dp[1]) % MOD;
        // dp[0] may be 0 if there was no '0' in the string; we have already counted it
        // as part of dp[0] when a zero appears, so no extra addition is needed.
        return (int) result;
    }
}

