public class Solution {
    public long maxMatrixSum(int[][] matrix) {
        long sumAbs = 0L;
        int negativeCount = 0;
        int minAbs = Integer.MAX_VALUE;

        for (int[] row : matrix) {
            for (int val : row) {
                int absVal = Math.abs(val);
                sumAbs += absVal;
                if (val < 0) {
                    negativeCount++;
                }
                if (absVal < minAbs) {
                    minAbs = absVal;
                }
            }
        }

        if ((negativeCount & 1) == 1) {
            sumAbs -= 2L * minAbs;
        }

        return sumAbs;
    }
