import java.util.*;

public class Solution {
    public int[][] rotateGrid(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int layers = Math.min(m, n) / 2;

        for (int layer = 0; layer < layers; layer++) {
            int top = layer;
            int bottom = m - 1 - layer;
            int left = layer;
            int right = n - 1 - layer;

            List<Integer> elems = new ArrayList<>();

            // down the left side
            for (int i = top; i < bottom; i++) {
                elems.add(grid[i][left]);
            }
            // right along the bottom
            for (int j = left; j < right; j++) {
                elems.add(grid[bottom][j]);
            }
            // up the right side
            for (int i = bottom; i > top; i--) {
                elems.add(grid[i][right]);
            }
            // left along the top
            for (int j = right; j > left; j--) {
                elems.add(grid[top][j]);
            }

            int len = elems.size();
            int rot = k % len;
            if (rot == 0) continue;

            int[] rotated = new int[len];
            for (int i = 0; i < len; i++) {
                rotated[(i + rot) % len] = elems.get(i);
            }

            int idx = 0;
            // write back down the left side
            for (int i = top; i < bottom; i++) {
                grid[i][left] = rotated[idx++];
            }
            // write back right along the bottom
            for (int j = left; j < right; j++) {
                grid[bottom][j] = rotated[idx++];
            }
            // write back up the right side
            for (int i = bottom; i > top; i--) {
                grid[i][right] = rotated[idx++];
            }
            // write back left along the top
            for (int j = right; j > left; j--) {
                grid[top][j] = rotated[idx++];
            }
        }

        return grid;
    }
}

package referenz;


import java.util.*;

public class Solution {
    public int[] longestObstacleCourseAtEachPosition(int[] obstacles) {
        int n = obstacles.length;
        int[] ans = new int[n];
        List<Integer> tails = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int x = obstacles[i];
            int pos = upperBound(tails, x);
            if (pos == tails.size()) {
                tails.add(x);
            } else {
                tails.set(pos, x);
            }
            ans[i] = pos + 1;
        }
        return ans;
    }

    private int upperBound(List<Integer> list, int target) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (list.get(mid) <= target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

package referenz;


public class Solution {
    public int[] findPeakGrid(int[][] mat) {
        int m = mat.length;
        int n = mat[0].length;
        int left = 0;
        int right = n - 1;

        while (left <= right) {
            int midCol = left + (right - left) / 2;

            // Find the row index of the maximum element in midCol
            int maxRow = 0;
            for (int i = 1; i < m; i++) {
                if (mat[i][midCol] > mat[maxRow][midCol]) {
                    maxRow = i;
                }
            }

            int leftVal = (midCol - 1 >= 0) ? mat[maxRow][midCol - 1] : -1;
            int rightVal = (midCol + 1 < n) ? mat[maxRow][midCol + 1] : -1;

            if (mat[maxRow][midCol] > leftVal && mat[maxRow][midCol] > rightVal) {
                // Peak found
                return new int[]{maxRow, midCol};
            } else if (leftVal > mat[maxRow][midCol]) {
                // Move to the left half
                right = midCol - 1;
            } else {
                // Move to the right half
                left = midCol + 1;
            }
        }

        // Should never reach here because a peak always exists
        return new int[]{-1, -1};
    }
}

package referenz;


import java.util.*;

public class Solution {
    public int maxProductDifference(int[] nums) {
        // Initialize max values to smallest possible and min values to largest possible
        int max1 = Integer.MIN_VALUE, max2 = Integer.MIN_VALUE;
        int min1 = Integer.MAX_VALUE, min2 = Integer.MAX_VALUE;

        for (int num : nums) {
            // Update max values
            if (num > max1) {
                max2 = max1;
                max1 = num;
            } else if (num > max2) {
                max2 = num;
            }

            // Update min values
            if (num < min1) {
                min2 = min1;
                min1 = num;
            } else if (num < min2) {
                min2 = num;
            }
        }

        long productMax = (long) max1 * max2;
        long productMin = (long) min1 * min2;
        return (int) (productMax - productMin);
    }
}
